parameter N = 8; // number of bits used to represent the LO phase

reg [15:0] lo_i;
reg [15:0] lo_q;
reg [15:0] phase_i;
reg [15:0] phase_q;
reg [15:0] i_signal;
reg [15:0] q_signal;
reg [15:0] mod_signal;
reg [15:0] demod_signal;

// Quadrature modulator
always @(posedge clk) begin
  if (reset) begin
    lo_i <= 0;
    lo_q <= 0;
    phase_i <= 0;
    phase_q <= 0;
    i_signal <= 0;
    q_signal <= 0;
    mod_signal <= 0;
  end else begin
    // Generate LO signals
    lo_i <= $sin(2 * $pi * freq / Fs * phase_i);
    lo_q <= $sin(2 * $pi * freq / Fs * phase_q + $pi / 2);

    // Generate quadrature signals
    i_signal <= in * $cos(2 * $pi * freq / Fs * k);
    q_signal <= in * $sin(2 * $pi * freq / Fs * k);

    // Modulate amplitude and phase of quadrature signals
    mod_signal <= i_signal * lo_i - q_signal * lo_q;

    // Update LO phase
    phase_i <= phase_i + (1 << N) * freq / Fs;
    phase_q <= phase_q + (1 << N) * freq / Fs;
  end
end

// Quadrature demodulator
always @(posedge clk) begin
  if (reset) begin
    lo_i <= 0;
    lo_q <= 0;
    phase_i <= 0;
    phase_q <= 0;
    demod_signal <= 0;
  end else begin
    // Generate LO signals
    lo_i <= $sin(2 * $pi * freq / Fs * phase_i);
    lo_q <= $sin(2 * $pi * freq / Fs * phase_q + $pi / 2);

    // Demodulate modulated signal
    demod_signal <= mod_signal * lo_i + mod_signal * lo_q;

    // Update LO phase
    phase_i <= phase_i + (1 << N) * freq / Fs;
    phase_q <= phase_q + (1 << N) * freq / Fs;
  end
end

// Low-pass filter
reg [15:0] filtered_signal;
always @(posedge clk) begin
  if (reset) begin
    filtered_signal <= 0;
  end else begin
    filtered_signal <= filtered_signal + (demod_signal - filtered_signal) / 16;
  end
end

assign out = filtered_signal;

endmodule

