input wire InTrigger;
output wire OutReady;

reg [8:1] counter = 0;
localparam Ready = 0;
localparam Counting = 1;
reg currentState = 0;

always @ (posedge Clock) 
begin
	if (Reset == 1) 
		begin
			counter = 0;
			currentState = Ready;
		end
	else
		begin
			case (currentState)
				Ready:
					if (InTrigger == 1)
						begin
							counter = 0;
							currentState = Counting;
						end
				Counting:
					if (counter == 10)
						begin
							currentState = Ready;
						end
					else
						begin
							counter = counter + 1;
						end
				default:
					currentState = Ready;
			endcase
		end
end


assign OutSignal = InSignal + counter;
assign OutReady = currentState == Ready ? 1'b1 : 1'b0;

endmodule

