module vga_controller(
input wire clk,
input wire reset,
output reg hs,
output reg vs,
output wire pixel_clk,
output wire blank,
output wire sync,
output wire [10:0] DrawX,
output wire [10:0] DrawY
);
// 50 MHz clock
// reset signal
// Horizontal sync pulse.  Active low
// Vertical sync pulse.  Active low
// 25 MHz pixel clock output
// Blanking interval indicator.  Active low.
// Composite Sync signal.  Active low.  We don't use it in this lab,
//   but the video DAC on the DE2 board requires an input for it.
// horizontal coordinate
// vertical coordinate
//800 horizontal pixels indexed 0 to 799
//525 vertical pixels indexed 0 to 524
parameter hpixels = 10'b1100011111;
parameter vlines = 10'b1000001100;  //horizontal pixel and vertical line counters
reg [10:0] hc; reg [10:0] vc;
reg clkdiv;  //signal indicates if ok to display color for a pixel
reg display;
  // Disable Composite Sync
  assign sync = 1'b0;
  //This cuts the 50 Mhz clock in half to generate a 25 MHz pixel clock
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      clkdiv <= 1'b0;
    end else begin
      clkdiv <=  ~clkdiv;
    end
  end
  //Runs the horizontal counter  when it resets vertical counter is incremented
  always @(posedge clkdiv, posedge reset) begin
    if((reset == 1'b1)) begin
      hc <= 11'b00000000000;
      vc <= 11'b00000000000;
    end else begin
      if((hc == hpixels)) begin
        //If hc has reached the end of pixel count
        hc <= 11'b00000000000;
        if((vc == vlines)) begin
          // if vc has reached end of line count
          vc <= 11'b00000000000;
        end
        else begin
          vc <= vc + 1;
        end
      end
      else begin
        hc <= hc + 1;
        // no statement about vc, implied vc <= vc;
      end
    end
  end
  assign DrawX = hc;
  assign DrawY = vc;
  // horizontal sync pulse is 96 pixels long at pixels 656-752
  // (signal is registered to ensure clean output waveform)
  always @(posedge reset, posedge clkdiv, posedge hc) begin
    if((reset == 1'b1)) begin
      hs <= 1'b0;
    end else begin
      if(((hc + 1) >= 10'b1010010000 && (hc + 1) < 10'b1011110000)) begin
        // must check next value of hc
        hs <= 1'b0;
      end
      else begin
        hs <= 1'b1;
      end
    end
  end
  // vertical sync pulse is 2 lines(800 pixels) long at line 490-491
  //   (signal is registered to ensure clean output waveform)
  always @(posedge reset, posedge clkdiv, posedge vc) begin
    if((reset == 1'b1)) begin
      vs <= 1'b0;
    end else begin
      if(((vc + 1) == 9'b111101010 || (vc + 1) == 9'b111101011)) begin
        // must check next value of vc
        vs <= 1'b0;
      end
      else begin
        vs <= 1'b1;
      end
    end
  end
  // only display pixels between horizontal 0-639 and vertical 0-479 (640x480)
  // (This signal is registered within the DAC chip, so we can leave it as pure combinational logic here)
  always @(hc, vc) begin
    if(((hc >= 10'b1010000000) || (vc >= 10'b0111100000))) begin
      display <= 1'b0;
    end
    else begin
      display <= 1'b1;
    end
  end
  assign blank = display;
  assign pixel_clk = clkdiv;
endmodule

