module zk_session_Packetizer(
input wire clk,
input wire rst,
input wire in_valid,
output wire in_ready,
input wire [63:0] in_data,
input wire [63:0] in_meta,
input wire [7:0] in_keep,
input wire in_last,
output wire out_valid,
input wire out_ready,
output wire out_last,
output wire [63:0] out_data,
output wire [63:0] out_meta
);
wire outValid;
wire outReady;
wire outLast;
reg outFirst;
reg [15:0] outLength;
wire [63:0] outData;
wire [63:0] outMeta;
  assign outValid = in_valid;
  assign in_ready = outReady;
  assign outData = in_data;
  assign outMeta = in_data;
  assign outLast = outLength == 0 ? 1'b1 : 1'b0;
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      outFirst <= 1'b1;
      outLength <= {16{1'b0}};
      outLength[0] <= 1'b1;
    end
    else begin
      if((outValid == 1'b1 && outReady == 1'b1)) begin
        outLength <= outLength - 1;
        if((outFirst == 1'b1)) begin
          if((outData[15 + 32 -: 15 + 1] != 0)) begin
            outLength <= outData[15 + 32 -: 15 + 1];
          end
          outFirst <= 1'b0;
        end
        if((outLength == 0)) begin
          outFirst <= 1'b1;
          outLength <= {16{1'b0}};
          outLength[0] <= 1'b1;
        end
      end
    end
  end
  assign out_valid = outValid;
  assign outReady = out_ready;
  assign out_data = outData;
  assign out_meta = outMeta;
  assign out_last = outLast;
endmodule

