module ADS7830(
inout wire SDA,
input wire SCL
);
parameter [6:0] I2C_ADR=7'b1001000;
parameter CMD_WORD = 8'h8C;
parameter MEM_WORD = 8'h9A;  //x"9A";
wire SDA_latched = 1'b1;
wire start_or_stop;
reg [3:0] bitcnt = 4'b1111;  // counts the I2C bits from 7 downto 0, plus an ACK bit
wire bit_DATA;
wire bit_ACK;
reg data_phase = 1'b0;
wire adr_phase;
reg adr_match = 1'b0;
reg op_read = 1'b0;
wire [7:0] mem = MEM_WORD;
wire op_write;
wire mem_bit_low;
wire SDA_assert_low;
wire SDA_assert_ACK;
wire SDA_low;
reg [6:0] adr_reg = 7'b0000000;
wire SDA_int;
wire SCL_int;
reg initialized = 1'b0;
wire SDA_edge;
  // for simulation only
  assign SDA_int = SDA == 1'b0 ? 1'b0 : 1'b1;
  assign SCL_int = SCL == 1'b0 ? 1'b0 : 1'b1;
  // We use two wires with a combinatorial loop to detect the start and stop conditions
  // making sure these two wires don't get optimized away
  assign SDA_latched = (SCL_int == 1'b0) ? SDA_int : SDA_latched;
  assign SDA_edge = SDA_int ^ SDA_latched;
  assign start_or_stop = (SCL_int == 1'b0) ? 1'b0 : SDA_edge;
  assign bit_ACK = bitcnt[3];
  // the ACK bit is the 9th bit sent
  assign bit_DATA =  ~bit_ACK;
  always @(negedge SCL_int, negedge start_or_stop) begin
    if((start_or_stop == 1'b1)) begin
      bitcnt <= 4'h7;
      // the bit 7 is received first
      data_phase <= 1'b0;
    end else begin
      if((bit_ACK == 1'b1)) begin
        bitcnt <= 4'h7;
        data_phase <= 1'b1;
      end
      else begin
        bitcnt <= bitcnt - 1;
      end
    end
  end
  assign adr_phase =  ~data_phase;
  assign op_write =  ~op_read;
  always @(posedge SCL_int, posedge start_or_stop) begin : P1
    reg [7:0] cmd_reg = 8'h00;
    if((start_or_stop == 1'b1)) begin
      adr_match <= 1'b0;
      op_read <= 1'b0;
    end else begin
      if((adr_phase == 1'b1)) begin
        if((bitcnt > 3'b000)) begin
          adr_reg <= {adr_reg[5:0],SDA_int};
        end
        else begin
          op_read <= SDA_int;
          if((adr_reg == I2C_ADR[6:0])) begin
            adr_match <= 1'b1;
          end
        end
      end
      if((data_phase == 1'b1 && adr_match == 1'b1)) begin
        if((op_write == 1'b1 && initialized == 1'b0)) begin
          if((bitcnt >= 3'b000)) begin
            cmd_reg = {cmd_reg[6:0],SDA_int};
          end
          if((bitcnt == 3'b000 && cmd_reg == CMD_WORD)) begin
            initialized <= 1'b1;
          end
        end
      end
    end
  end
  assign mem_bit_low =  ~mem[bitcnt[2:0]];
  assign SDA_assert_low = adr_match & bit_DATA & data_phase & op_read & mem_bit_low & initialized;
  assign SDA_assert_ACK = adr_match & bit_ACK & (adr_phase | op_write);
  assign SDA_low = SDA_assert_low | SDA_assert_ACK;
  assign SDA = (SDA_low == 1'b1) ? 1'b0 : 1'bZ;
endmodule

module Clk1Hz(
input wire Rst,
input wire Clk,
output reg ClkOut
);
//Declaraciones de constantes
parameter Fosc = 100000000;  //Frecuencia del oscilador de tabletas NEXYS 3
parameter Fdiv = 1;  //Frecuencia deseada del divisor
parameter CtaMax = Fosc / Fdiv;  //Cuenta maxima a la que hay que llegar
//Declaracion de signals
reg [31:0] Cont;
  //Proceso que Divide la Frecuencia de entrada para obtener una Frecuencia de 1 Hz
  always @(posedge Rst, posedge Clk) begin
    if(Rst == 1'b1) begin
      Cont <= 0;
    end else begin
      if(Cont == CtaMax) begin
        Cont <= 0;
        ClkOut <= 1'b1;
      end
      else begin
        Cont <= Cont + 1;
        ClkOut <= 1'b0;
      end
    end
  end
endmodule

