module run_control(
input wire clock_i,
input wire reset_i,
input wire start_i,
input wire stop_i,
input wire toggle_i,
output wire enable_o
);
reg state;
  assign enable_o = state;
  always @(posedge clock_i) begin
    if((reset_i == 1'b1)) begin
      state <= 1'b0;
    end
    else begin
      state <= state;
      if((stop_i == 1'b1)) begin
        state <= 1'b0;
      end
      else if((start_i == 1'b1)) begin
        state <= 1'b1;
      end
      else if((toggle_i == 1'b1)) begin
        state <=  ~state;
      end
    end
  end
endmodule

module multiplexedadbus(
input wire [15:0] avs_s0_address,
input wire avs_s0_read,
output wire [15:0] avs_s0_readdata,
input wire avs_s0_write,
input wire [15:0] avs_s0_writedata,
output wire avs_s0_waitrequest,
input wire [1:0] avs_s0_byteenable,
input wire clk,
input wire reset,
output reg adbus_cs,
inout wire [15:0] adbus_ad,
output reg [1:0] adbus_be,
output reg adbus_ale,
output reg adbus_wr,
output reg adbus_rd,
input wire adbus_ack
);
//    s0.address
//      .read
//      .readdata
//      .write
//      .writedata
//      .waitrequest
//      .byteenable
// clock.clk
// reset.reset
// adbus.export
//      .export
//      .export
//      .export
//      .export
//      .export
//      .export
reg [2:0] count;
parameter countMax = 3'b111;
parameter [1:0]
  sIdle = 0,
  sWait = 1,
  sWrd = 2;
reg [1:0] fsm;
reg ack;
reg ack_d;
reg ack_l;
reg [15:0] readdata;
reg [15:0] readdata_l;
reg [15:0] adReg;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      count <= {3{1'b0}};
      adbus_cs <= 1'b0;
      adbus_ale <= 1'b0;
      adbus_rd <= 1'b0;
      adbus_wr <= 1'b0;
      ack <= 1'b0;
      ack_l <= 1'b0;
      readdata <= {16{1'b0}};
      readdata_l <= {16{1'b0}};
      adbus_be <= {2{1'b0}};
      adReg <= {16{1'b0}};
    end else begin
      ack_l <= adbus_ack;
      ack <= ack_l;
      ack_d <= ack;
      readdata_l <= adbus_ad;
      readdata <= readdata_l;
      if(fsm == sIdle) begin
        count <= {3{1'b0}};
      end
      else if(fsm == sWait) begin
        count <= (count) + 1;
      end
      adbus_be <= avs_s0_byteenable;
      case(fsm)
      sIdle : begin
        adbus_cs <= 1'b0;
        adbus_ale <= 1'b0;
        adbus_rd <= 1'b0;
        adbus_wr <= 1'b0;
        if(avs_s0_read == 1'b1 || avs_s0_write == 1'b1) begin
          fsm <= sWait;
          adbus_cs <= 1'b1;
          adbus_ale <= 1'b1;
          adReg <= avs_s0_address;
        end
      end
      sWait : begin
        if(count == countMax) begin
          fsm <= sWrd;
          adbus_ale <= 1'b0;
          adbus_wr <= avs_s0_write;
          adbus_rd <= avs_s0_read;
          adReg <= avs_s0_writedata;
        end
      end
      sWrd : begin
        if(ack == 1'b1) begin
          fsm <= sIdle;
          adbus_cs <= 1'b0;
          adbus_rd <= 1'b0;
          adbus_wr <= 1'b0;
        end
      end
      endcase
    end
  end
  assign adbus_ad = fsm == sWait || (fsm == sWrd && avs_s0_write == 1'b1) ? adReg : {16{1'bZ}};
  // if ack goes high deassert waitrequest (edge detection)
  assign avs_s0_waitrequest = ack_d == 1'b0 && ack == 1'b1 ? 1'b0 : 1'b1;
  assign avs_s0_readdata = readdata;
// of multiplexedadbus
endmodule

module stage(
input wire [31:0] la_input,
input wire la_inputReady,
input wire [31:0] data,
input wire clock,
input wire reset,
input wire wrMask,
input wire wrValue,
input wire wrConfig,
input wire arm,
input wire [1:0] level,
input wire demuxed,
output reg run,
output reg match
);
parameter [1:0]
  OFF = 0,
  ARMED = 1,
  MATCHED = 2;
reg [31:0] maskRegister; reg [31:0] valueRegister;
reg [31:0] intermediateRegister; reg [31:0] shiftRegister;
wire [31:0] testValue;
reg cfgStart; reg cfgSerial;
reg [4:0] cfgChannel;
reg [1:0] cfgLevel;
reg [15:0] counter; reg [15:0] cfgDelay;
wire matchL16; wire matchH16; reg match32Register;
reg [1:0] state;
reg serialChannelL16; reg serialChannelH16;
  // use shift register or la_input depending on configuration
  assign testValue = cfgSerial == 1'b1 ? shiftRegister : la_input;
  // apply mask and value and create a additional pipeline step
  always @(posedge clock) begin
    intermediateRegister <= (testValue ^ valueRegister) & maskRegister;
  end
  // match upper and lower word separately
  assign matchL16 = intermediateRegister[15:0] == 16'b0000000000000000 ? 1'b1 : 1'b0;
  assign matchH16 = intermediateRegister[31:16] == 16'b0000000000000000 ? 1'b1 : 1'b0;
  // in demux mode only one half must match, in normal mode both words must match
  always @(posedge clock) begin
    if(demuxed == 1'b1) begin
      match32Register <= matchL16 | matchH16;
    end
    else begin
      match32Register <= matchL16 & matchH16;
    end
  end
  // select serial channel based on cfgChannel
  always @(la_input, cfgChannel) begin
    for (i=0; i <= 15; i = i + 1) begin
      if((cfgChannel[3:0]) == i) begin
        serialChannelL16 <= la_input[i];
        serialChannelH16 <= la_input[i + 16];
      end
    end
  end
  // shift in bit from selected channel whenever la_input is ready
  always @(posedge clock) begin
    if(la_inputReady == 1'b1) begin
      if(demuxed == 1'b1) begin
        // in demux mode two bits come in per sample
        shiftRegister <= {shiftRegister[29:0],serialChannelH16,serialChannelL16};
      end
      else if(cfgChannel[4] == 1'b1) begin
        shiftRegister <= {shiftRegister[30:0],serialChannelH16};
      end
      else begin
        shiftRegister <= {shiftRegister[30:0],serialChannelL16};
      end
    end
  end
  // trigger state machine
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      state <= OFF;
    end
    else begin
      run <= 1'b0;
      match <= 1'b0;
      case(state)
      OFF : begin
        if(arm == 1'b1) begin
          state <= ARMED;
        end
      end
      ARMED : begin
        if(match32Register == 1'b1 && level >= cfgLevel) begin
          counter <= cfgDelay;
          state <= MATCHED;
        end
      end
      MATCHED : begin
        if(la_inputReady == 1'b1) begin
          if(counter == 16'b0000000000000000) begin
            run <= cfgStart;
            match <=  ~cfgStart;
            state <= OFF;
          end
          else begin
            counter <= counter - 1;
          end
        end
      end
      endcase
    end
  end
  // handle mask, value & config register write requests
  always @(posedge clock) begin
    if(wrMask == 1'b1) begin
      maskRegister <= data;
    end
    if(wrValue == 1'b1) begin
      valueRegister <= data;
    end
    if(wrConfig == 1'b1) begin
      cfgStart <= data[27];
      cfgSerial <= data[26];
      cfgChannel <= data[24:20];
      cfgLevel <= data[17:16];
      cfgDelay <= data[15:0];
    end
  end
endmodule

module clk4Hz(
