    if((RST == 1'b1)) begin
      clkdv <= 1'b0;
      counter <= 0;
    end else begin
      if((counter == 12500000)) begin
        if((clkdv == 1'b0)) begin
          clkdv <= 1'b1;
        end
        else begin
          clkdv <= 1'b0;
        end
        counter <= 0;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  assign CLK_OUT = clkdv;
endmodule

