module VideoSyncGenerator(
input wire reset,
input wire PixelClock,
output reg HSync,
output reg VSync,
output wire VideoOn,
output reg [9:0] CurCol,
output reg [9:0] CurRow
);
// indicates whether colourshall be outputted
reg [9:0] vcount;  // count scanlines
reg [9:0] hcount;  // count pixels
reg hblank; reg vblank;
  // Horizontal line counter
  always @(posedge PixelClock, posedge reset) begin
      // if reset is asserted
    if(reset == 1'b1) begin
      hcount <= {10{1'b0}};
    end else begin
      if(hcount == 799) begin
        hcount <= {10{1'b0}};
      end
      else begin
        hcount <= hcount + 1;
      end
    end
  end
  // HSync generator
  always @(hcount) begin
    hblank <= 1'b1;
    CurCol <= hcount;
    if(hcount >= 640) begin
      hblank <= 1'b0;
      CurCol <= {10{1'b0}};
    end
    if((hcount <= 755 && hcount >= 659)) begin
      HSync <= 1'b0;
    end
    else begin
      HSync <= 1'b1;
    end
  end
  // Vertical line counter
  always @(posedge PixelClock, posedge reset) begin
    if(reset == 1'b1) begin
      vcount <= {10{1'b0}};
    end else begin
      if(hcount == 799) begin
        if(vcount == 524) begin
          vcount <= {10{1'b0}};
        end
        else begin
          vcount <= vcount + 1;
        end
      end
    end
  end
  // VSync generator
  always @(vcount) begin
    vblank <= 1'b1;
    CurRow <= vcount;
    if(vcount >= 480) begin
      vblank <= 1'b0;
      CurRow <= {10{1'b0}};
    end
    if((vcount <= 494 && vcount >= 493)) begin
      VSync <= 1'b0;
    end
    else begin
      VSync <= 1'b1;
    end
  end
  assign VideoOn = VBlank & HBlank;
endmodule

