module Controller_DAC8218(
input wire CLK,
output wire SCLK,
output wire CS,
output reg SDO,
input wire SDI,
input wire [4:0] ADDR,
output reg [15:0] DATA_Read,
input wire [15:0] DATA_Write,
input wire WR,
input wire RD,
output wire busy,
output reg Data_Update,
input wire [3:0] CLK_DIVIDER
);
// system clock
// Clock, Chip Select, and data out (to dac)
// data in from DAC
// address for read / write
// Data to read
// Data to write
// commands: write and read.
// indicates if interfaca is being used, data_update indicates end of read cycle / updated data at output port.
// clock prescaler for SCLK
reg [3:0] CLK_Div_count = 4'b0000;
reg CE = 1'b0;  // id read or write command occurs
// the command is latched
reg reading = 1'b0; reg writing = 1'b0;  // also the data to write:
reg [15:0] data_to_write = 1'b0;  // and the address:
reg [4:0] latched_address = 1'b0;  // counter for SCLK
reg [5:0] SPI_Counter = 0;  // register for chip select, so it's possible to read back its value.
reg CS_Register = 1'b1;  // initiate with 1 due to inverted logic
// same for SCLK
reg SCLK_Register = 1'b0;  //Shift register for SPI 
reg [23:0] ShiftRegister;
  //- genreate clock enable signal. will be used to scale down the internal clock.
  //- maximum SCLK is 25MHz for the DAC8218 for VCCO=3V
  always @(posedge CLK) begin
    if(CLK_Div_count == 4'b0000) begin
      CE <= 1'b1;
      CLK_Div_count <= CLK_DIVIDER;
    end
    else begin
      CE <= 1'b0;
      CLK_Div_count <= (CLK_Div_count) - 1;
    end
  end
  assign busy = reading | Writing | WR | rd;
  assign CS = CS_Register;
  assign SCLK = SCLK_Register;
  always @(posedge CLK) begin
    Data_Update <= 1'b0;
    if(reading == 1'b0 && writing == 1'b0) begin
      if(WR == 1'b1) begin
        writing <= 1'b1;
        latched_address <= ADDR;
        data_to_write <= DATA_Write;
      end
      else if(RD == 1'b1) begin
        reading <= 1'b1;
        latched_address <= ADDR;
      end
    end
    else if(CE == 1'b1) begin
      if(CS_Register == 1'b0) begin
        if(SCLK_Register == 1'b0) begin
          // on rising edge of SCLK
          SPI_Counter <= SPI_Counter + 1;
          // increase count of generated clocks
          // load shift register serially during transfer
          ShiftRegister[23:1] <= ShiftRegister[22:0];
          ShiftRegister[0] <= SDI;
          SDO <= Shiftregister[23];
          if(SPI_Counter == (24)) begin
            // when 24 clocks are generated
            CS_Register <= 1'b1;
            // finish transfer by disabeling CS (invertet logic)
            reading <= 1'b0;
            writing <= 1'b0;
            SDO <= 1'b0;
            //if reading = '1' then -- condition removed, because in the datasheet a write cycle is used to read (read cycle only to initiate)
            Data_Update <= 1'b1;
            DATA_Read[15:1] <= ShiftRegister[14:0];
            DATA_Read[0] <= SDI;
            //end if;
          end
          else begin
            SCLK_Register <=  ~SCLK_Register;
          end
        end
        else begin
          SCLK_Register <=  ~SCLK_Register;
        end
      end
      else if(reading == 1'b1 || writing == 1'b1) begin
        CS_Register <= 1'b0;
        SPI_Counter <= 0;
        // load shift register parallely:
        ShiftRegister[23] <= reading;
        //bit defines if access is read or write, 0=write
        ShiftRegister[22:21] <= 2'b00;
        //bits are always don't care (however a command is 24 bit long)
        ShiftRegister[20:16] <= latched_address;
        ShiftRegister[15:0] <= data_to_write;
      end
    end
  end
endmodule

