module mux_4_single_bit(
input wire in_signal_0,
input wire in_signal_1,
input wire in_signal_2,
input wire in_signal_3,
input wire [1:0] input_select,
output reg out_signal
);
// inputs
// select signal
// output
// this circuit requires no internal signals
  // design implementation
  always @(in_signal_0, in_signal_1, in_signal_2, in_signal_3, input_select) begin
    // select 00 is input 0
    if(input_select == 2'b00) begin
      out_signal <= in_signal_0;
      // select 01 is input 1
    end
    else if(input_select == 2'b01) begin
      out_signal <= in_signal_1;
      // select 10 is input 2
    end
    else if(input_select == 2'b10) begin
      out_signal <= in_signal_2;
      // select 11 is input 3
    end
    else if(input_select == 2'b11) begin
      out_signal <= in_signal_3;
      // otherwise invalid select signal, output 0
    end
    else begin
      out_signal <= 1'b0;
    end
  end
endmodule

module mul_int2(
input wire [23:0] in1,
input wire [23:0] in2,
input wire clk,
input wire rst,
output wire done,
output wire [47:0] res
);
wire [47:0] rsh = 1'b0;
reg [47:0] r = 1'b0;
reg [4:0] counter = 5'b00000;
reg d;
  shifter2 sh(
      .in1(in2),
    .in2(counter),
    .rst(rst),
    .res(rsh));
  assign res = r[47:0];
  assign done = d;
  always @(posedge rst, posedge clk) begin
    if(rst == 1'b0) begin
      r <= {48{1'b0}};
      counter <= 5'b00000;
      d <= 1'b0;
    end else begin
      if((in1[counter] == 1'b1 && d == 1'b0)) begin
        r <= (r) + (rsh);
      end
      if((counter == 5'b10111)) begin
        d <= 1'b1;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

