module nexys2_rs232(
input wire [3:0] btns,
input wire rx,
input wire lclk,
output wire tx,
output wire [7:0] leds
);
reg [12:0] count_out;
reg [12:0] count_in;
reg [9:0] data_out = 10'b0000000001;
reg [9:0] data_in = 10'b0000000000;
reg [7:0] holding = 8'b00000000;
reg data_ready = 1'b0;
wire busy_out = 1'b0;
reg [1:0] key_down = 2'b00;
  always @(posedge lclk) begin
    if(btns[0] == 1'b0) begin
      key_down <= 2'b00;
    end
    else if(btns[0] == 1'b1 && key_down == 2'b00) begin
      key_down <= 2'b01;
    end
    if(busy_out == 1'b1) begin
      if(count_out == 5208) begin
        for (i=0; i <= 8; i = i + 1) begin
          data_out[i] <= data_out[i + 1];
        end
        data_out[9] <= 1'b0;
        count_out <= 13'b0000000000000;
      end
      else begin
        count_out <= count_out + 1;
      end
    end
    else begin
      if(data_ready == 1'b1) begin
        data_out[8:1] <= holding;
        data_out[9] <= 1'b1;
        data_out[0] <= 1'b0;
        data_ready <= 1'b0;
      end
      else if(key_down == 2'b01) begin
        key_down <= 2'b10;
        data_out <= 10'b1010000110;
      end
      count_out <= 13'b0000000000000;
    end
    if(data_in[0] == 1'b1) begin
      if(count_in == 5208) begin
        count_in <= 13'b0000000000000;
        for (i=0; i <= 8; i = i + 1) begin
          data_in[i] <= data_in[i + 1];
        end
        data_in[9] <= rx;
        if(data_in[1] == 1'b0) begin
          data_ready <= 1'b1;
          holding[7:0] <= data_in[9:2];
        end
      end
      else begin
        count_in <= count_in + 1;
      end
    end
    else if(rx == 1'b0) begin
      count_in <= 13'b1111000000000;
      data_in <= 10'b0111111111;
    end
  end
  assign leds[0] = rx == 1'b0 ? 1'b1 : 1'b0;
  assign leds[1] = data_out[0] == 1'b0 ? 1'b1 : 1'b0;
  assign leds[2] = busy_out;
  assign leds[3] = data_in[0];
  assign leds[4] = btns[0];
  assign leds[5] = btns[1];
  assign leds[6] = btns[2];
  assign leds[7] = btns[3];
  assign tx = data_out[0];
  assign busy_out = data_out == 10'b0000000001 ? 1'b0 : 1'b1;
endmodule

