module dp_lsft64(
input wire [64:1] inbus,
input wire [6:1] shift,
output wire [64:1] outbus
);
wire [64:1] levzip; wire [64:1] levone; wire [64:1] levtwo; wire [64:1] levthr;
  assign levzip = inbus;
  genvar k;
  generate for (k=4; k <= 64; k = k + 1) begin: gla
      assign levone[k] = (levzip[k] &  ~(shift[2]) &  ~(shift[1])) | (levzip[k - 1] &  ~(shift[2]) & shift[1]) | (levzip[k - 2] & shift[2] &  ~(shift[1])) | (levzip[k - 3] & shift[2] & shift[1]);
  end
  endgenerate
  assign levone[3] = (levzip[3] &  ~(shift[2]) &  ~(shift[1])) | (levzip[2] &  ~(shift[2]) & shift[1]) | (levzip[1] & shift[2] &  ~(shift[1]));
  assign levone[2] = (levzip[2] &  ~(shift[2]) &  ~(shift[1])) | (levzip[1] &  ~(shift[2]) & shift[1]);
  assign levone[1] = levzip[1] &  ~(shift[2]) &  ~(shift[1]);
  genvar k;
  generate for (k=13; k <= 64; k = k + 1) begin: glba
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3])) | (levone[k - 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=9; k <= 12; k = k + 1) begin: glbb
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=5; k <= 8; k = k + 1) begin: glbc
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 4; k = k + 1) begin: glbd
      assign levtwo[k] = levone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: glca
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5])) | (levtwo[k - 48] & shift[6] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=33; k <= 48; k = k + 1) begin: glcb
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5]));
  end
  endgenerate
  genvar k;
  generate for (k=17; k <= 32; k = k + 1) begin: glcc
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 16; k = k + 1) begin: glcd
      assign levthr[k] = levtwo[k] &  ~(shift[6]) &  ~(shift[5]);
  end
  endgenerate
  assign outbus = levthr;
endmodule

module vga_sync(
input wire clock,
input wire reset,
output wire hsync,
output wire vsync,
output wire video_on,
output wire pixel_tick,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y
);
// VGA 640x480
// horizontal timings, in pixels
parameter h_display_area = 640;
parameter h_front_porch = 16;
parameter h_sync = 96;
parameter h_back_porch = 48;  // vertical timings, in lines
parameter v_display_area = 480;
parameter v_front_porch = 10;
parameter v_sync = 2;
parameter v_back_porch = 33;  // derived horizontal constants
parameter hsync_start = h_display_area + h_front_porch;
parameter hsync_end = hsync_start + h_sync;
parameter end_of_line = hsync_end + h_back_porch - 1;  // derived vertical constants
parameter vsync_start = v_display_area + v_front_porch;
parameter vsync_end = vsync_start + v_sync;
parameter end_of_frame = vsync_start + v_back_porch - 1;  // mod-2 counter
reg mod2_reg; wire mod2_next;  // sync counters
reg [9:0] v_count_reg; reg [9:0] v_count_next;
reg [9:0] h_count_reg; reg [9:0] h_count_next;  // output buffer
reg v_sync_reg; reg h_sync_reg;
wire v_sync_next; wire h_sync_next;  // status signals
wire h_end; wire v_end; wire p_tick;
  // registers
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      mod2_reg <= 1'b0;
      v_count_reg <= {10{1'b0}};
      h_count_reg <= {10{1'b0}};
      v_sync_reg <= 1'b0;
      h_sync_reg <= 1'b0;
    end else begin
      mod2_reg <= mod2_next;
      v_count_reg <= v_count_next;
      h_count_reg <= h_count_next;
      v_sync_reg <= v_sync_next;
      h_sync_reg <= h_sync_next;
    end
  end
  // mod-2 circuit to generate 25.125MHz enable tick
  assign mod2_next =  ~mod2_reg;
  // 25.125MHz pixel tick
  assign p_tick = mod2_reg == 1'b1 ? 1'b1 : 1'b0;
  // status
  assign h_end = h_count_reg == end_of_line ? 1'b1 : 1'b0;
  assign v_end = v_count_reg == end_of_frame ? 1'b1 : 1'b0;
  // mod-800 horizontal sync counter
  always @(h_count_reg, h_end, p_tick) begin
    if(p_tick == 1'b1) begin
      if(h_end == 1'b1) begin
        h_count_next <= {10{1'b0}};
      end
      else begin
        h_count_next <= h_count_reg + 1;
      end
    end
    else begin
      h_count_next <= h_count_reg;
    end
  end
  // mod-525 vertical sync counter
  always @(v_count_reg, h_end, v_end, p_tick) begin
    if(p_tick == 1'b1 && h_end == 1'b1) begin
      if(v_end == 1'b1) begin
        v_count_next <= {10{1'b0}};
      end
      else begin
        v_count_next <= v_count_reg + 1;
      end
    end
    else begin
      v_count_next <= v_count_reg;
    end
  end
  // hsync and vsync, buffered to avoid glitch
  assign h_sync_next = hsync_start <= h_count_reg && h_count_reg < hsync_end ? 1'b1 : 1'b0;
  assign v_sync_next = vsync_start <= v_count_reg && v_count_reg < vsync_end ? 1'b1 : 1'b0;
  // video on/off
  assign video_on = h_count_reg < h_display_area && v_count_reg < v_display_area ? 1'b1 : 1'b0;
  // output signals
  assign hsync = h_sync_reg;
  assign vsync = v_sync_reg;
  assign pixel_x = h_count_reg;
  assign pixel_y = v_count_reg;
  assign pixel_tick = p_tick;
endmodule

module extRam_loader(
input wire clock,
input wire reset,
input wire [7:0] data_in,
input wire RxRdy_in,
output reg [15:0] data_out,
output reg RxRdy_out
);
parameter [0:0]
  LSB = 0,
  MSB = 1;
reg estado = LSB;
  always @(posedge clock, posedge reset) begin
      // reset
    if(reset == 1'b1) begin
      data_out <= {16{1'b0}};
      estado <= LSB;
      RxRdy_out <= 1'b0;
    end else begin
      RxRdy_out <= 1'b0;
      case(estado)
      LSB : begin
        if(RxRdy_in == 1'b1) begin
          // Modo lectura del LSB
          data_out[7:0] <= data_in;
          RxRdy_out <= 1'b0;
          estado <= MSB;
        end
      end
      MSB : begin
        if(RxRdy_in == 1'b1) begin
          data_out[15:8] <= data_in;
          RxRdy_out <= 1'b1;
          estado <= LSB;
        end
      end
      endcase
    end
  end
endmodule

module add_295(
output wire [26:0] result,
input wire [26:0] in_a,
input wire [26:0] in_b
);
wire [28:0] carry_inA;
wire [28:0] carry_inB;
wire [28:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[27:1];
endmodule

module spi_funnel(
input wire clk_in,
input wire reset_in,
input wire cpuByteWide_in,
input wire [15:0] cpuWrData_in,
input wire cpuWrValid_in,
output wire [15:0] cpuRdData_out,
input wire cpuRdStrobe_in,
output reg [7:0] sendData_out,
output reg sendValid_out,
input wire sendReady_in,
input wire [7:0] recvData_in,
input wire recvValid_in,
output wire recvReady_out
);
// CPU I/O
// Sending SPI data
// Receiving SPI data
parameter [0:0]
  S_WRITE_MSB = 0,
  S_WRITE_LSB = 1;
parameter [0:0]
  S_WAIT_MSB = 0,
  S_WAIT_LSB = 1;
reg sstate = S_WRITE_MSB;
reg sstate_next;
reg rstate = S_WAIT_MSB;
reg rstate_next;
reg byteWide = 1'b0;
reg byteWide_next;
reg [7:0] lsb = 1'b0;
reg [7:0] lsb_next;
reg [15:0] readData = 1'b0;
reg [15:0] readData_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      sstate <= S_WRITE_MSB;
      rstate <= S_WAIT_MSB;
      lsb <= {8{1'b0}};
      readData <= {16{1'b0}};
      byteWide <= 1'b0;
    end
    else begin
      sstate <= sstate_next;
      rstate <= rstate_next;
      lsb <= lsb_next;
      readData <= readData_next;
      byteWide <= byteWide_next;
    end
  end
  // Send state machine
  always @(sstate, lsb, cpuWrData_in, cpuWrValid_in, sendReady_in, cpuByteWide_in, cpuRdStrobe_in, byteWide) begin
    sstate_next <= sstate;
    sendValid_out <= 1'b0;
    lsb_next <= lsb;
    byteWide_next <= byteWide;
    case(sstate)
        // Now send the LSB to SPI and return:
    S_WRITE_LSB : begin
      sendData_out <= lsb;
      if((sendReady_in == 1'b1)) begin
        sendValid_out <= 1'b1;
        sstate_next <= S_WRITE_MSB;
      end
      // When the CPU writes a word, send the MSB to SPI:
    end
    default : begin
      sendData_out <= 8'h55;
      if((cpuByteWide_in == 1'b1)) begin
        // We're sending single bytes rather than 16-bit words. Note
        // the lack of byte auto-read.
        if((cpuWrValid_in == 1'b1)) begin
          // Write next word
          sendData_out <= cpuWrData_in[15:8];
          sendValid_out <= 1'b1;
          byteWide_next <= 1'b1;
        end
      end
      else begin
        // We're sending 16-bit words rather than single bytes. Note
        // the word auto-read.
        if((cpuWrValid_in == 1'b1)) begin
          // Write next word
          sstate_next <= S_WRITE_LSB;
          sendData_out <= cpuWrData_in[15:8];
          sendValid_out <= 1'b1;
          lsb_next <= cpuWrData_in[7:0];
          byteWide_next <= 1'b0;
        end
        else if((cpuRdStrobe_in == 1'b1)) begin
          // Auto-fetch next word when reading
          sstate_next <= S_WRITE_LSB;
          sendData_out <= 8'hFF;
          sendValid_out <= 1'b1;
          lsb_next <= 8'hFF;
          byteWide_next <= 1'b0;
        end
      end
    end
    endcase
  end
  // Receive state machine
  always @(rstate, readData, recvData_in, recvValid_in, byteWide) begin
    rstate_next <= rstate;
    readData_next <= readData;
    case(rstate)
        // Wait for the LSB to arrive:
    S_WAIT_LSB : begin
      if((recvValid_in == 1'b1)) begin
        rstate_next <= S_WAIT_MSB;
        readData_next[7:0] <= recvData_in;
      end
      // When bytes arrive over SPI, present them (as bytes or words) to the CPU
    end
    default : begin
      if((recvValid_in == 1'b1)) begin
        if((byteWide == 1'b1)) begin
          // We're receiving single bytes rather than 16-bit words
          readData_next <= {recvData_in,8'hAA};
          //"XXXXXXXX";
        end
        else begin
          // We're receiving 16-bit words rather than single bytes
          rstate_next <= S_WAIT_LSB;
          readData_next[15:8] <= recvData_in;
        end
      end
    end
    endcase
  end
  assign cpuRdData_out = readData;
  assign recvReady_out = 1'b1;
    // ready for data from 8-bit side
endmodule

module scc_process1(
input wire clk,
input wire rst,
input wire enable,
input wire [7:0] kernel_id,
input wire [1:0] ae_id,
input wire [7:0] kernels_count,
input wire [63:0] reach_count,
input wire [63:0] reach_queue,
output reg p1_done,
input wire p1_req_q_almost_full,
output reg p1_req_q_wr_en,
output reg [63:0] p1_req_q_din
);
// control signals
// Kernel Parameters
// Kernel ID
// Application Engine ID
// Queue pointers
// Number of nodes in reachability queue
// Reach queue pointer (could be FW or BW reach queue)
// Process 1 signals
// p1_count             : out unsigned(63 downto 0);	
// Process 1 req queue signals
reg [63:0] p1_offset;  // signal count			: unsigned(63 downto 0);
// Helping signals
wire [5:0] ae_id_x16;
wire [63:0] u_reach_queue;
wire [63:0] u_reach_count;
wire [63:0] read_pointer;
wire [63:0] read_pointer_x8;
  // p1_count        <= count;
  assign ae_id_x16 = {1'b0,ae_id,3'b000};
  //------this is for 32 kernels, make this ae_id & "0000" for 64 kernels
  assign u_reach_queue = reach_queue;
  assign u_reach_count = reach_count;
  assign read_pointer = p1_offset + kernel_id + ae_id_x16;
  assign read_pointer_x8 = {read_pointer[60:0],3'b000};
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      p1_done <= 1'b0;
      // count			<= (others => '0');
      p1_offset <= {64{1'b0}};
      p1_req_q_wr_en <= 1'b0;
      p1_req_q_din <= {64{1'b0}};
    end
    else begin
      if((enable == 1'b1)) begin
        if((read_pointer < u_reach_count && p1_req_q_almost_full == 1'b0)) begin
          // request reach_queue[p1_offset + kernel_id + ae_id]
          p1_req_q_wr_en <= 1'b1;
          p1_req_q_din <= u_reach_queue + read_pointer_x8;
          // Increment nodes count and read offset
          // count			<= count + 1;
          p1_offset <= p1_offset + kernels_count;
        end
        else begin
          p1_req_q_wr_en <= 1'b0;
          p1_req_q_din <= {64{1'b0}};
          if((p1_req_q_almost_full == 1'b0)) begin
            p1_done <= 1'b1;
          end
        end
      end
      else begin
        p1_done <= 1'b0;
        // count			<= (others => '0');
        p1_offset <= {64{1'b0}};
        // set the p1 request queue signals to default
        p1_req_q_wr_en <= 1'b0;
        p1_req_q_din <= {64{1'b0}};
      end
      // end if kernel state
    end
    // end if rst
  end
    // process 1
endmodule

module MULTIPLICATION_COMPONENT(
input wire [7:0] INPUT1,
input wire [7:0] INPUT2,
output wire [15:0] OUTPUT
);
wire cables[0:7];
wire [7:0] khar[0:7]; wire [7:0] gav[0:7]; wire [7:0] ain[0:7]; wire [7:0] summ[0:7];
wire [15:0] gav16[0:7]; wire [15:0] ain16[0:7]; wire [15:0] summ16[0:7];
  genvar W;
  generate for (W=0; W <= 7; W = W + 1) begin: MAKING_IN
      genvar J;
    generate for (J=0; J <= 7; J = J + 1) begin: ANDING
          assign gav[W][j] = INPUT1[J] & INPUT2[W];
    end
    endgenerate
  end
  endgenerate
  assign ain[0][7] = 1'b0;
  genvar L;
  generate for (L=0; L <= 6; L = L + 1) begin: KHAAR
      assign ain[0][L] = gav[0][L + 1];
  end
  endgenerate
  assign output[0] = gav[0][0];
  genvar I;
  generate for (I=0; I <= 6; I = I + 1) begin: CONNECT
      assign gav16[I + 1] = {8'b00000000,gav[I + 1]};
    assign ain16[I] = {8'b00000000,ain[I]};
    assign summ[I] = summ16[I][7:0];
    ADDER_SUBTRACTOR_COMPONENT MODULE(
          1'b0,
      gav16[I + 1],
      ain16[I],
      1'b0,
      summ16[I],
      cables[I],
      /* open */);
    assign ain[I + 1][7] = cables[I];
    genvar K;
    generate for (K=0; K <= 6; K = K + 1) begin: MAKING
          assign ain[I + 1][K] = summ[I][K + 1];
    end
    endgenerate
    assign output[I + 1] = summ[I][0];
  end
  endgenerate
  // AH:
  // for Q in 0 to COMPONENT_SIZE/2 - 1 generate
  // 	output(Q + COMPONENT_SIZE/2) <= summ(COMPONENT_SIZE/2 - 2)(Q);
  // end generate;
  genvar Q;
  generate for (Q=0; Q <= 6; Q = Q + 1) begin: AH
      assign output[Q + 8] = summ[6][Q + 1];
  end
  endgenerate
  assign output[15] = cables[6];
endmodule

