module clock_generation(
input wire bufclkin,
input wire rst_n,
input wire bufsclkfb,
output reg rst_int,
output wire clk_12_5Mhz,
output wire clk_50Mhz,
output wire clk_100Mhz,
output wire sclk
);
//feedback clock from sdram
wire lock;
wire dllint_clk0;
wire bufdllint_clk0;
wire dllint_clk2x;
wire bufdllint_clk2x;
wire dllext_clk0;
wire locked; wire lockint; wire lockext;
wire bufdllint_clkdv;
wire dllint_clkdv;
  // generate an internal clock sync'ed to the master clock
  CLKDLL #(
      .CLKDV_DIVIDE(10))
  dllint(
      .CLKIN(bufclkin),
    .CLKFB(bufdllint_clk0),
    .CLK0(dllint_clk0),
    .RST(1'b0),
    .CLK90(/* open */),
    .CLK180(/* open */),
    .CLK270(/* open */),
    .CLK2X(dllint_clk2x),
    .CLKDV(dllint_clkdv),
    .LOCKED(lockint));
  // generate an external SDRAM clock sync'ed to the master clock
  CLKDLL dllext(
      .CLKIN(bufclkin),
    .CLKFB(bufsclkfb),
    .CLK0(dllext_clk0),
    .RST(1'b0),
    .CLK90(/* open */),
    .CLK180(/* open */),
    .CLK270(/* open */),
    .CLK2X(/* open */),
    .CLKDV(/* open */),
    .LOCKED(lockext));
  BUFG clkg(
      .I(dllint_clk0),
    .O(bufdllint_clk0));
  BUFG clkg2x(
      .I(dllint_clk2x),
    .O(bufdllint_clk2x));
  BUFG clkhalfx(
      .I(dllint_clkdv),
    .O(bufdllint_clkdv));
  // output the sync'ed SDRAM clock to the SDRAM
  assign sclk = dllext_clk0;
  assign clk_12_5Mhz = bufdllint_clkdv;
  assign clk_50Mhz = bufdllint_clk0;
  // SDRAM controller logic clock
  assign clk_100Mhz = bufdllint_clk2x;
  // doubled clock to other FPGA logic;
  assign locked = lockint & lockext;
  // indicate lock status of the DLLs
  // synchronous reset.  internal reset flag is set active by config. bitstream
  // and then gets reset after DLL clocks start.
  always @(posedge bufclkin) begin
    if(locked == 1'b0) begin
      rst_int <= 1'b0;
      // keep in reset until DLLs start up
    end
    else begin
      rst_int <= rst_n;
      // else manually activate reset with pushbutton
    end
  end
endmodule

module clk_divider(
