    if((rst == 1'b1)) begin
      counter <= 0;
      clk_tp <= 1'b0;
    end else begin
      if(counter == const) begin
        counter <= 0;
        clk_tp <=  ~clk_tp;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

