module ram(
input wire Clk,
input wire Reset,
input wire WriteEnable,
input wire OutputEnable,
input wire ChipSelect,
input wire [7:0] Address,
inout wire [7:0] Databus,
output wire [7:0] Switches,
output wire [6:0] Temp_L,
output wire [6:0] Temp_H
);
// Declaración del componente Bloque de Ram de 64 Bytes.
// Declaración del componente SPR.
// Buses de señales procedentes del decodificador "DEC2:4", que controlan
// las señales WriteEnable y OutputEnable de cada BRAM (Block RAM) y del 
// bloque SPR (Specific Porpouse Registers).
reg [3:0] WE;
reg [3:0] OE;
  // Instancia del SPR. En el decodificador "DEC2:4", sus señales de control 
  // se corresponden con la salida 0.
  spr spr_0(
      .Clk(Clk),
    .Reset(Reset),
    .WriteEnable(WE[0]),
    .OutputEnable(OE[0]),
    .Address(Address[5:0]),
    .Databus(Databus[7:0]),
    .Switches(Switches),
    .Temp_L(Temp_L),
    .Temp_H(Temp_H));
  // Instancia de BRAM. En el decodificador "DEC2:4", sus señales de control 
  // se corresponden con la salida 1.
  bram64 bram_1(
      .Clk(Clk),
    .WriteEnable(WE[1]),
    .OutputEnable(OE[1]),
    .Address(Address[5:0]),
    .Databus(Databus[7:0]));
  // Instancia de BRAM. En el decodificador "DEC2:4", sus señales de control 
  // se corresponden con la salida 2.
  bram64 bram_2(
      .Clk(Clk),
    .WriteEnable(WE[2]),
    .OutputEnable(OE[2]),
    .Address(Address[5:0]),
    .Databus(Databus[7:0]));
  // Instancia de BRAM. En el decodificador "DEC2:4", sus señales de control 
  // se corresponden con la salida 3.
  bram64 bram_3(
      .Clk(Clk),
    .WriteEnable(WE[3]),
    .OutputEnable(OE[3]),
    .Address(Address[5:0]),
    .Databus(Databus[7:0]));
  // Proceso combinacional que decodifica en función del bus de dirección y
  // las señales ChipSelect, WriteEnable y OutputEnable, las señales de 
  // control WE y OE de cada uno de los bloques del sistema de almacenamiento.
  // La escritura predomina sobre la lectura, en caso de tener activadas ambas
  // señales de control.
  always @(ChipSelect, WriteEnable, OutputEnable, Address[7:6]) begin
    WE <= 4'h0;
    OE <= 4'h0;
    if((ChipSelect == 1'b1 && WriteEnable == 1'b1)) begin
      WE[Address[7:6]] <= 1'b1;
    end
    else if((ChipSelect == 1'b1 && OutputEnable == 1'b1)) begin
      OE[Address[7:6]] <= 1'b1;
    end
  end
endmodule

module WriterControlReg0(
input wire clk,
input wire reset,
input wire strobe,
input wire [15:0] data_in,
output wire [15:0] data_out,
input wire buf_interrupt,
output wire data_available,
output wire end_of_stream,
output wire reset_buffer,
output wire [4:0] dataSecAddr,
output wire [6:0] status_byte
);
//----------------- gpib -------------------------
// buffer consumed
// data avilable - at least one byte in buffer
// indicates end of stream
// resets buffer
// secondary address of data
// serial poll status byte
reg i_data_available;
reg i_end_of_stream;
wire i_reset_buffer;
reg [4:0] i_dataSecAddr;
reg [6:0] i_status_byte;
reg t_in; wire t_out;
  assign data_out[0] = buf_interrupt;
  assign data_out[1] = i_data_available;
  assign data_out[2] = i_end_of_stream;
  assign data_out[3] = i_reset_buffer;
  assign data_out[8:4] = i_dataSecAddr;
  assign data_out[15:9] = i_status_byte;
  assign data_available = i_data_available;
  assign end_of_stream = i_end_of_stream;
  assign reset_buffer = i_reset_buffer;
  assign dataSecAddr = i_dataSecAddr;
  assign status_byte = i_status_byte;
  always @(posedge reset, posedge strobe) begin
    if(reset == 1'b1) begin
      t_in <= 1'b0;
      i_data_available <= 1'b1;
    end else begin
      i_data_available <= data_in[1];
      i_end_of_stream <= data_in[2];
      if(data_in[3] == 1'b1) begin
        t_in <=  ~t_out;
      end
      i_dataSecAddr <= data_in[8:4];
      i_status_byte <= data_in[15:9];
    end
  end
  SinglePulseGenerator #(
      .WIDTH(3))
  spg(
      .reset(reset),
    .clk(clk),
    .t_in(t_in),
    .t_out(t_out),
    .pulse(i_reset_buffer));
endmodule

module Clock_Div_5(
input wire nReset,
input wire ClkIn,
output wire ClkOut
);
// Reset
// Incoming Clock
// Outgoing Clock
reg Div_1;
reg Div_2;
reg [2:0] Counter_1;
reg [2:0] Counter_2;
  always @(posedge ClkIn, posedge nReset) begin
    if((nReset == 1'b0)) begin
      Div_1 <= 1'b0;
      Counter_1 <= 3'b000;
    end else begin
      if(Counter_1 == 5) begin
        Counter_1 <= 3'b001;
        Div_1 <= 1'b1;
      end
      else if(Counter_1 >= 2) begin
        Div_1 <= 1'b0;
        Counter_1 <= Counter_1 + 1;
      end
      else begin
        Div_1 <= 1'b1;
        Counter_1 <= Counter_1 + 1;
      end
    end
  end
  always @(negedge ClkIn, negedge nReset) begin
    if((nReset == 1'b0)) begin
      Div_2 <= 1'b0;
      Counter_2 <= 3'b000;
    end else begin
      if(Counter_2 == 5) begin
        Counter_2 <= 3'b001;
        Div_2 <= 1'b1;
      end
      else if(Counter_2 >= 2) begin
        Div_2 <= 1'b0;
        Counter_2 <= Counter_2 + 1;
      end
      else begin
        Div_2 <= 1'b1;
        Counter_2 <= Counter_2 + 1;
      end
    end
  end
  assign ClkOut = Div_1 | Div_2;
endmodule

