module fmsp_sync_cell(
input wire clk,
input wire rst,
input wire data_in,
output reg data_out
);
parameter SYNC_EN=true;
//! Synchronize input
//! INPUTs
//! Receiving clock
//! Receiving reset (active high)
//! Asynchronous data input
//! OUTPUTs
//! Synchronized data output
reg [1:0] data_sync;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      data_sync <= 2'b00;
    end else begin
      data_sync <= {data_sync[0],data_in};
    end
  end
  always @(data_sync[1], data_in) begin
    if((SYNC_EN == true)) begin
      data_out <= data_sync[1];
    end
    else begin
      data_out <= data_in;
    end
  end
