module add4(
input wire [3:0] A,
input wire [3:0] B,
input wire CIN,
output wire [3:0] D,
output reg COUT
);
wire [3:0] sum;
wire [3:0] cG;
wire [3:0] cP;
reg [3:1] cI;
  assign sum = A ^ B;
  assign cG = A & B;
  assign cP = A | B;
  always @(cG, cP, cI) begin
    cI[1] <= cG[0] | (cP[0] & CIN);
    for (i=1; i <= 2; i = i + 1) begin
      cI[i + 1] <= cG[i] | (cP[i] & cI[i]);
    end
    COUT <= cG[3] | (cP[3] & cI[3]);
  end
  assign D[0] = sum[0] ^ CIN;
  assign D[3:1] = sum[3:1] ^ cI[3:1];
endmodule

