reg irq_s = 1'b0;
reg bank_s = 1'b0;
wire ack_rise_s = 1'b0;
  // behavourial
  // does synchronisation, can be connected directly to port pin.
  edge_detect edge_detect_1(
      .async_sig(ack_p),
    .clk(clk),
    .rise(ack_rise_s),
    .fall(/* open */));
  assign enable_p = enable_s;
  assign irq_p = irq_s;
  assign bank_p = bank_s;
  always @(posedge clk) begin
      // process
    // rising clock edge
    if((ready_p == 1'b1)) begin
      irq_s <= 1'b1;
    end
    else if((ack_rise_s == 1'b1)) begin
      irq_s <= 1'b0;
    end
    else begin
      // keep
      irq_s <= irq_s;
    end
  end
  // 
  always @(posedge clk) begin
      // process bank_proc
    // rising clock edge
    if((ready_p == 1'b1) && (irq_s == 1'b0)) begin
      // the other bank was read and is empty now (= irq_s low)
      bank_s <=  ~bank_s;
    end
  end
    // types
  // signals
endmodule

