module TriggerOutLogic(
input wire CLK_100MHZ,
input wire CLK_400MHZ,
input wire RESET,
input wire [7:0] TRIG_TX,
input wire TRIG_VALID,
output wire TRIG_CLKP,
output wire TRIG_CLKN,
output wire TRIG_DATP,
output wire TRIG_DATN
);
// These clocks are usually generated from SYS_MMCM.
// 100 MHz trigger output serial clock, must be from same MMCM as CLK_400MHZ
// 400 MHz DDR serial output clock
// Asynchronous reset for the trigger logic
// Current trigger value, synchronous to CLK_100MHZ
// Valid flag for TRIG_TX
// 100MHz Serial Clock
// 800 Mbps Serial Data
wire [0:0] ClkOutP;
wire [0:0] ClkOutN;
wire [0:0] DatOutP;
wire [0:0] DatOutN;
wire [1:0] DataOut;
reg [7:0] SerTrigIn;
wire [7:0] SerTrigOut;
wire [15:0] SerDatOut;
reg dTRIG_VALID;
  // Connect serial output vectors to output pins
  assign TRIG_CLKP = ClkOutP[0];
  assign TRIG_CLKN = ClkOutN[0];
  assign TRIG_DATP = DatOutP[0];
  assign TRIG_DATN = DatOutN[0];
  // Data sent externally LSB first, because the SelectIO wizard IP internally
  // assigns the LSB to D1 of the OSERDESE2.
  // Fixed 0xF0 clock pattern.
  SEROUT8 SCLK1(
      .data_out_to_pins_p(ClkOutP),
    .data_out_to_pins_n(ClkOutN),
    .clk_in(CLK_400MHZ),
    .clk_div_in(CLK_100MHZ),
    .data_out_from_device(8'b11110000),
    // Fixed clock data pattern, sent LSB first.
    .io_reset(RESET));
  SEROUT8 SDAT1(
      .data_out_to_pins_p(DatOutP),
    .data_out_to_pins_n(DatOutN),
    .clk_in(CLK_400MHZ),
    .clk_div_in(CLK_100MHZ),
    .data_out_from_device(SerTrigOut),
    // Trigger Byte
    .io_reset(RESET));
  // One level of input data pipelining to allow for easier routing
  always @(posedge CLK_100MHZ, posedge RESET) begin
    if(RESET == 1'b1) begin
      SerTrigIn <= {8{1'b0}};
      dTRIG_VALID <= 1'b0;
    end else begin
      SerTrigIn <= TRIG_TX;
      dTRIG_VALID <= TRIG_VALID;
    end
  end
  // Only present non-zero data when there is a valid input
  // The output is ALWAYS writing.  When there are not triggers, it writes 0xFF
  assign SerTrigOut = dTRIG_VALID == 1'b1 ? SerTrigIn : 8'hff;
endmodule

module cla_4_bit(
input wire [3:0] A,
input wire [3:0] B,
input wire Cin,
output wire [3:0] Sum,
output wire Cout
);
//these wire the output of the CLL to each FA.
wire Cin1 = 1'b0; wire Cin2 = 1'b0; wire Cin3 = 1'b0;  //these wire the result of the add/sub check to each FA.
wire b0 = 1'b0; wire b1 = 1'b0; wire b2 = 1'b0; wire b3 = 1'b0;
wire [3:0] Bxor;
  //add/sub control; this flips B if necessary.
  assign Bxor[0] = B[0] ^ Cin;
  assign Bxor[1] = B[1] ^ Cin;
  assign Bxor[2] = B[2] ^ Cin;
  assign Bxor[3] = B[3] ^ Cin;
  //Carry-Look-Ahead Logic
  cl_logic CLL0(
      A,
    Bxor,
    Cin,
    Cin1,
    Cin2,
    Cin3,
    Cout);
  //Full adders; for CLA, then individual Couts dangle; they are  
  //handled by the CLL module and are technically unnecessary for 
  //the CLA implementation.
  full_adder_1_bit FA0(
      A[0],
    Bxor[0],
    Cin,
    /* open */,
    Sum[0]);
  full_adder_1_bit FA1(
      A[1],
    Bxor[1],
    Cin1,
    /* open */,
    Sum[1]);
  full_adder_1_bit FA2(
      A[2],
    Bxor[2],
    Cin2,
    /* open */,
    Sum[2]);
  full_adder_1_bit FA3(
      A[3],
    Bxor[3],
    Cin3,
    /* open */,
    Sum[3]);
endmodule

module opcode_fetch(
input wire CLK_I,
input wire T2,
input wire CLR,
input wire CE,
input wire [2:0] PC_OP,
input wire [15:0] JDATA,
input wire [15:0] RR,
input wire [7:0] RDATA,
output wire [15:0] PC
);
reg [15:0] LPC;
reg [7:0] LRET;
  assign PC = LPC;
  always @(posedge CLK_I) begin
    if((CLR == 1'b1)) begin
      LPC <= 16'h0000;
    end
    else if((CE == 1'b1 && T2 == 1'b1)) begin
      case(PC_OP)
      PC_NEXT : begin
        LPC <= LPC + 1;
        // next address
      end
      PC_JMP : begin
        LPC <= JDATA;
        // jump address
      end
      PC_RETL : begin
        LRET <= RDATA;
        // return address L
        LPC <= LPC + 1;
      end
      PC_RETH : begin
        LPC <= {RDATA,LRET};
        // return address H
      end
      PC_JPRR : begin
        LPC <= RR;
      end
      PC_WAIT : begin
      end
      default : begin
        LPC <= 16'h0008;
        // interrupt
      end
      endcase
    end
  end
endmodule

