module button(
input wire clk,
input wire rst,
input wire hw_in,
output reg button_assert
);
parameter [31:0] counter_size=20;
// debounce time control
// system clock, assumed 100 MHz
// system reset
// input from physical button
//debounced signal
reg buf1; reg buf2;  // input buffer digits
wire reset_counter;  // toggle reset_counter
reg [counter_size:0] counter;  // := (OTHERS => '0'); --counter output
  assign reset_counter = buf1 ^ buf2;
  // on change, reset_counter is high
  always @(posedge clk) begin
    if((1'b1 == rst)) begin
      counter <= {((counter_size)-(0)+1){1'b0}};
    end else begin
      buf1 <= hw_in;
      buf2 <= buf1;
      if((reset_counter == 1'b1)) begin
        //input changed, start timer
        counter <= {((counter_size)-(0)+1){1'b0}};
      end
      else if((counter[counter_size] == 1'b1)) begin
        // debounced, output last matched signal
        button_assert <= buf2;
      end
      else begin
        counter <= counter + 1;
        // not debounced yet, keep waiting
      end
    end
  end
endmodule

module dp_rsft64x5pipe(
input wire sysclk,
input wire reset,
input wire enable,
input wire [64:1] inbus,
input wire [5:1] shift,
output wire [64:1] outbus
);
wire [64:1] rightone; wire [64:1] righttwo; wire [64:1] rightthr;
reg [64:1] righttwoff;
reg shiftff;
  genvar k;
  generate for (k=1; k <= 61; k = k + 1) begin: gra
      assign rightone[k] = (inbus[k] &  ~(shift[2]) &  ~(shift[1])) | (inbus[k + 1] &  ~(shift[2]) & shift[1]) | (inbus[k + 2] & shift[2] &  ~(shift[1])) | (inbus[k + 3] & shift[2] & shift[1]);
  end
  endgenerate
  assign rightone[62] = (inbus[62] &  ~(shift[2]) &  ~(shift[1])) | (inbus[63] &  ~(shift[2]) & shift[1]) | (inbus[64] & shift[2] &  ~(shift[1]));
  assign rightone[63] = (inbus[63] &  ~(shift[2]) &  ~(shift[1])) | (inbus[64] &  ~(shift[2]) & shift[1]);
  assign rightone[64] = inbus[64] &  ~(shift[2]) &  ~(shift[1]);
  genvar k;
  generate for (k=1; k <= 52; k = k + 1) begin: grb
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]) | (rightone[k + 8] & shift[4] &  ~(shift[3])) | (rightone[k + 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=53; k <= 56; k = k + 1) begin: grc
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]) | (rightone[k + 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=57; k <= 60; k = k + 1) begin: grd
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=61; k <= 64; k = k + 1) begin: gre
      assign righttwo[k] = rightone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 64; k = k + 1) begin
        righttwoff[k] <= 1'b0;
      end
      shiftff <= 1'b0;
    end else begin
      righttwoff <= righttwo;
      shiftff <= shift[5];
    end
  end
  genvar k;
  generate for (k=1; k <= 48; k = k + 1) begin: grf
      assign rightthr[k] = (righttwoff[k] &  ~(shiftff)) | (righttwoff[k + 16] & shiftff);
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: grg
      assign rightthr[k] = righttwoff[k] &  ~(shiftff);
  end
  endgenerate
  assign outbus = rightthr;
endmodule

module tri_mode_ethernet_mac_0_support_resets(
input wire glbl_rstn,
input wire refclk,
input wire idelayctrl_ready,
output wire idelayctrl_reset_out
);
// The reset pulse for the IDELAYCTRL.  
//----------------------------------------------------------------------------
// Component declaration for the reset synchroniser
//----------------------------------------------------------------------------
wire glbl_rst;
wire idelayctrl_reset_in;  // Used to trigger reset_sync generation in refclk domain.                       
wire idelayctrl_reset_sync;  // Used to create a reset pulse in the IDELAYCTRL refclk domain.      
reg [3:0] idelay_reset_cnt;  // Counter to create a long IDELAYCTRL reset pulse.
reg idelayctrl_reset;
  assign glbl_rst =  ~glbl_rstn;
  assign idelayctrl_reset_out = idelayctrl_reset;
  assign idelayctrl_reset_in = glbl_rst |  ~idelayctrl_ready;
  // Create a synchronous reset in the IDELAYCTRL refclk clock domain.
  aeg_design_0_reset_sync idelayctrl_reset_gen(
      .clk(refclk),
    .enable(1'b1),
    .reset_in(idelayctrl_reset_in),
    .reset_out(idelayctrl_reset_sync));
  // Reset circuitry for the IDELAYCTRL reset.
  // The IDELAYCTRL must experience a pulse which is at least 50 ns in
  // duration.  This is ten clock cycles of the 200MHz refclk.  Here we
  // drive the reset pulse for 12 clock cycles.
  always @(posedge refclk) begin
    if(idelayctrl_reset_sync == 1'b1) begin
      idelay_reset_cnt <= 4'b0000;
      idelayctrl_reset <= 1'b1;
    end
    else begin
      idelayctrl_reset <= 1'b1;
      case(idelay_reset_cnt)
      4'b0000 : begin
        idelay_reset_cnt <= 4'b0001;
      end
      4'b0001 : begin
        idelay_reset_cnt <= 4'b0010;
      end
      4'b0010 : begin
        idelay_reset_cnt <= 4'b0011;
      end
      4'b0011 : begin
        idelay_reset_cnt <= 4'b0100;
      end
      4'b0100 : begin
        idelay_reset_cnt <= 4'b0101;
      end
      4'b0101 : begin
        idelay_reset_cnt <= 4'b0110;
      end
      4'b0110 : begin
        idelay_reset_cnt <= 4'b0111;
      end
      4'b0111 : begin
        idelay_reset_cnt <= 4'b1000;
      end
      4'b1000 : begin
        idelay_reset_cnt <= 4'b1001;
      end
      4'b1001 : begin
        idelay_reset_cnt <= 4'b1010;
      end
      4'b1010 : begin
        idelay_reset_cnt <= 4'b1011;
      end
      4'b1011 : begin
        idelay_reset_cnt <= 4'b1100;
      end
      4'b1100 : begin
        idelay_reset_cnt <= 4'b1101;
      end
      4'b1101 : begin
        idelay_reset_cnt <= 4'b1110;
      end
      default : begin
        idelay_reset_cnt <= 4'b1110;
        idelayctrl_reset <= 1'b0;
      end
      endcase
    end
  end
endmodule

module romnextor(
input wire reset_i,
input wire clock_i,
input wire enable_i,
input wire [15:0] addr_i,
input wire [7:0] data_i,
input wire sltsl_n_i,
input wire rd_n_i,
input wire wr_n_i,
output wire rom_cs_o,
output wire rom_wr_o,
output wire [2:0] rom_page_o
);
//
reg [2:0] rom_page_s;
wire ram_wr_s;
  // Writes
  always @(negedge reset_i, negedge clock_i) begin
    if(reset_i == 1'b1) begin
      rom_page_s <= {3{1'b0}};
    end else begin
      if(enable_i == 1'b1) begin
        if(sltsl_n_i == 1'b0 && wr_n_i == 1'b0 && addr_i == 16'h6000) begin
          rom_page_s <= data_i[2:0];
        end
      end
    end
  end
  assign rom_page_o = rom_page_s;
  assign ram_wr_s = sltsl_n_i == 1'b0 && wr_n_i == 1'b0 && rom_page_s == 3'b111 && addr_i >= 16'h7000 && addr_i <= 16'h7FD0 ? 1'b1 : 1'b0;
  assign rom_cs_o = enable_i == 1'b0 ? 1'b0 : sltsl_n_i == 1'b0 && rd_n_i == 1'b0 && addr_i[15:14] == 2'b01 ? 1'b1 : ram_wr_s == 1'b1 ? 1'b1 : 1'b0;
  assign rom_wr_o = enable_i == 1'b0 ? 1'b0 : ram_wr_s == 1'b1 ? 1'b1 : 1'b0;
endmodule

module i2c_controller(
input wire clk,
input wire reset_n,
output reg FIFO_WriteEn,
output reg [7:0] FIFO_DataIn,
input wire FIFO_Full,
output reg ena,
input wire busy,
input wire [7:0] data_rd,
input wire ack_error,
input wire [7:0] sensorId,
input wire [7:0] delimeter
);
//system clock
//active low reset
//fifo pins
//latch in command
//indicates transaction in progress
//data read from slave
//flag if improper acknowledge from slave
// delimeter character
// state control signals
parameter [3:0]
  STATE_WAITREADY = 0,
  STATE_STARTREAD = 1,
  STATE_WAIT_RX = 2,
  STATE_GETBYTE = 3,
  STATE_WRITEBYTE = 4,
  STATE_FINISHWRITE = 5,
  STATE_FINISHREAD = 6,
  STATE_SLEEPCHK = 7,
  STATE_SLEEPINC = 8,
  STATE_HEADERWRITE = 9,
  STATE_HEADERIDWRITE = 10;
reg [3:0] state_reg = STATE_WAITREADY;  // recd. byte counter
reg [31:0] ByteCount = 0;
reg [31:0] delay = 0;
  // state control
  always @(posedge clk, posedge FIFO_Full, posedge busy, posedge ack_error) begin : P1
  // process to handle the next state
    case(state_reg)
    STATE_WAITREADY : begin
      //reset the timers & counters
      delay <= 0;
      ByteCount <= 0;
      // make sure not enabled
      ena <= 1'b0;
      if((busy == 1'b0)) begin
        state_reg <= STATE_STARTREAD;
      end
    end
    STATE_STARTREAD : begin
      // load the address and start a read
      ena <= 1'b1;
      if((busy == 1'b1)) begin
        state_reg <= STATE_WAIT_RX;
      end
    end
    STATE_WAIT_RX : begin
      if((busy == 1'b0 && ack_error == 1'b0)) begin
        state_reg <= STATE_GETBYTE;
      end
      else begin
        if((ack_error == 1'b1)) begin
          state_reg <= STATE_WAITREADY;
        end
      end
    end
    STATE_GETBYTE : begin
      FIFO_DataIn <= data_rd;
      state_reg <= STATE_WRITEBYTE;
    end
    STATE_WRITEBYTE : begin
      FIFO_WriteEn <= 1'b1;
      ByteCount <= ByteCount + 1;
      state_reg <= STATE_FINISHWRITE;
    end
    STATE_FINISHWRITE : begin
      FIFO_WriteEn <= 1'b0;
      if((ByteCount == 4)) begin
        state_reg <= STATE_HEADERIDWRITE;
      end
      else if((ByteCount == 5)) begin
        state_reg <= STATE_HEADERWRITE;
      end
      else if((ByteCount == 6)) begin
        state_reg <= STATE_SLEEPCHK;
      end
      else begin
        state_reg <= STATE_FINISHREAD;
      end
    end
    STATE_FINISHREAD : begin
      if((ByteCount == 3)) begin
        ena <= 1'b0;
      end
      if((busy == 1'b1)) begin
        state_reg <= STATE_WAIT_RX;
      end
    end
    STATE_HEADERWRITE : begin
      FIFO_DataIn <= delimeter;
      state_reg <= STATE_WRITEBYTE;
    end
    STATE_HEADERIDWRITE : begin
      FIFO_DataIn <= sensorId;
      state_reg <= STATE_WRITEBYTE;
    end
    STATE_SLEEPCHK : begin
      ena <= 1'b0;
      // this might not be needed anymore.
      if((delay == 100000)) begin
        state_reg <= STATE_WAITREADY;
      end
      else begin
        state_reg <= STATE_SLEEPINC;
      end
    end
    STATE_SLEEPINC : begin
      delay <= delay + 1;
      state_reg <= STATE_SLEEPCHK;
    end
    default : begin
      state_reg <= STATE_WAITREADY;
    end
    endcase
  end
endmodule

