input wire rst,
input wire input,
output reg output
);
parameter max_value = 2;
  always @(posedge clk, posedge rst) begin : P1
    reg [31:0] counter = 0;
    if(rst == 1'b1) begin
      counter = 0;
    end else begin
      if(input == 1'b1) begin
        if(counter == max_value) begin
          counter = 0;
          output <= 1'b1;
        end
        else begin
          output <= 1'b0;
          counter = counter + 1;
        end
      end
      else begin
        output <= 1'b0;
      end
    end
  end
endmodule

