module ALU(
input wire [31:0] A,
input wire [31:0] B,
input wire [3:0] sel,
output reg [31:0] result,
output reg [3:0] flags
);
reg [32:0] output; reg [32:0] normal_output;
wire [31:0] fixed_output;
  always @(A, B, sel, fixed_output, normal_output, output) begin
    //Set flags to 0 as default
    flags <= 4'b0000;
    //This actually performs the operation chosen by the select lines
    //The reason the output variable is 33 bits wide is to accomodate for
    //the carry bit, and it also helps a lot with shifting operations. By
    //the way, I did try the built-in shift operations, but without much
    //luck.
    case(sel)
    4'b0000 : begin
      //add
      normal_output <= ({1'b0,A[31:0]}) + ({1'b0,B[31:0]});
    end
    4'b0001 : begin
      //sub
      normal_output <= ({1'b0,A[31:0]}) - ({1'b0,B[31:0]});
    end
    4'b0010 : begin
      //and
      normal_output <= {1'b0,A & B};
    end
    4'b0011 : begin
      //or
      normal_output <= {1'b0,A | B};
    end
    4'b0100 : begin
      //xor
      normal_output <= {1'b0,A ^ B};
    end
    4'b0101 : begin
      //cp
      normal_output <= {1'b0,A};
    end
    4'b0110 : begin
      //sll
      normal_output <= {A[31:0],1'b0};
    end
    4'b0111 : begin
      //srl
      normal_output <= {2'b00,A[31:1]};
    end
    4'b1000 : begin
      //rol
      normal_output <= {A[0],A[0],A[31:1]};
    end
    4'b1001 : begin
      //ror
      normal_output <= {A[30],A[30:0],A[31]};
    end
    default : begin
      normal_output <= {1'b0,A};
    end
    endcase
    if(sel[3:1] == 3'b101) begin
      output <= {1'b0,fixed_output};
    end
    else begin
      output <= normal_output;
    end
    //This if statement generates the flags
    if((A > B)) begin
      //Greater than
      flags[1] <= 1'b1;
    end
    else if((A == B)) begin
      //Equal to
      flags[2] <= 1'b1;
    end
    else if((A < B)) begin
      //Less than
      flags[3] <= 1'b1;
    end
    flags[0] <= output[32];
    //Carry flag (33rd bit)
    result <= output[31:0];
  end
  FPMultiply fpmul(
      .A_in(A),
    .B_in(B),
    .R(fixed_output));
endmodule

module cpu86_top(
input wire clock_40mhz,
input wire cts,
input wire reset,
input wire rxd,
input wire [7:0] dbus_in,
output wire rts,
output wire txd,
output wire [19:0] abus,
output wire cpuerror,
output wire led2n,
output wire led3n,
output wire csramn,
output wire [7:0] dbus_out,
output wire rdn,
output wire resoutn,
output wire wrn
);
// Connected to 16750 OUT1 signal
// Connected to 16750 OUT2 signal
// Architecture declarations
wire csromn;  // Internal signal declarations
wire DCDn = 1'b1;
wire DSRn = 1'b1;
wire RIn = 1'b1;
wire clk;
wire cscom1;
wire [7:0] dbus_com1;
reg [7:0] dbus_in_cpu;
wire [7:0] dbus_rom;
