  always @(sel_s, dbus_com1, dbus_in, dbus_rom) begin
    case(sel_s)
    2'b01 : begin
      dbus_in_cpu <= dbus_com1;
      // UART     
    end
    2'b10 : begin
      dbus_in_cpu <= dbus_rom;
      // BootStrap Loader  
    end
    default : begin
      dbus_in_cpu <= dbus_in;
      // Embedded SRAM        
    end
    endcase
  end
