  assign sel_s = {cscom1,csromn};
  // chip_select 
  // Comport, uart_16750, address 0x3F8-0x3FF
  assign cscom1 = (abus_s[15:3] == 13'b0000001111111 && iom == 1'b1) ? 1'b0 : 1'b1;
  // Bootstrap ROM 256 bytes, address FFFFF-FF=FFF00
  assign csromn = ((abus_s[19:8] == 12'hFFF) && iom == 1'b0) ? 1'b0 : 1'b1;
  // SRAM 1MByte-256 bytes for the bootstrap
  assign csramn = (csromn == 1'b1 && iom == 1'b0) ? 1'b0 : 1'b1;
  assign nmi = 1'b0;
  assign intr = 1'b0;
  assign DCDn = 1'b0;
  assign DSRn = 1'b0;
  assign RIn = 1'b0;
  // Instance port mappings.
  cpu86 U_1(
      .clk(clk),
    .dbus_in(dbus_in_cpu),
    .intr(intr),
    .nmi(nmi),
    .por(por),
    .abus(abus_s),
    .cpuerror(cpuerror),
    .dbus_out(dbus_out_s),
    .inta(/* open */),
    .iom(iom),
    .rdn(rdn_s),
    .resoutn(resoutn_s),
    .wran(/* open */),
    .wrn(wrn_s));
  uart_top U_0(
      .BR_clk(rxclk_s),
    .CTSn(CTS),
    .DCDn(DCDn),
    .DSRn(DSRn),
    .RIn(RIn),
    .abus(abus_s[2:0]),
