module FIFO2Elink(
input wire clk40,
input wire clk80,
input wire clk160,
input wire RSTclk40,
input wire [17:0] efifoDin,
input wire efifoWe,
output wire efifoPfull,
input wire efifoWclk,
output reg DATA1bitOUT
);
parameter [31:0] OutputDataRate=80;
// 80 or 160 MHz
//----   
// [data_code,2bit][data,16bit]
//----
//----
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--------------------------------
//--
wire efifoRE; wire doutRdy;
wire [9:0] efifoDout;
wire [1:0] dout2bit; reg [1:0] dout2bit_r;
reg bitCount1 = 1'b0;
wire [3:0] dout4bit; reg [3:0] dout4bit_r;
reg [1:0] bitCount2 = 2'b00;  //--
  //----------------------------------------------------------
  // EPATH_FIFO
  //----------------------------------------------------------
  upstreamEpathFifoWrap UEF(
      .rst(RSTclk40),
    .fifoRstState(/* open */),
    //-
    .wr_clk(efifoWclk),
    .wr_en(efifoWe),
    .din(efifoDin),
    //-
    .rd_clk(clk160),
    .rd_en(efifoRE),
    .dout(efifoDout),
    .doutRdy(doutRdy),
    //-
    .full(/* open */),
    .almost_full(efifoPfull),
    .empty(/* open */),
    .prog_full(/* open */));
  //
  //----------------------------------------------------------
  // E-PATH case 80 MHz
  //----------------------------------------------------------
  generate if (OutputDataRate == 80) begin: OutputDataRate80
      EPROC_OUT2 EPROC_OUT2bit(
          .bitCLK(clk40),
      .bitCLKx2(clk80),
      .bitCLKx4(clk160),
      .rst(RSTclk40),
      .ENA(1'b1),
      .getDataTrig(efifoRE),
      .ENCODING(2'b10),
      // 8b10b
      .EDATA_OUT(dout2bit),
      // @ 40MHz
      .TTCin(2'b00),
      // not in use
      .DATA_IN(efifoDout),
      .DATA_RDY(doutRdy));
    //-
    always @(posedge clk80) begin
      bitCount1 <=  ~bitCount1;
    end
    //
    always @(posedge clk80) begin
      if(bitCount1 == 1'b0) begin
        dout2bit_r <= dout2bit[1];
      end
    end
    //-
    always @(posedge clk80) begin
      if(bitCount1 == 1'b0) begin
        DATA1bitOUT <= dout2bit[0];
      end
      else begin
        DATA1bitOUT <= dout2bit_r[1];
      end
    end
        //-
  end
  endgenerate
  //----------------------------------------------------------
  // E-PATH case 160 MHz
  //----------------------------------------------------------
  generate if (OutputDataRate == 160) begin: OutputDataRate160
      EPROC_OUT4 EPROC_OUT4bit(
          .bitCLK(clk40),
      .bitCLKx2(clk80),
      .bitCLKx4(clk160),
      .rst(RSTclk40),
      .ENA(1'b1),
      .getDataTrig(efifoRE),
      .ENCODING(2'b10),
      // 8b10b
      .EDATA_OUT(dout4bit),
      // @ 40MHz
      .TTCin(5'b00000),
      // not in use
      .DATA_IN(efifoDout),
      .DATA_RDY(doutRdy));
    //-
    always @(posedge clk160) begin
      bitCount2 <= bitCount2 + 1;
    end
    //
    always @(posedge clk160) begin
      if(bitCount2 == 2'b00) begin
        dout4bit_r <= dout4bit;
      end
    end
    //-
    always @(posedge clk80) begin
      case(bitCount2)
      2'b00 : begin
        DATA1bitOUT <= dout4bit[0];
      end
      2'b01 : begin
        DATA1bitOUT <= dout4bit_r[1];
      end
      2'b10 : begin
        DATA1bitOUT <= dout4bit_r[2];
      end
      2'b11 : begin
        DATA1bitOUT <= dout4bit_r[3];
      end
      default : begin
      end
      endcase
    end
        //-
  end
  endgenerate
endmodule

