module UART_TX_CTRL(
input wire SEND,
input wire [7:0] DATA,
input wire CLK,
output wire READY,
output wire UART_TX
);
parameter [1:0]
  RDY = 0,
  LOAD_BIT = 1,
  SEND_BIT = 2;
parameter BIT_TMR_MAX = 14'b10100010110000;  //10416 = (round(100MHz / 9600)) - 1
parameter BIT_INDEX_MAX = 10;
reg [13:0] bitTmr = 1'b0;
wire bitDone;
reg [31:0] bitIndex;
reg txBit = 1'b1;
reg [9:0] txData;
reg [1:0] txState = RDY;
  always @(posedge CLK) begin
    case(txState)
    RDY : begin
      if((SEND == 1'b1)) begin
        txState <= LOAD_BIT;
      end
    end
    LOAD_BIT : begin
      txState <= SEND_BIT;
    end
    SEND_BIT : begin
      if((bitDone == 1'b1)) begin
        if((bitIndex == BIT_INDEX_MAX)) begin
          txState <= RDY;
        end
        else begin
          txState <= LOAD_BIT;
        end
      end
    end
    default : begin
      txState <= RDY;
    end
    endcase
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitTmr <= {14{1'b0}};
    end
    else begin
      if((bitDone == 1'b1)) begin
        bitTmr <= {14{1'b0}};
      end
      else begin
        bitTmr <= bitTmr + 1;
      end
    end
  end
  assign bitDone = (bitTmr == BIT_TMR_MAX) ? 1'b1 : 1'b0;
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitIndex <= 0;
    end
    else if((txState == LOAD_BIT)) begin
      bitIndex <= bitIndex + 1;
    end
  end
  always @(posedge CLK) begin
    if((SEND == 1'b1)) begin
      txData <= {1'b1,DATA,1'b0};
    end
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      txBit <= 1'b1;
    end
    else if((txState == LOAD_BIT)) begin
      txBit <= txData[bitIndex];
    end
  end
  assign UART_TX = txBit;
  assign READY = (txState == RDY) ? 1'b1 : 1'b0;
endmodule

