module control(
input wire clk,
input wire reset,
input wire inicioIn,
input wire [7:0] filasBolita,
input wire [7:0] columnasJugador,
input wire [7:0] columnasBolita,
output reg visible,
output reg inicioOut,
output reg [3:0] puntajeOut,
output reg [7:0] filas,
output reg [7:0] columnas
);
parameter [1:0]
  inicio = 0,
  jugando = 1,
  victoria = 2,
  derrota = 3;
reg [1:0] estado;
reg [3:0] puntaje;
  always @(posedge clk, posedge reset, posedge inicioIn, posedge filasBolita, posedge columnasJugador, posedge columnasBolita, posedge estado, posedge puntaje) begin
    if(reset == 1'b1) begin
      estado <= inicio;
      puntaje <= 4'b0000;
      visible <= 1'b0;
      inicioOut <= 1'b1;
      puntajeOut <= 4'b0000;
      filas <= 8'b00000000;
      columnas <= 8'b00000000;
    end else begin
      case(estado)
      inicio : begin
        inicioOut <= 1'b1;
        visible <= 1'b0;
        puntaje <= 4'b0000;
        if((inicioIn == 1'b1)) begin
          estado <= jugando;
        end
      end
      jugando : begin
        inicioOut <= 1'b0;
        visible <= 1'b0;
        if(filasBolita == 8'b10000000) begin
          if(columnasJugador == columnasBolita) begin
            if((puntaje == 9)) begin
              estado <= victoria;
            end
            else begin
              puntaje <= puntaje + 1;
              puntajeOut <= puntaje + 1;
            end
          end
          else begin
            estado <= derrota;
          end
        end
      end
      victoria : begin
        inicioOut <= 1'b1;
        visible <= 1'b1;
        filas <= 8'b10000001;
        columnas <= 8'b11111111;
        if(inicioIn == 1'b1) begin
          estado <= inicio;
        end
      end
      derrota : begin
        inicioOut <= 1'b1;
        visible <= 1'b1;
        filas <= 8'b11111111;
        columnas <= 8'b11111111;
        if(inicioIn == 1'b1) begin
          estado <= inicio;
        end
      end
      endcase
    end
  end
endmodule

