module segment_out(
input wire clk,
input wire ready,
input wire reset,
input wire [7:0] scancode,
output reg [14:0] segments
);
reg isE0; reg isF0; reg stw_q;
wire [6:0] segment_repr;
reg [31:0] clock_divide_counter;
reg [31:0] current_digit;
reg [6:0] digit0;
reg [6:0] digit1;
reg [6:0] digit2;
reg [6:0] digit3;
reg [6:0] digit4;
reg [6:0] digit5;
reg [6:0] digit6;
reg [6:0] digit7;
  seg_scancode_to_segments seg_scancode_to_segments0(
      scancode,
    segment_repr);
  always @(scancode) begin
    if((scancode == 8'b11100000)) begin
      isE0 <= 1'b1;
    end
    else begin
      isE0 <= 1'b0;
    end
    if((scancode == 8'b11110000)) begin
      isF0 <= 1'b1;
    end
    else begin
      isF0 <= 1'b0;
    end
  end
  always @(posedge isE0, posedge isF0, posedge ready, posedge clk) begin
    if(stw_q == 1'b0) begin
      if(isE0 == 1'b0 && isF0 == 1'b0) begin
        digit7 <= digit6;
        digit6 <= digit5;
        digit5 <= digit4;
        digit4 <= digit3;
        digit3 <= digit2;
        digit2 <= digit1;
        digit1 <= digit0;
        digit0 <= segment_repr;
      end
      else if(isE0 == 1'b0 && isF0 == 1'b1) begin
        stw_q <= 1'b1;
      end
    end
    else begin
      stw_q <= 1'b0;
    end
  end
  always @(posedge clk) begin
    if(clock_divide_counter >= 99999) begin
      clock_divide_counter <= 0;
      current_digit <= current_digit + 1;
      // overflows automatically with mod 8
    end
    else begin
      clock_divide_counter <= clock_divide_counter + 1;
    end
  end
  always @(current_digit) begin
    if(current_digit == 0) begin
      segments <= {8'b11111110,digit0};
    end
    else if(current_digit == 1) begin
      segments <= {8'b11111101,digit1};
    end
    else if(current_digit == 2) begin
      segments <= {8'b11111011,digit2};
    end
    else if(current_digit == 3) begin
      segments <= {8'b11110111,digit3};
    end
    else if(current_digit == 4) begin
      segments <= {8'b11101111,digit4};
    end
    else if(current_digit == 5) begin
      segments <= {8'b11011111,digit5};
    end
    else if(current_digit == 6) begin
      segments <= {8'b10111111,digit6};
    end
    else begin
      segments <= {8'b01111111,digit7};
    end
  end
endmodule

