module Full_Adder_Bit(
input wire A,
input wire B,
input wire c,
output wire sout,
output wire Cout
);
  // 1-bit Adder definition
  assign Sout = A ^ B ^ c;
  assign Cout = (A & B) | (A & c) | (B & c);
endmodule

module datamemory(
input wire [31:0] Address,
input wire [31:0] WriteData,
input wire MemWrite,
input wire MemRead,
output reg [31:0] ReadData,
output reg [3:0] O_LMotor,
output reg [3:0] O_RMotor,
input wire [6:0] I_Sensors,
output reg [6:0] O_Leds,
input wire [2:0] I_Rf,
output reg O_Buzzer,
output reg [7:0] O_Seg,
output reg [2:0] O_El_7l,
input wire [5:0] I_St_7l,
input wire I_Clock
);
  // Memory Map
  // 0x000
  // 0x001
  // 0x010  Set motors
  // 0x020  Set leds
  // 0x021  Get Sensors
  // 0x030  Get RF
  // 0x031  Set BUZZER
  // 0x032  Set SEG
  // 0x033  Set EL_7L
  // 0x034  Get ST_7L
  always @(posedge I_Clock) begin
    if((MemRead == 1'b1)) begin
      case(Address)
      32'b00000000000000000000000000100001 : begin
        ReadData[6:0] <= I_Sensors[6:0];
        ReadData[31:7] <= 25'b0000000000000000000000000;
      end
      32'b00000000000000000000000000110000 : begin
        ReadData[2:0] <= I_Rf[2:0];
        ReadData[31:3] <= 29'b00000000000000000000000000000;
      end
      32'b00000000000000000000000000110100 : begin
        ReadData[5:0] <= I_St_7l[5:0];
        ReadData[31:6] <= 26'b00000000000000000000000000;
      end
      default : begin
        ReadData <= 32'b00000000000000000000000000000000;
      end
      endcase
    end
  end
  always @(posedge I_Clock) begin
    if((MemWrite == 1'b1)) begin
      case(Address)
      32'b00000000000000000000000000010000 : begin
        O_RMotor <= WriteData[3:0];
        O_LMotor <= WriteData[7:4];
      end
      32'b00000000000000000000000000100000 : begin
        O_Leds <= WriteData[6:0];
      end
      32'b00000000000000000000000000110001 : begin
        O_Buzzer <= WriteData[0];
      end
      32'b00000000000000000000000000110010 : begin
        O_Seg <= WriteData[7:0];
      end
      32'b00000000000000000000000000110011 : begin
        O_El_7l <= WriteData[2:0];
      end
      default : begin
      end
      endcase
    end
  end
endmodule

`timescale 1 ns / 1 ns
module Ram_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [12:0] ADDRA = 1'b0;
reg [12:0] ADDRA_R = 1'b0;
wire [31:0] DINA = 1'b0;
reg [31:0] DINA_R = 1'b0;
wire [31:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(32),
    .READ_WIDTH(32))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {32{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {13{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  Ram_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

module djb_clock_sync(
input wire hr_clk,
input wire reset,
input wire seq_idle,
input wire lvds_i,
output wire main_clk,
output wire seq_reset,
output reg sync_early,
output reg sync_late,
output wire test_seq_reset_internal,
output wire test_sync_2,
output wire test_sync
);
//
reg [1:0] divider;
reg seq_reset_i;
reg lvds_i_sampled; reg last_lvds_i;
  assign test_seq_reset_internal = seq_reset_i;
  assign seq_reset = seq_reset_i;
  assign test_sync = 1'b0;
  assign test_sync_2 = 1'b0;
  always @(posedge hr_clk, posedge reset) begin
    if(reset == 1'b1) begin
      lvds_i_sampled <= 1'b0;
    end else begin
      lvds_i_sampled <= lvds_i;
    end
  end
  always @(posedge hr_clk, posedge reset) begin
    if(reset == 1'b1) begin
      // Initialize internal signals
      divider <= {2{1'b1}};
      last_lvds_i <= 1'b0;
      seq_reset_i <= 1'b0;
      sync_early <= 1'b0;
      sync_late <= 1'b0;
    end else begin
      //Signal initial values
      sync_early <= 1'b0;
      sync_late <= 1'b0;
      //
      if(seq_idle == 1'b1 && seq_reset_i == 1'b0 && last_lvds_i == 1'b0 && lvds_i_sampled == 1'b1) begin
        // Reset sequencer, this will cause the sequencer to disable seq_idle
        seq_reset_i <= 1'b1;
        divider <= 2'b10;
        // Do we need to synchronize?
        case(divider)
        2'b01 : begin
          // If the LVDS edge is perfectly in sync, divider will be 01
          // and about to go to 10 (because lvds_i has  been sampled, delayed 1 clock, plus extra 1  sample delay for no reason)
                  end
        2'b00 : begin
          // Sync edge happened slightly early
          sync_early <= 1'b1;
        end
        2'b10 : begin
          // Sync edge happened slightly late
          sync_late <= 1'b1;
        end
        default : begin
          // Bad
          sync_early <= 1'b1;
          sync_late <= 1'b1;
        end
        endcase
      end
      else begin
        // Turn off reset if the sequencer is no longer idle 
        if(divider == 2'b01 && seq_idle == 1'b0) begin
          //Going to be falling edge of main_clk
          seq_reset_i <= 1'b0;
        end
        // Increment clock
        divider <= divider + 1;
      end
      // Store last data
      last_lvds_i <= lvds_i_sampled;
    end
  end
  // Inverted divide by 4 counter
  assign main_clk =  ~divider[1];
endmodule

