module ULA(
input wire [31:0] IN_A,
input wire [31:0] IN_B,
input wire [2:0] IN_C,
output wire [31:0] OUT_A,
output wire ZERO
);
//RS
//RT
wire [31:0] DATA_RS;
wire [31:0] DATA_RT;
wire [2:0] ULA_CTRL;
reg [31:0] DATA_ALU_RESULT;
  assign DATA_RS = IN_A;
  assign DATA_RT = IN_B;
  assign ULA_CTRL = IN_C;
  assign ZERO = (DATA_ALU_RESULT == 32'h00000000) ? 1'b1 : 1'b0;
  //PARA A INSTRUO SLT, PEGA O SINAL DO RESULTADO DA SUBTRAO E ADICIONA AO FINAL DO VETOR
  assign OUT_A = ULA_CTRL == 3'b111 ? {28'h0000000,3'b000,DATA_ALU_RESULT[31]} : DATA_ALU_RESULT;
  always @(ULA_CTRL, DATA_RS, DATA_RT) begin
    case(ULA_CTRL)
    3'b000 : begin
      DATA_ALU_RESULT <= DATA_RS & DATA_RT;
      //AND
    end
    3'b001 : begin
      DATA_ALU_RESULT <= DATA_RS | DATA_RT;
      //OR
    end
    3'b010 : begin
      DATA_ALU_RESULT <= DATA_RS + DATA_RT;
      //ADD
    end
    3'b110 : begin
      DATA_ALU_RESULT <= DATA_RS - DATA_RT;
      //SUB
    end
    3'b111 : begin
      DATA_ALU_RESULT <= DATA_RS - DATA_RT;
      //SLT			
    end
    default : begin
      DATA_ALU_RESULT <= 32'h00000000;
    end
    endcase
  end
endmodule

module bcdTo7SEG(
input wire clk,
input wire [3:0] bcd,
output reg [6:0] segmented
);
  always @(posedge clk) begin
    case(bcd)
    4'b0000 : begin
      segmented <= 7'b0000001;
    end
    4'b0001 : begin
      segmented <= 7'b1001111;
    end
    4'b0010 : begin
      segmented <= 7'b0010010;
    end
    4'b0011 : begin
      segmented <= 7'b0000110;
    end
    4'b0100 : begin
      segmented <= 7'b1001100;
    end
    4'b0101 : begin
      segmented <= 7'b0100100;
    end
    4'b0110 : begin
      segmented <= 7'b0100000;
    end
    4'b0111 : begin
      segmented <= 7'b0001111;
    end
    4'b1000 : begin
      segmented <= 7'b0000000;
    end
    4'b1001 : begin
      segmented <= 7'b0000100;
    end
    default : begin
      segmented <= 7'b1111111;
    end
    endcase
  end
endmodule

module WM8731(
input wire clock_i,
input wire reset_i,
output wire k7_audio_o,
input wire [15:0] audio_l_i,
input wire [15:0] audio_r_i,
output wire i2s_xck_o,
output wire i2s_bclk_o,
output wire i2s_adclrck_o,
input wire i2s_adcdat_i,
output wire i2s_daclrck_o,
output wire i2s_dacdat_o,
inout wire i2c_sda_io,
inout wire i2c_scl_io
);
// Clock 24 MHz
// Reset geral
// Ligar nos pinos do TOP
// Ligar no pino I2C SDA
// Ligar no pino I2C SCL
// 32767	0111111111111111
//
// 1		0000000000000001
// 0		0000000000000000
// -1		1111111111111111
//
// -32768	1000000000000000
wire pcm_lrclk_s;
reg ear_r;
wire [15:0] pcm_inl_s;
wire [15:0] pcm_l_s;
wire [15:0] pcm_r_s;
  //
  i2c_loader #(
      .device_address('H1a),
    // Address of slave to be loaded
    .num_retries(0),
    // Number of retries to allow before stopping
    // Length of clock divider in bits.  Resulting bus frequency is
    // CLK/2^(log2_divider + 2)
    .log2_divider(7))
  i2c(
      .clock_i(clock_i),
    .reset_i(reset_i),
    .i2c_scl_io(i2c_scl_io),
    .i2c_sda_io(i2c_sda_io),
    .is_done_o(/* open */),
    .is_error_o(/* open */));
  //
  i2s_intf #(
      .mclk_rate(12000000),
    .sample_rate(48000),
    .preamble(1),
    // I2S
    .word_length(16))
  i2s(
      // 2x MCLK in (e.g. 24 MHz for WM8731 USB mode)
    .clock_i(clock_i),
    .reset_i(reset_i),
    // Parallel IO
    .pcm_inl_o(pcm_inl_s),
    .pcm_inr_o(/* open */),
    .pcm_outl_i(pcm_l_s),
    .pcm_outr_i(pcm_r_s),
    // Codec interface (right justified mode)
    // MCLK is generated at half of the CLK input
    .i2s_mclk_o(i2s_xck_o),
    // LRCLK is equal to the sample rate and is synchronous to
    // MCLK.  It must be related to MCLK by the oversampling ratio
    // given in the codec datasheet.
    .i2s_lrclk_o(pcm_lrclk_s),
    // Data is shifted out on the falling edge of BCLK, sampled
    // on the rising edge.  The bit rate is determined such that
    // it is fast enough to fit preamble + word_length bits into
    // each LRCLK half cycle.  The last cycle of each word may be 
    // stretched to fit to LRCLK.  This is OK at least for the 
    // WM8731 codec.
    // The first falling edge of each timeslot is always synchronised
    // with the LRCLK edge.
    .i2s_bclk_o(i2s_bclk_o),
    // Output bitstream
    .i2s_d_o(i2s_dacdat_o),
    // Input bitstream
    .i2s_d_i(i2s_adcdat_i));
  assign i2s_adclrck_o = pcm_lrclk_s;
  assign i2s_daclrck_o = pcm_lrclk_s;
  assign pcm_l_s = audio_l_i;
  assign pcm_r_s = audio_r_i;
  assign k7_audio_o = ear_r;
  // Hysteresis
  always @(posedge clock_i) begin : P1
    reg [31:0] in_val_v;
    in_val_v = pcm_inl_s;
    if(in_val_v < ( -15)) begin
      ear_r <= 1'b0;
    end
    else if(in_val_v > 15) begin
      ear_r <= 1'b1;
    end
  end
endmodule

module spi_receiver(
input wire clk,
input wire sck,
input wire data,
input wire cs_n,
output reg irq,
output reg [7:0] parallel_out
);
reg sck_prev = 1'b0;
reg cs_prev = 1'b0;
reg [7:0] shift_reg = 1'b0;
reg irq_delay = 1'b1;
  always @(posedge clk) begin
    if(((sck != sck_prev) && (sck == 1'b1))) begin
      if((cs_n == 1'b0)) begin
        shift_reg <= {shift_reg[6:0],data};
      end
    end
    sck_prev <= sck;
  end
  always @(posedge clk) begin
    if((irq_delay == 1'b0)) begin
      irq <= 1'b0;
    end
    else begin
      irq_delay <= 1'b0;
    end
    if(((cs_n != cs_prev) && (cs_n == 1'b1))) begin
      parallel_out <= shift_reg;
      irq <= 1'b1;
      irq_delay <= 1'b1;
    end
    cs_prev <= cs_n;
  end
endmodule

module ece324_pulse_generator(
input wire clk,
input wire oneStep,
input wire [3:0] duty_cycle,
input wire reset,
input wire enable,
output reg pulse
);
reg [3:0] count;
reg generatedSignal;
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      count <= 4'b1111;
    end
    else if((enable == 1'b1)) begin
      if((count == 4'b1111)) begin
        count <= 4'b0000;
      end
      else begin
        count <= count + 1;
      end
    end
    if((count < duty_cycle)) begin
      generatedSignal <= 1'b1;
    end
    else begin
      generatedSignal <= 1'b0;
    end
  end
  // clocked multiplexer
  always @(posedge clk) begin
    if((duty_cycle == 4'b0000)) begin
      pulse <= oneStep;
    end
    else begin
      pulse <= generatedSignal;
    end
  end
endmodule

module clk_div(
input wire clk,
input wire reset,
input wire [31:0] div,
output reg div_clk
);
parameter [31:0] MAXD=5;
  always @(posedge clk, posedge reset) begin : P1
    reg [31:0] M;
    if(reset == 1'b1) begin
      //reset clock divider 
      M = 0;
      div_clk <= 1'b0;
    end else begin
      // generate a pulse when the counter = (the division magnitude -1)  
      if(M == (div - 1)) begin
        div_clk <= 1'b1;
        M = 0;
      end
      else begin
        M = M + 1;
        div_clk <= 1'b0;
      end
    end
  end
endmodule

module mod_bcd(
