      segment7 <= 7'b0111111;
      // '-'
    end
    else begin
      case(bcd)
      4'b0000 : begin
        segment7 <= 7'b1000000;
        // '0'
      end
      4'b0001 : begin
        segment7 <= 7'b1111001;
        // '1'
      end
      4'b0010 : begin
        segment7 <= 7'b0100100;
        // '2'
      end
      4'b0011 : begin
        segment7 <= 7'b0110000;
        // '3'
      end
      4'b0100 : begin
        segment7 <= 7'b0011001;
        // '4'
      end
      4'b0101 : begin
        segment7 <= 7'b0010010;
        // '5'
      end
      4'b0110 : begin
        segment7 <= 7'b0000010;
        // '6'
      end
      4'b0111 : begin
        segment7 <= 7'b1111000;
        // '7'
      end
      4'b1000 : begin
        segment7 <= 7'b0000000;
        // '8'
      end
      4'b1001 : begin
        segment7 <= 7'b0010000;
        // '9'
      end
      4'b1010 : begin
        segment7 <= 7'b0001000;
        // 'A'
      end
      4'b1011 : begin
        segment7 <= 7'b0000011;
        // 'B'
      end
      4'b1100 : begin
        segment7 <= 7'b1000110;
        // 'C'
      end
      4'b1101 : begin
        segment7 <= 7'b0100001;
        // 'D'
      end
      4'b1110 : begin
        segment7 <= 7'b0000110;
        // 'E'
      end
      4'b1111 : begin
        segment7 <= 7'b0001110;
        // 'F'
      end
      default : begin
        segment7 <= 7'b0111111;
        // '-'
      end
      endcase
    end
  end
endmodule

