module background_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
parameter [31:0] C_ROM_SYNTH=1;
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [16:0] ADDRA = 1'b0;
reg [16:0] ADDRA_R = 1'b0;
wire [11:0] DOUTA;
wire CHECKER_EN = 1'b0;
wire CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  BMG_STIM_GEN #(
      .C_ROM_SYNTH(C_ROM_SYNTH))
  BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((ADDRA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
    end
    else begin
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {17{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  background_exdes BMG_PORT(
      //Port A
    .ADDRA(ADDRA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

module sounds(
input wire clk,
input wire not_reset,
input wire enable,
input wire [18:0] period,
input wire [2:0] volume,
output wire buzzer
);
reg [18:0] counter; wire [18:0] counter_next;
wire [18:0] pulse_width;
  always @(negedge clk, negedge not_reset) begin
    if(not_reset == 1'b0) begin
      counter <= {19{1'b0}};
    end else begin
      counter <= counter_next;
    end
  end
  // duty cycle:
  //    max:   50% (18 downto 1)
  //    min: 0.78% (18 downto 7)
  //    off when given 0 (18 downto 0)!
  assign pulse_width = period[18:volume];
  assign counter_next = counter == period ? {19{1'b0}} : counter + 1;
  assign buzzer = (enable == 1'b1 && counter < pulse_width) ? 1'b1 : 1'b0;
endmodule

module fifo(
input wire rst,
input wire clk,
input wire [7:0] dia,
input wire ena,
output wire full,
output reg [7:0] dob,
input wire enb,
output wire empty
);
reg [10:0] addra;
reg [10:0] addrb;
reg [7:0] mem[2047:0];
wire empty_i;
wire full_i;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      addra <= {11{1'b0}};
      addrb <= {11{1'b0}};
    end
    else begin
      if(ena == 1'b1 && full_i == 1'b0) begin
        mem[addra] <= dia;
        addra <= addra + 1;
      end
      if(enb == 1'b1 && empty_i == 1'b0) begin
        dob <= mem[addrb];
        addrb <= addrb + 1;
      end
    end
  end
  assign empty_i = addra == addrb ? 1'b1 : 1'b0;
  assign full_i = addra == (addrb - 1) ? 1'b1 : 1'b0;
  assign empty = empty_i;
  assign full = full_i;
endmodule

