  // behave
  assign c = control[2];
  assign bb = control[2] == 1'b1 ?  ~b : b;
  assign o0 = a & bb;
  assign o1 = a | b;
  assign o2 = a + bb + c;
  assign o3 = {28'h0000000,3'b000,o2[31]};
  assign out_buf = control[1:0] == 2'b00 ? o0 : control[1:0] == 2'b01 ? o1 : control[1:0] == 2'b10 ? o2 : ;
  assign output = out_buf;
  assign zero = out_buf == 32'h00000000 ? 1'b1 : 1'b0;
