module RAM_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [3:0] WEA = 1'b0;
reg [3:0] WEA_R = 1'b0;
wire [7:0] ADDRA = 1'b0;
reg [7:0] ADDRA_R = 1'b0;
wire [31:0] DINA = 1'b0;
reg [31:0] DINA_R = 1'b0;
wire [31:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(32),
    .READ_WIDTH(32))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {4{1'b0}};
      DINA_R <= # 50 {32{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {8{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  RAM_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

