module uart(
output wire uart_tx,
input wire [7:0] data_in,
output reg ready,
input wire send_data,
input wire rst,
input wire clk
);
parameter [31:0] clk_freq=50000000;
parameter [31:0] baud_rate=115200;
parameter [1:0]
  reset = 0,
  waiting = 1,
  sending = 2;
reg [1:0] curr_state;
reg [31:0] clock_divide = 0;
reg slow_clock = 1'b0;
reg uart_tx_sig;
reg [31:0] current_bit;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      clock_divide <= 0;
      slow_clock <= 1'b0;
    end else begin
      clock_divide <= clock_divide + 1;
      if((clock_divide == 215)) begin
        // 651->38400 baud
        clock_divide <= 0;
        slow_clock <=  ~slow_clock;
      end
    end
  end
  always @(posedge slow_clock, posedge rst) begin
    if((rst == 1'b1)) begin
      curr_state <= reset;
    end else begin
      case(curr_state)
      reset : begin
        uart_tx_sig <= 1'b1;
        curr_state <= waiting;
      end
      waiting : begin
        ready <= 1'b1;
        current_bit <= 0;
        uart_tx_sig <= 1'b1;
        if((send_data == 1'b1)) begin
          curr_state <= sending;
        end
      end
      sending : begin
        ready <= 1'b0;
        current_bit <= current_bit + 1;
        if((current_bit == 9)) begin
          current_bit <= 0;
          uart_tx_sig <= 1'b1;
          curr_state <= waiting;
        end
        else if((current_bit == 0)) begin
          uart_tx_sig <= 1'b0;
        end
        else begin
          uart_tx_sig <= data_in[current_bit - 1];
        end
      end
      endcase
    end
  end
  assign uart_tx = uart_tx_sig;
endmodule

