module i2s_serializer_old(
input wire clock,
input wire reset,
output reg i2s_out,
input wire i2s_in,
output reg i2s_bclk,
output reg i2s_fs,
output reg [23:0] stream_out_data,
output reg [0:0] stream_out_tag,
output reg stream_out_valid,
input wire [23:0] stream_in_data,
input wire [0:0] stream_in_tag,
input wire stream_in_valid,
output reg stream_in_ready
);
// equals i2s_mclk
reg [7:0] bit_count;
reg [31:0] shift_reg = 1'b0;
  // mclk = 256*fs. bclk = 64*fs (32 bits per channel)
  always @(posedge clock) begin
    bit_count <= bit_count + 1;
    i2s_bclk <= bit_count[1];
    i2s_fs <= bit_count[7];
    stream_in_ready <= 1'b0;
    stream_out_valid <= 1'b0;
    if(bit_count[1:0] == 2'b00) begin
      i2s_out <= shift_reg[(31)];
    end
    else if(bit_count[1:0] == 2'b10) begin
      shift_reg <= {shift_reg[(31) - 1:0],i2s_in};
    end
    if(bit_count[6:0] == 7'b1111110) begin
      stream_out_data <= shift_reg[(31) - 2:(31) - 25];
      stream_out_tag[0] <= bit_count[7];
      stream_out_valid <= 1'b1;
      if(stream_in_valid == 1'b1 && ((bit_count[7] ^ stream_in_tag[0]) == 1'b1)) begin
        shift_reg <= {1'b0,stream_in_data,7'b0000000};
        stream_in_ready <= 1'b1;
      end
      else begin
        shift_reg <= {32{1'b0}};
      end
    end
    if(reset == 1'b1) begin
      bit_count <= {8{1'b1}};
      i2s_out <= 1'b0;
      stream_in_ready <= 1'b0;
      stream_out_valid <= 1'b0;
    end
  end
endmodule

