module square(
input wire [15:0] number,
input wire clock,
output reg [15:0] output,
output reg done
);
parameter [1:0]
  INITIAL = 0,
  OPERATION = 1,
  FINAL = 2;
reg [1:0] state;
reg [15:0] n; reg [15:0] d; reg [15:0] r;
  always @(posedge clock) begin
    case(state)
    INITIAL : begin
      n <= number;
      d <= 15'b000000000000001;
      r <= 15'b000000000000000;
      done <= 1'b0;
      state <= OPERATION;
    end
    OPERATION : begin
      if((n > 0)) begin
        n <= n - d;
        d <= d + 2;
        r <= r + 1;
        done <= 1'b0;
        state <= OPERATION;
      end
      else begin
        state <= FINAL;
      end
    end
    FINAL : begin
      output <= r;
      done <= 1'b1;
      state <= INITIAL;
    end
    default : begin
      done <= 1'b0;
      state <= INITIAL;
    end
    endcase
  end
endmodule

