wire [2:0] alpha4;
wire [2:0] D1;
wire [2:0] D2;
wire [2:0] Q1;
wire [2:0] Q2;
wire [2:0] C0;
wire [2:0] multa1;
wire [2:0] multa2;
  assign alpha3[0] = 1'b0;
  assign alpha3[1] = 1'b1;
  assign alpha3[2] = 1'b1;
  assign alpha4[0] = 1'b1;
  assign alpha4[1] = 1'b1;
  assign alpha4[2] = 1'b0;
  flipflop ff1(
