      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(16),
    .READ_WIDTH(16))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {16{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {5{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  instruction_memory_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
