module FSM_clock(
input wire clock,
input wire reset,
output reg c1,
output reg c2
);
reg [31:0] contador_1 = 0; reg [31:0] contador_2 = 0;  //definido signal como inteiro para os valores da frequência de entrada e 1/4 dela.
  always @(posedge clock, posedge reset) begin : P2
  //process que vai definir o clock de 1hz para o contador ascendente do tempo.
    if(reset == 1'b0) begin
      contador_1 <= 0;
    end else begin
      contador_1 <= contador_1 + 1;
      if(contador_1 >= 50000000) begin
        contador_1 <= 0;
        c1 <= 1'b1;
      end
      else begin
        c1 <= 1'b0;
      end
    end
  end
  always @(posedge clock, posedge reset) begin : P1
  //vai definir o clock de 4hz para a contagem decrescente dos créditos.
    if(reset == 1'b0) begin
      contador_2 <= 0;
    end else begin
      contador_2 <= contador_2 + 1;
      if(contador_2 >= 12500000) begin
        contador_2 <= 0;
        c2 <= 1'b1;
      end
      else begin
        c2 <= 1'b0;
      end
    end
  end
endmodule

