module mips(
input wire [31:0] inInstruction,
input wire Clk,
input wire reset,
output wire O_Fetch,
output wire [31:0] O_PCNext,
output wire [31:0] outMemAddr,
output wire outMemRead,
input wire [31:0] inMemReadData,
input wire inMemRead,
output wire outMemWrite,
output wire [31:0] outMemWriteData
);
//error_control   : out std_logic
wire fetch = 1'b1;
wire alu_pause = 1'b0;
wire [11:0] operationD = 1'b0;
wire [31:0] pcnext = 1'b0;
wire [31:0] pcF = 1'b0;
wire [31:0] instructionExtended = 1'b0;
wire [31:0] instructionExtPC = 1'b0;
wire alu_zero = 1'b0;
wire [31:0] alu_result = 1'b0;
wire [31:0] alu_mem_write = 1'b0;
wire [5:0] alu_opcode = 1'b0;
wire [5:0] alu_func = 1'b0;
wire [4:0] alu_shamt = 1'b0;
wire [4:0] InstReg1 = 1'b0;
wire [4:0] InstReg2 = 1'b0;
wire [4:0] InstReg3 = 1'b0;
wire memtoreg = 1'b0;
wire memread = 1'b0;
wire memwrite = 1'b0;
wire jump = 1'b0;
wire jumptoreg = 1'b0;
wire branch = 1'b0;
wire discard = 1'b0;
reg [31:0] clk_counter = 0;
  assign O_PCNext = pcnext;
  assign O_Fetch =  ~alu_pause;
  always @(posedge clk) begin
    clk_counter <= clk_counter + 1;
  end
  //------------------------------------------------------------------
  // STAGE 1 FETCH/DECODE
  //------------------------------------------------------------------
  DECODER DECODER0(
      clk,
    ininstruction,
    pcnext,
    discard,
    operationD,
    alu_opcode,
    alu_func,
    alu_shamt,
    pcF,
    InstReg1,
    InstReg2,
    InstReg3,
    fetch);
  SIGNEXTEND SIGNEXTEND0(
      clk,
    ininstruction[15:0],
    instructionExtended);
  //------------------------------------------------------------------
  // STAGE 2
  //------------------------------------------------------------------
  ALU ALU0(
      clk,
    reset,
    pcF,
    alu_opcode,
    alu_func,
    alu_shamt,
    InstReg1,
    InstReg2,
    InstReg3,
    instructionExtended,
    operationD,
    fetch,
    inMemReadData,
    inMemRead,
    memtoreg,
    memread,
    memwrite,
    alu_zero,
    alu_result,
    alu_mem_write,
    alu_pause);
  PC_BRIDGE PC_BRIDGE0(
      clk,
    operationD,
    instructionExtended,
    instructionExtPC,
    jump,
    branch,
    jumptoreg);
  //------------------------------------------------------------------
  // STAGE 3 Memory
  //------------------------------------------------------------------
  MEMORY_RW MEMORY_RW0(
      clk,
    alu_result,
    alu_mem_write,
    memtoreg,
    memread,
    memwrite,
    outMemAddr,
    outMemRead,
    outMemWrite,
    outMemWriteData);
  PC_NEXT PC_NEXT0(
      clk,
    reset,
    instructionExtPC,
    alu_result,
    alu_pause,
    alu_zero,
    jump,
    branch,
    jumptoreg,
    discard,
    pcnext);
endmodule

module i2c_arbiter_ss_detector(
input wire clk_i,
input wire rst_n_i,
input wire input_sda_i,
input wire input_scl_i,
input wire start_ack_i,
input wire stop_ack_i,
output reg start_state_o,
output reg stop_state_o
);
// Clock & Reset
// I2C input buses & ACK
// Start/Stop outputs
// Start FSM signals
parameter [1:0]
  ARB_START_IDLE = 0,
  ARB_START_WAIT_SDA = 1,
  ARB_START_DETECTED = 2;
reg [1:0] arb_start_st = ARB_START_IDLE;  // Stop FSM signals
parameter [1:0]
  ARB_STOP_IDLE = 0,
  ARB_STOP_WAIT_SDA = 1,
  ARB_STOP_DETECTED = 2;
reg [1:0] arb_stop_st = ARB_STOP_IDLE;
  // Start FSM
  always @(posedge clk_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      arb_start_st <= ARB_START_IDLE;
      start_state_o <= 1'b0;
    end
    else begin
      case(arb_start_st)
      ARB_START_IDLE : begin
        start_state_o <= 1'b0;
        if(input_sda_i == 1'b1 && input_scl_i == 1'b1) begin
          arb_start_st <= ARB_START_WAIT_SDA;
        end
      end
      ARB_START_WAIT_SDA : begin
        if(input_scl_i == 1'b1) begin
          if(input_sda_i == 1'b0) begin
            start_state_o <= 1'b1;
            arb_start_st <= ARB_START_DETECTED;
          end
        end
        else begin
          start_state_o <= 1'b0;
          arb_start_st <= ARB_START_IDLE;
        end
      end
      ARB_START_DETECTED : begin
        if(start_ack_i == 1'b1) begin
          start_state_o <= 1'b0;
          arb_start_st <= ARB_START_IDLE;
        end
      end
      default : begin
        start_state_o <= 1'b0;
        arb_start_st <= ARB_START_IDLE;
      end
      endcase
    end
  end
  // Stop FSM
  always @(posedge clk_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      arb_stop_st <= ARB_STOP_IDLE;
      stop_state_o <= 1'b0;
    end
    else begin
      case(arb_stop_st)
      ARB_STOP_IDLE : begin
        stop_state_o <= 1'b0;
        if(input_scl_i == 1'b1 && input_sda_i == 1'b0) begin
          arb_stop_st <= ARB_STOP_WAIT_SDA;
        end
      end
      ARB_STOP_WAIT_SDA : begin
        if(input_scl_i == 1'b1) begin
          if(input_sda_i == 1'b1) begin
            stop_state_o <= 1'b1;
            arb_stop_st <= ARB_STOP_DETECTED;
          end
        end
        else begin
          stop_state_o <= 1'b0;
          arb_stop_st <= ARB_STOP_IDLE;
        end
      end
      ARB_STOP_DETECTED : begin
        if(stop_ack_i == 1'b1) begin
          stop_state_o <= 1'b0;
          arb_stop_st <= ARB_STOP_IDLE;
        end
      end
      default : begin
        stop_state_o <= 1'b0;
        arb_stop_st <= ARB_STOP_IDLE;
      end
      endcase
    end
  end
endmodule

module Rotary(
input wire clock,
input wire A,
input wire B,
output reg inc,
output reg dec
);
reg prevA; reg prevB;
reg currA; reg currB;
  always @(posedge clock) begin
    prevA <= currA;
    prevB <= currB;
    currA <= A;
    currB <= B;
    if(prevA == 1'b0 && currA == 1'b1) begin
      // a rising
      if(currB == 1'b1) begin
        inc <= 1'b0;
        dec <= 1'b1;
      end
      else if(currB == 1'b0) begin
        inc <= 1'b1;
        dec <= 1'b0;
      end
    end
    else if(prevA == 1'b1 && currA == 1'b0) begin
      // a falling
      if(currB == 1'b1) begin
        inc <= 1'b1;
        dec <= 1'b0;
      end
      else if(currB == 1'b0) begin
        inc <= 1'b0;
        dec <= 1'b1;
      end
    end
    else if(prevB == 1'b0 && currB == 1'b1) begin
      // b rising
      if(currA == 1'b1) begin
        inc <= 1'b1;
        dec <= 1'b0;
      end
      else if(currA == 1'b0) begin
        inc <= 1'b0;
        dec <= 1'b1;
      end
    end
    else if(prevB == 1'b1 && currB == 1'b0) begin
      // b falling
      if(currA == 1'b1) begin
        inc <= 1'b0;
        dec <= 1'b1;
      end
      else if(currA == 1'b0) begin
        inc <= 1'b1;
        dec <= 1'b0;
      end
    end
    else begin
      inc <= 1'b0;
      dec <= 1'b0;
    end
  end
endmodule

