module hcc_alulong(
input wire sysclk,
input wire reset,
input wire enable,
input wire addsub,
input wire [32:1] aa,
input wire [32:1] bb,
output wire [32:1] cc
);
wire [31:1] zerovec;
wire [32:1] bbvec;
reg [32:1] aluff;
  genvar k;
  generate for (k=1; k <= 31; k = k + 1) begin: gza
      assign zerovec[k] = 1'b0;
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 32; k = k + 1) begin: gaa
      assign bbvec[k] = bb[k] ^ addsub;
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 32; k = k + 1) begin
        aluff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        aluff <= aa + bbvec + ({zerovec,addsub});
      end
    end
  end
  assign cc = aluff;
endmodule

module system(
input wire rst,
input wire clk,
input wire btn0,
input wire rxd,
output wire txd,
output wire evn1,
output wire evn2,
output wire led0,
output wire led1
);
// system reset, high active
// system clock, 50 MHz, rising edge active
// push button, low active
// receiver signal
// transmitter signal
// event1, interrupt, high active
// event2, RETURNI, high active
// led, low active
// led, low active
parameter RSTDEF = 1'b1;  // high active
wire reset;  // high active
wire sbtn0;
wire srxd;
reg [8:0] enable;
wire [1:0] led;
wire en0;
wire en1;
wire [9:0] address;
wire [17:0] instruction;
wire [7:0] port_id;
wire write_strobe;  // high active
wire [7:0] out_port;
wire read_strobe;  // high active
reg [7:0] in_port;
wire interrupt;  // high active
wire interrupt_ack;  // high active
  // -----------------------------------------------------------------------------
  assign evn1 = interrupt;
  assign evn2 = instruction[17:14] == 4'b1110 ? 1'b1 : 1'b0;
  // Resetgenarator und Synchronisation des Resetsignals mit dem System
  FDSx2 sync_rst(
      .D(1'b0),
    .Q(reset),
    .S(rst),
    .C(clk));
  // -----------------------------------------------------------------------------
  // Synchronisation des Eingangssignals RXD mit dem System
  FDSx2 sync_rxd(
      .D(rxd),
    .Q(srxd),
    .S(reset),
    .C(clk));
  // -----------------------------------------------------------------------------
  // Synchronisation des Eingangssignals BTN0 mit dem System
  FDSx2 sync_btn0(
      .D(btn0),
    .Q(sbtn0),
    .S(reset),
    .C(clk));
  // -----------------------------------------------------------------------------
  assign en1 = enable[1] & write_strobe;
  // Flipflop fuer das serielle Datenausgangssignal TXD
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  txd_ff(
      .D(out_port[0]),
    .Q(txd),
    .CE(en1),
    .S(reset),
    .C(clk));
  assign en0 = enable[0] & write_strobe;
  // Flipflop fuer das Steuerungssignals der LED0
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  led0_ff(
      .D(out_port[0]),
    .Q(led[0]),
    .CE(en0),
    .S(reset),
    .C(clk));
  // Flipflop fuer das Steuerungssignals der LED1
  FDSE  //synthesis translate_off
   #(
      .INIT(1'b1))
  led1_ff(
      .D(out_port[1]),
    .Q(led[1]),
    .CE(en0),
    .S(reset),
    .C(clk));
  assign led0 = led[0];
  assign led1 = led[1];
  // -----------------------------------------------------------------------------
  // Timer
  timer #(
      .RSTDEF(RSTDEF))
  t1(
      .rst(reset),
    .clk(clk),
    .irq(interrupt),
    .iack(interrupt_ack));
  // -----------------------------------------------------------------------------
  // Dekoder
  always @(*) begin
    case(port_id[3:0])
      4'b0000 : enable <= 9'b000000001;
      4'b0001 : enable <= 9'b000000010;
      4'b0010 : enable <= 9'b000000100;
      4'b0011 : enable <= 9'b000001000;
      4'b0100 : enable <= 9'b000010000;
      4'b0101 : enable <= 9'b000100000;
      4'b0110 : enable <= 9'b001000000;
      4'b0111 : enable <= 9'b010000000;
      4'b1000 : enable <= 9'b100000000;
      default : enable <= 9'b000000000;
    endcase
  end
  always @(*) begin
    case(port_id[3:0])
      4'b0000 : in_port <= {5'b00000,sbtn0,led};
      4'b0001 : in_port <= {7'b0000000,srxd};
      default : in_port <= 8'b00000000;
    endcase
  end
  // -----------------------------------------------------------------------------
  kcpsm3 cpu(
      .reset(reset),
    .clk(clk),
    .address(address),
    .instruction(instruction),
    .port_id(port_id),
    .write_strobe(write_strobe),
    .out_port(out_port),
    .read_strobe(read_strobe),
    .in_port(in_port),
    .interrupt(interrupt),
    .interrupt_ack(interrupt_ack));
  // -----------------------------------------------------------------------------
  // programm memory
  programm rom(
      .clk(clk),
    .address(address),
    .instruction(instruction));
endmodule

