module moduler(
input wire clk,
input wire reset,
input wire T,
input wire E2,
input wire E1,
input wire E0,
output wire S
);
// clock et reset
// tick d'entrée
// config d'entrée
// tick de sortie
//-----------------------------------------------------------------------------
//  Partie Opérative
//-----------------------------------------------------------------------------
// registre de stockage des 3 bits en un vecteur
wire [2:0] E;  // la commande courante
parameter [0:0]
  INIT = 0,
  COUNT = 1;
reg CMD;  // registre stockant la valeur du registre à charger
reg [7:0] V_E;  // registre de comptagne V_E => V_E - 1 => ... 0 => V_E => ...
reg [7:0] C;  // boolean vaux 1 si C est à 0, 0 sinon
wire C_IS_ZERO;  //-----------------------------------------------------------------------------
// Partie Contrôle
//-----------------------------------------------------------------------------
parameter [0:0]
  ST_INIT = 0,
  ST_COUNT = 1;
reg state;
  //-----------------------------------------------------------------------------
  //  Partie Opérative
  //-----------------------------------------------------------------------------
  always @(posedge reset, posedge clk, posedge V_E) begin
    if(reset == 1'b1) begin
      C <= V_E;
    end else begin
      if(CMD == INIT) begin
        C <= V_E;
      end
      else if(CMD == COUNT && T == 1'b1) begin
        C <= C - 1;
      end
    end
  end
  assign C_IS_ZERO = C == 0 ? 1'b1 : 1'b0;
  assign E[0] = E0;
  assign E[1] = E1;
  assign E[2] = E2;
  //-----------------------------------------------------------------------------
  // Partie Contrôle
  //-----------------------------------------------------------------------------
  // Inputs:  T
  // Outputs: S, CMD
  //-----------------------------------------------------------------------------
  // fonction de transitition    
  always @(posedge reset, posedge clk) begin
    if(reset == 1'b1) begin
      state <= ST_INIT;
    end else begin
      case(state)
      ST_INIT : begin
        state <= ST_COUNT;
      end
      ST_COUNT : begin
        if(C_IS_ZERO == 1'b1) begin
          state <= ST_INIT;
        end
      end
      endcase
    end
  end
  // fonction de sortie
  always @(*) begin
    case(state)
      ST_INIT : CMD <= INIT;
      ST_COUNT : CMD <= COUNT;
    endcase
  end
  always @(*) begin
    case(E)
      3'b000 : V_E <= 2;
      3'b001 : V_E <= 5;
      3'b010 : V_E <= 7;
      3'b011 : V_E <= 10;
      3'b100 : V_E <= 12;
      3'b101 : V_E <= 15;
      3'b110 : V_E <= 17;
      3'b111 : V_E <= 20;
    endcase
  end
  // on génère un tick si on a atteint 0 dans le compteur
  assign S = C_IS_ZERO;
endmodule

