module uart_tx(
input wire clk,
input wire reset,
input wire [7:0] din,
input wire wr,
output reg busy,
output reg txd
);
parameter [31:0] fullbit;
//
//
//---------------------------------------------------------------------------
// Implemenattion -----------------------------------------------------------
parameter halfbit = fullbit / 2;  // Signals
reg [31:0] bitcount;
reg [31:0] count;
reg [7:0] shiftreg;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      count <= 0;
      bitcount <= 0;
      busy <= 1'b0;
      txd <= 1'b1;
    end else begin
      if(count != 0) begin
        count <= count - 1;
      end
      else begin
        if(bitcount == 0) begin
          busy <= 1'b0;
          if(wr == 1'b1) begin
            // START BIT
            shiftreg <= din;
            busy <= 1'b1;
            txd <= 1'b0;
            bitcount <= bitcount + 1;
            count <= fullbit;
          end
        end
        else if(bitcount == 9) begin
          // STOP BIT
          txd <= 1'b1;
          bitcount <= 0;
          count <= fullbit;
        end
        else begin
          // DATA BIT
          shiftreg[6:0] <= shiftreg[7:1];
          txd <= shiftreg[0];
          bitcount <= bitcount + 1;
          count <= fullbit;
        end
      end
    end
  end
endmodule

