module ALU(
input wire [31:0] ope1,
input wire [31:0] ope2,
input wire [5:0] aluop,
input wire carry,
output reg [31:0] alurs
);
  always @(ope1, ope2, aluop, carry) begin
    case(aluop)
        // ADD
    6'b100000 : begin
      alurs <= ope1 + ope2;
      // ADDcc
    end
    6'b100001 : begin
      alurs <= ope1 + ope2;
      // ADDX
    end
    6'b100010 : begin
      alurs <= ope1 + ope2 + carry;
      //ADDXcc
    end
    6'b100011 : begin
      alurs <= ope1 + ope2 + carry;
      // SUB
    end
    6'b100100 : begin
      alurs <= ope1 - ope2;
      // SUBcc
    end
    6'b100101 : begin
      alurs <= ope1 - ope2;
      // SUBX
    end
    6'b100110 : begin
      alurs <= ope1 - ope2 - carry;
      //SUBXcc
    end
    6'b100111 : begin
      alurs <= ope1 - ope2 - carry;
      // AND
    end
    6'b101000 : begin
      alurs <= ope1 & ope2;
      // ANDcc
    end
    6'b101001 : begin
      alurs <= ope1 & ope2;
      // ANDN
    end
    6'b101010 : begin
      alurs <=  ~(ope1 & ope2);
      // ANDNcc
    end
    6'b101011 : begin
      alurs <=  ~(ope1 & ope2);
      // OR
    end
    6'b101100 : begin
      alurs <= ope1 | ope2;
      // ORcc
    end
    6'b101101 : begin
      alurs <= ope1 | ope2;
      // ORN
    end
    6'b101110 : begin
      alurs <=  ~(ope1 | ope2);
      // ORNcc
    end
    6'b101111 : begin
      alurs <=  ~(ope1 | ope2);
      // XOR
    end
    6'b110000 : begin
      alurs <= ope1 ^ ope2;
      // XORcc
    end
    6'b110001 : begin
      alurs <= ope1 ^ ope2;
      // XNOR
    end
    6'b110010 : begin
      alurs <=  ~(ope1 ^ ope2);
      // XNORcc
    end
    6'b110011 : begin
      alurs <=  ~(ope1 ^ ope2);
      //SAVE 57
    end
    6'b111001 : begin
      alurs <= ope1 + ope2;
      //RESTORE 58
    end
    6'b111010 : begin
      alurs <= ope1 + ope2;
    end
    default : begin
      alurs <= {32{1'b0}};
    end
    endcase
  end
endmodule

module whole_design(
input wire rst,
input wire clk,
input wire [5:0] gpio,
output wire lcd_en,
output wire lcd_rw,
output wire lcd_rs,
output wire lcd_bl,
inout wire [3:0] lcd_data
);
parameter RSTDEF=1'b0;
// LCD enable
// LCD rw
// LCD rs
// LCD backlight
// LCD data
// import lcd component
// states for communication over GPIO
parameter [1:0]
  SIDLE = 0,
  SCHAR1 = 1,
  SCHAR2 = 2,
  SPOS = 3;
reg [1:0] state = SIDLE;  // character that will be written on the LCD
reg [7:0] char = 1'b0;  // position where char will be written
reg [4:0] pos = 1'b0;
reg reinit = 1'b0;
reg [7:0] lcd_char = 1'b0;
reg [4:0] lcd_pos = 1'b0;
reg lcd_flush = 1'b0;
wire lcd_rdy = 1'b0;
wire lcd_rst = 1'b1;  // gpio clock that keeps track of curr and prev signal
// used to detect rising edges
reg [1:0] gpio_clk = 1'b0;  // payload of gpios whenever we receive rising edge
wire [4:0] gpio_cmd = 1'b0;
  // curr gpio clk is msb of gpio
  assign gpio_clk[0] = gpio[5];
  // remaining bits hold payload
  assign gpio_cmd = gpio[4:0];
  assign lcd_rst = reinit == 1'b1 ? RSTDEF : rst;
  lcd #(
      .RSTDEF(RSTDEF))
  mylcd(
      .rst(lcd_rst),
    .clk(clk),
    .din(lcd_char),
    .posx(lcd_pos[3:0]),
    .posy(lcd_pos[4]),
    .flush(lcd_flush),
    .rdy(lcd_rdy),
    .en(lcd_en),
    .rw(lcd_rw),
    .rs(lcd_rs),
    .bl(lcd_bl),
    .data(lcd_data));
  always @(posedge rst, posedge clk) begin
    if(rst == RSTDEF) begin
      state <= SIDLE;
      char <= {8{1'b0}};
      pos <= {5{1'b0}};
      reinit <= 1'b0;
      lcd_char <= {8{1'b0}};
      lcd_pos <= {5{1'b0}};
      lcd_flush <= 1'b0;
      gpio_clk[1] <= 1'b0;
    end else begin
      // always keep track of prev gpio_clk
      // so we can detect rising and falling edges
      gpio_clk[1] <= gpio_clk[0];
      // keep reinit active for only one cycle
      reinit <= 1'b0;
      // flush whenever possible
      lcd_flush <= 1'b0;
      if(lcd_rdy == 1'b1 && lcd_flush == 1'b0 && state == SIDLE) begin
        // data has to be stored temporarily, so it cannot
        // be changed while LCD is writing
        lcd_pos <= pos;
        lcd_char <= char;
        lcd_flush <= 1'b1;
      end
      // only process communication state machine if
      // gpio_clk shows rising edge
      if(gpio_clk == 2'b01) begin
        case(state)
        SIDLE : begin
          // possible commands:
          //   "00001": reset LCD (reinit)
          //   "00010": write new char to LCD
          //   "00011": change position of character
          if(gpio_cmd == 5'b00001) begin
            reinit <= 1'b1;
          end
          else if(gpio_cmd == 5'b00010) begin
            state <= SCHAR1;
          end
          else if(gpio_cmd == 5'b00011) begin
            state <= SPOS;
          end
        end
        SCHAR1 : begin
          // receive first half of character
          // msb of gpio_cmd is unused here
          char[7:4] <= gpio_cmd[3:0];
          state <= SCHAR2;
        end
        SCHAR2 : begin
          // receive second half of character
          // msb of gpio_cmd is unused here
          char[3:0] <= gpio_cmd[3:0];
          state <= SIDLE;
        end
        SPOS : begin
          // gpio_cmd contains position update
          // msb is posy, remaining are posx
          pos <= gpio_cmd;
          state <= SIDLE;
        end
        endcase
      end
    end
  end
endmodule

`timescale 1 ns / 1 ns
module EXTERNAL_MEMORY_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [13:0] ADDRA = 1'b0;
reg [13:0] ADDRA_R = 1'b0;
wire [15:0] DINA = 1'b0;
reg [15:0] DINA_R = 1'b0;
wire [15:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(16),
    .READ_WIDTH(16))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {16{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {14{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  EXTERNAL_MEMORY_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

