module hc_sr04(
input wire CLOCK_CORE,
input wire INIT_KEY,
input wire ECHO,
output reg TRIGGER,
output wire [31:0] DIST
);
parameter [31:0] freqIn=50000000;
parameter [31:0] HC_freqOut=17000;
parameter [31:0] count_out=1000000;
parameter COUNT_MAX = 500;  //10us
parameter MAX_DIST = 200;
parameter DISP_TRIGGER = 0;
parameter WAIT_ECHO = 1;
parameter STANDBY = 2;  //CONSTANT DELAY 			: integer := 3;
//CONSTANT RESET			: integer := 4;
reg [31:0] dist_mm;
reg hc_clock;
wire count_clock;
  always @(posedge CLOCK_CORE) begin : P2
    reg [31:0] counter = 0;
    if(counter < COUNT_MAX) begin
      counter = counter + 1;
    end
    else begin
      counter = 0;
      hc_clock <=  ~hc_clock;
    end
  end
  assign count_clock = hc_clock;
  //		HC_SR04_CLOCK:WORK.clockDivider
  //		
  //			PORT MAP(
  //			CLOCK_CORE,
  //			freqIn,
  //			count_out,
  //			count_clock
  //			);
  always @(count_clock, echo) begin : P1
    reg [31:0] STATE = 0;
    reg [31:0] NEXT_STATE = 0;
    reg [31:0] counter = 0;
    if((INIT_KEY == 1'b1)) begin
      case(STATE)
      DISP_TRIGGER : begin
        TRIGGER <= 1'b1;
        counter = counter + 1;
        if((counter > 10)) begin
          counter = 0;
          TRIGGER <= 1'b0;
          NEXT_STATE = WAIT_ECHO;
        end
      end
      WAIT_ECHO : begin
        if((ECHO == 1'b1)) begin
          counter = counter + 1;
        end
        if((ECHO == 1'b0 && counter > 0)) begin
          dist_mm <= MAX_DIST - (counter * 10) / 58;
          NEXT_STATE = STANDBY;
        end
      end
      STANDBY : begin
        STATE = NEXT_STATE;
      end
      endcase
    end
    if((INIT_KEY == 1'b0)) begin
      STATE = DISP_TRIGGER;
      counter = 0;
      TRIGGER <= 1'b0;
    end
  end
endmodule

module round_f(
