    theta_2_s,
    theta_3_s);
  reg_128 REG_STAGE_0(
      clk,
    rst,
    theta_0_s,
    theta_1_s,
    theta_2_s,
    theta_3_s,
    stage_0_out_0_s,
    stage_0_out_1_s,
    stage_0_out_2_s,
    stage_0_out_3_s);
  pi_1 PI_1_0(
      stage_0_out_1_s,
    stage_0_out_2_s,
    stage_0_out_3_s,
    pi_1_1_s,
    pi_1_2_s,
