  assign a_0_aux_s = enc == 1'b1 ? stage_0_out_0_s ^ rc_delay_s : stage_0_out_0_s;
  reg_128 REG_STAGE_1(
      clk,
    rst,
    a_0_aux_s,
    pi_1_1_s,
    pi_1_2_s,
    pi_1_3_s,
    stage_1_out_0_s,
    stage_1_out_1_s,
    stage_1_out_2_s,
    stage_1_out_3_s);
  gamma GAMMA_0(
      stage_1_out_0_s,
    stage_1_out_1_s,
    stage_1_out_2_s,
    stage_1_out_3_s,
    gamma_0_s,
    gamma_1_s,
    gamma_2_s,
    gamma_3_s);
  pi_2 PI_2_0(
      gamma_1_s,
    gamma_2_s,
    gamma_3_s,
    pi_2_1_s,
    pi_2_2_s,
    pi_2_3_s);
  assign a_0_out = gamma_0_s;
  assign a_1_out = pi_2_1_s;
  assign a_2_out = pi_2_2_s;
  assign a_3_out = pi_2_3_s;
endmodule

