module sub_586(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module RAM(
input wire clk,
input wire cs,
input wire read,
input wire write,
input wire [9:0] address,
input wire [31:0] wrdata,
output reg [31:0] rddata
);
reg [31:0] mem[0:1023];
reg [9:0] reg_address;
reg reg_read;
  // address register
  always @(posedge clk) begin
    reg_read <= cs & read;
    // The next statement is optional and ONLY compatible
    // with Quartus II 8.0 or higher:
    // Since we don't read during the next cycle, we can
    // save power consumption by keeping the address constant.
    //if(read='1' and cs='1')then
    reg_address <= address;
    //end if;
  end
  // read in memory
  always @(mem, reg_read, reg_address) begin
    rddata <= {32{1'bZ}};
    if((reg_read == 1'b1)) begin
      rddata <= mem[reg_address];
    end
  end
  // write in memory
  always @(posedge clk) begin
    if((cs == 1'b1 && write == 1'b1)) begin
      mem[address] <= wrdata;
    end
  end
endmodule

module PMem(
