module SpaceWireCODECIPTimeCodeControl(
input wire clock,
input wire reset,
input wire receiveClock,
input wire gotTimeCode,
input wire [7:0] receiveTimeCodeOut,
output wire [5:0] timeOut,
output wire [1:0] controlFlagsOut,
output wire tickOut
);
reg [7:0] iReceiveTimeCodeOutRegister;
reg [1:0] iControlFlags;
reg [5:0] iReceiveTimeCode;
reg [5:0] iReceiveTimeCodePlus1;
reg iTickOutSignal;
wire gotTimeCodeSynchronized;
  assign timeOut = iReceiveTimeCode;
  assign controlFlagsOut = iControlFlags;
  assign tickOut = iTickOutSignal;
  //--------------------------------------------------------------------
  // ECSS-E-ST-50-12C 8.12 System time distribution (normative)
  // ECSS-E-ST-50-12C 7.3 Control characters and control codes
  // The new time should be one more than the time-counter's previous
  // time-value.
  //--------------------------------------------------------------------
  always @(posedge clock, posedge reset) begin
    if((reset == 1'b1)) begin
      iReceiveTimeCode <= {6{1'b0}};
      iReceiveTimeCodePlus1 <= 6'b000001;
      iTickOutSignal <= 1'b0;
      iControlFlags <= 2'b00;
      iReceiveTimeCodeOutRegister <= {8{1'b0}};
    end else begin
      if((gotTimeCodeSynchronized == 1'b1)) begin
        iControlFlags <= iReceiveTimeCodeOutRegister[7:6];
        iReceiveTimeCode <= iReceiveTimeCodeOutRegister[5:0];
        iReceiveTimeCodePlus1 <= iReceiveTimeCodeOutRegister[5:0] + 1;
        if((iReceiveTimeCodePlus1 == iReceiveTimeCodeOutRegister[5:0])) begin
          iTickOutSignal <= 1'b1;
        end
      end
      else begin
        iTickOutSignal <= 1'b0;
      end
      iReceiveTimeCodeOutRegister <= receiveTimeCodeOut;
    end
  end
  SpaceWireCODECIPSynchronizeOnePulse timeCodePulse(
      .clock(clock),
    .asynchronousClock(receiveClock),
    .reset(reset),
    .asynchronousIn(gotTimeCode),
    .synchronizedOut(gotTimeCodeSynchronized));
endmodule

module bcd_5_digit_adder(
input wire [19:0] Entrada1,
input wire [19:0] Entrada2,
output wire [19:0] sum,
output wire [3:0] carry
);
// Entrada 1
// Entrada 2
// Resultado
// Importe do componente utilizado para fazer o somador.
// bcd_adder é um somador bcd de um dígito (4 bits).
// Este já realiza a correção caso a soma produza um carry de saída
// ou se a soma for um número maior que 9.
// Foram declarados alguns signals para auxiliar o cascateamento dos somadores.
wire [3:0] carry_1; wire [3:0] carry_2; wire [3:0] carry_3; wire [3:0] carry_4; wire [3:0] carry_5;
wire [19:0] Entrada1_s; wire [19:0] Entrada2_s; wire [19:0] sum_s;
  // Inicializar os signals
  assign Entrada1_s = Entrada1;
  assign Entrada2_s = Entrada2;
  assign sum = sum_s;
  // Port map de 5 blocos somadores BCD de um digito. Estes foram conectados em cascata através
  // dos signals de carry.
  bcd_adder adder1(
      Entrada1_s[3:0],
    Entrada2_s[3:0],
    4'b0000,
    sum_s[3:0],
    carry_1);
  bcd_adder adder2(
      Entrada1_s[7:4],
    Entrada2_s[7:4],
    carry_1,
    sum_s[7:4],
    carry_2);
  bcd_adder adder3(
      Entrada1_s[11:8],
    Entrada2_s[11:8],
    carry_2,
    sum_s[11:8],
    carry_3);
  bcd_adder adder4(
      Entrada1_s[15:12],
    Entrada2_s[15:12],
    carry_3,
    sum_s[15:12],
    carry_4);
  bcd_adder adder5(
      Entrada1_s[19:16],
    Entrada2_s[19:16],
    carry_4,
    sum_s[19:16],
    carry_5);
  assign carry = carry_5;
endmodule

