module video(
input wire CLK,
input wire RESET,
output reg [13:0] VRAM_A,
input wire [7:0] VRAM_D,
input wire [6:0] COLORS,
output reg [3:0] R,
output reg [3:0] G,
output reg [3:0] B,
output reg HSYNC,
output reg VSYNC,
input wire HI_RES,
input wire BLANK_SCR
);
// Pixel clock 65MHz
// Reset (active low)
// Red
// Green
// Blue
// Hor. sync
// Ver. sync
// PK-02 512 x 256 mode
// PK-02 Blank Screen	
// VGA timing constants (XGA - 1024x768@60) (512x768@60)
// HOR
parameter HSIZE = 512;  // Visible area
parameter HFP = 12;  // Front porch
parameter HS = 68;  // HSync pulse
parameter HB = 80;  // Back porch
parameter HOFFSET = 0;  // HSync offset
// VER
parameter VSIZE = 768;  // Visible area
parameter VFP = 3;  // Front porch
parameter VS = 6;  // VSync pulse
parameter VB = 29;  // Back porch     
parameter VOFFSET = 0;  // VSync offset
//----------------------------------------------------------
reg [9:0] H_COUNTER;  // Horizontal Counter    
reg [9:0] V_COUNTER;  // Vertical Counter
reg [1:0] THREE_ROW_CNT;  // 3 Row Counter
reg [7:0] ROW_COUNTER;  // Korvet Row Counter  
reg PAPER;  // Paper zone
reg PAPER_L;  // Paper zone
wire COLOR_R;
wire COLOR_G;
wire COLOR_B;
reg [3:0] PIX0;
reg [3:0] PIX1;
reg [7:0] PIX;
wire [1:0] COLOR;
  clr_mux u_COLOR_MUX(
      .color(COLOR),
    .portb(COLORS),
    .out_r(COLOR_R),
    .out_g(COLOR_G),
    .out_b(COLOR_B));
  assign COLOR = BLANK_SCR == 1'b1 ? 2'b00 : HI_RES == 1'b0 ? {PIX1[3 - (H_COUNTER[2:1])],PIX0[3 - (H_COUNTER[2:1])]} : {PIX[7 - (H_COUNTER[2:0])],PIX[7 - (H_COUNTER[2:0])]};
  always @(posedge CLK) begin : P2
  // H/V Counters
    if(RESET == 1'b0) begin
      H_COUNTER <= {10{1'b0}};
      V_COUNTER <= {10{1'b0}};
    end
    else begin
      H_COUNTER <= H_COUNTER + 1;
      if(H_COUNTER == (HSIZE + HFP + HS + HB - 1)) begin
        H_COUNTER <= {10{1'b0}};
        V_COUNTER <= V_COUNTER + 1;
        if(V_COUNTER == (VSIZE + VFP + VS + VB - 1)) begin
          V_COUNTER <= {10{1'b0}};
        end
      end
    end
  end
  always @(posedge CLK) begin : P1
  // H/V Counters
    if(RESET == 1'b0) begin
      THREE_ROW_CNT <= {2{1'b0}};
      ROW_COUNTER <= {8{1'b0}};
    end
    else begin
      if(H_COUNTER == 544) begin
        if(V_COUNTER < 768) begin
          THREE_ROW_CNT <= THREE_ROW_CNT + 1;
          if(THREE_ROW_CNT == 2) begin
            THREE_ROW_CNT <= {2{1'b0}};
            ROW_COUNTER <= ROW_COUNTER + 1;
          end
        end
        else begin
          ROW_COUNTER <= {8{1'b0}};
          THREE_ROW_CNT <= {2{1'b0}};
        end
      end
    end
  end
  always @(posedge CLK) begin
    HSYNC <= 1'b1;
    VSYNC <= 1'b1;
    PAPER <= 1'b0;
    if(H_COUNTER >= (HSIZE + HOFFSET + HFP) && H_COUNTER < (HSIZE + HOFFSET + HFP + HS)) begin
      HSYNC <= 1'b0;
    end
    if(V_COUNTER >= (VSIZE + VOFFSET + VFP) && V_COUNTER < (VSIZE + VOFFSET + VFP + VS)) begin
      VSYNC <= 1'b0;
    end
    if(H_COUNTER < HSIZE && V_COUNTER < VSIZE) begin
      PAPER <= 1'b1;
    end
  end
  always @(posedge CLK) begin
    case(H_COUNTER[2:0])
    3'b001 : begin
      VRAM_A <= {ROW_COUNTER,H_COUNTER[8:3]};
    end
    3'b111 : begin
      PIX0 <= VRAM_D[3:0];
      PIX1 <= VRAM_D[7:4];
      PIX <= VRAM_D[7:0];
      PAPER_L <= PAPER;
    end
    default : begin
    end
    endcase
  end
  always @(posedge CLK) begin
    if(PAPER_L == 1'b1) begin
      if(THREE_ROW_CNT == 2'b01) begin
        R <= {COLOR_R,COLOR_R,COLOR_R,COLOR_R};
        G <= {COLOR_G,COLOR_G,COLOR_G,COLOR_G};
        B <= {COLOR_B,COLOR_B,COLOR_B,COLOR_B};
      end
      else begin
        R <= {COLOR_R,3'b000};
        G <= {COLOR_G,3'b000};
        B <= {COLOR_B,3'b000};
      end
    end
    else begin
      R <= {4{1'b0}};
      G <= {4{1'b0}};
      B <= {4{1'b0}};
    end
  end
endmodule

module RefreshDisplay(
