);
//Declaraciones de constantes
parameter Fosc = 100000000;  //Frecuencia del oscilador de tabletas NEXYS 3
parameter Fdiv = 800;  //Frecuencia deseada del divisor
parameter CtaMax = Fosc / Fdiv;  //Cuenta maxima a la que hay que llegar
//Declaracion de signals
reg [31:0] Cont;
  //Proceso que Divide la Frecuencia de entrada para obtener una Frecuencia de 1 Hz
  always @(posedge Rst, posedge Clk) begin
    if(Rst == 1'b1) begin
      Cont <= 0;
    end else begin
      if(Cont == CtaMax) begin
        Cont <= 0;
