module BFB_Reaction(
input wire clk,
input wire reset,
input wire enable,
input wire sync,
input wire rx_change_eI,
output wire tx_change_eO,
input wire rx_I,
output wire tx_O,
output wire done
);
//for clock and reset signal
//input events
//output events
//input variables
//type was BOOL
//output variables
//type was BOOL
//for done signal
// Build an enumerated type for the state machine
parameter [0:0]
  STATE_Update = 0;
  // Register to hold the current state
reg state = STATE_Update;  // signals to store variable sampled on enable 
reg rx = 1'b0;  //register for input
// signals to rename outputs 
reg tx = 1'b0;  //signals to rename output events
reg tx_change_eO_ecc_out = 1'b0;  //used when event driven from ECC (normal FB behaviour)
reg tx_change_eO_alg_out = 1'b0;  //used when event driven from algorithm (normal SIFB behaviour)
// signals for enabling algorithms	
reg REACTION_TO_CHANGE_alg_en = 1'b0;
reg REACTION_TO_CHANGE_alg_done = 1'b1;  // signal for algorithm completion
reg AlgorithmsStart = 1'b0;
wire AlgorithmsDone;
  // Registers for data variables (only updated on relevant events)
  always @(posedge clk) begin
    if(sync == 1'b1) begin
      if(rx_change_eI == 1'b1) begin
        rx <= rx_I;
      end
    end
  end
  //output var renaming, no output registers as inputs are stored where they are processed
  assign tx_O = tx;
  // Logic to advance to the next state
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      state <= STATE_Update;
      AlgorithmsStart <= 1'b1;
    end else begin
      if(AlgorithmsStart == 1'b1) begin
        //algorithms should be triggered only once via this pulse signal
        AlgorithmsStart <= 1'b0;
      end
      else if(enable == 1'b1) begin
        //default values
        state <= state;
        AlgorithmsStart <= 1'b0;
        //next state logic
        case(state)
        STATE_Update : begin
          if(rx_change == 1'b1) begin
            state <= STATE_Update;
            AlgorithmsStart <= 1'b1;
          end
        end
        endcase
      end
    end
  end
  // Event outputs and internal algorithm triggers depend solely on the current state
  always @(state) begin
    //default values
    //events
    tx_change_eO_ecc_out <= 1'b0;
    //algorithms
    REACTION_TO_CHANGE_alg_en <= 1'b0;
    case(state)
    STATE_Update : begin
      REACTION_TO_CHANGE_alg_en <= 1'b1;
      tx_change_eO_ecc_out <= 1'b1;
    end
    endcase
  end
  // Algorithms process
  always @(posedge clk) begin
    if(AlgorithmsStart == 1'b1) begin
      if(REACTION_TO_CHANGE_alg_en == 1'b1) begin
        // Algorithm REACTION_TO_CHANGE
        REACTION_TO_CHANGE_alg_done <= 1'b0;
        //logic for resetting algorithm-driven output events
        tx_change_eO_alg_out <= 1'b0;
      end
    end
    if(REACTION_TO_CHANGE_alg_done == 1'b0) begin
      // Algorithm REACTION_TO_CHANGE
      //begin algorithm raw text
      tx <= rx;
      REACTION_TO_CHANGE_alg_done <= 1'b1;
      //end algorithm raw text
    end
  end
  //Done signal
  assign AlgorithmsDone = ( ~AlgorithmsStart) & ( ~enable) & REACTION_TO_CHANGE_alg_done;
  assign Done = AlgorithmsDone;
  //logic for renamed output events
  assign tx_change_eO = tx_change_eO_ecc_out | tx_change_eO_alg_out;
endmodule

