module vga(
input wire clk,
input wire reset,
output wire hsync,
output wire vsync,
output wire video_on,
output wire p_tick,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y
);
// VGA 640x480 sync parameters
parameter HD = 640;  // horizontal display area
parameter HF = 16;  // h. front porch
parameter HB = 48;  // h. back porch
parameter HR = 96;  // h. retrace
parameter VD = 480;  // vertical display area
parameter VF = 11;  // v. front porch
parameter VB = 31;  // v. back porch
parameter VR = 2;  // v. retrace
// mod-2 counter
reg mod2; wire mod2_next;  // sync counters
reg [9:0] v_count; reg [9:0] v_count_next;
reg [9:0] h_count; reg [9:0] h_count_next;  // output buffer
reg v_sync; reg h_sync;
wire v_sync_next; wire h_sync_next;  // status signal
wire h_end; wire v_end; wire pixel_tick;
  always @(negedge clk, negedge reset) begin
    if(reset == 1'b1) begin
      mod2 <= 1'b0;
      v_count <= {10{1'b0}};
      h_count <= {10{1'b0}};
      v_sync <= 1'b0;
      h_sync <= 1'b0;
    end else begin
      mod2 <= mod2_next;
      v_count <= v_count_next;
      h_count <= h_count_next;
      v_sync <= v_sync_next;
      h_sync <= h_sync_next;
    end
  end
  // mod-2 circuit to generate 25 MHz enable tick
  assign mod2_next =  ~mod2;
  // 25 MHz pixel tick
  assign pixel_tick = mod2 == 1'b1 ? 1'b1 : 1'b0;
  // end of counters (799 and 524 pixels)
  assign h_end = h_count == (HD + HF + HB + HR - 1) ? 1'b1 : 1'b0;
  assign v_end = v_count == (VD + VF + VB + VR - 1) ? 1'b1 : 1'b0;
  // mod-800 horizontal sync counter
  always @(h_count, h_end, pixel_tick) begin
    if(pixel_tick == 1'b1) begin
      if(h_end == 1'b1) begin
        h_count_next <= {10{1'b0}};
      end
      else begin
        h_count_next <= h_count + 1;
      end
    end
    else begin
      h_count_next <= h_count;
    end
  end
  // mod-525 vertical sync counter
  always @(v_count, h_end, v_end, pixel_tick) begin
    if(pixel_tick == 1'b1 && h_end == 1'b1) begin
      if(v_end == 1'b1) begin
        v_count_next <= {10{1'b0}};
      end
      else begin
        v_count_next <= v_count + 1;
      end
    end
    else begin
      v_count_next <= v_count;
    end
  end
  // horizontal and vertical sync, buffered to avoid glitch
  assign h_sync_next = (h_count >= (HD + HF)) && (h_count <= (HD + HF + HR - 1)) ? 1'b1 : 1'b0;
  assign v_sync_next = (v_count >= (VD + VF)) && (v_count <= (VD + VF + VR - 1)) ? 1'b1 : 1'b0;
  // video on/off
  assign video_on = (h_count < HD) && (v_count < VD) ? 1'b1 : 1'b0;
  // output signal
  assign hsync = h_sync;
  assign vsync = v_sync;
  assign pixel_x = h_count;
  assign pixel_y = v_count;
  assign p_tick = pixel_tick;
endmodule

