module alu(
input wire [15:0] operand0,
input wire [15:0] operand1,
input wire [3:0] operation,
output wire [15:0] alu_out,
output wire c_flag,
output wire z_flag,
output wire n_flag,
output wire lt_flag
);
//carry flag
//zero flag
//negative flag
//overflow flag
wire [15:0] sum_sig; wire [15:0] sub_sig; wire [15:0] slt_sig; wire [15:0] sneg_sig;
wire [16:0] A_17bits_sig; wire [16:0] B_17bits_sig; wire [16:0] sum_17bits_sig;
wire [15:0] alu_out_sig;
  assign A_17bits_sig = operand0[15] == 1'b0 ? {1'b0,operand0} : ;
  assign B_17bits_sig = operand1[15] == 1'b0 ? {1'b0,operand1} : ;
  assign sum_17bits_sig = A_17bits_sig + B_17bits_sig;
  assign c_flag = operation == 4'b0001 ? sum_17bits_sig[16] : operation == 4'b0010 && operand1 <= operand0 ? 1'b1 : 1'b0;
  assign z_flag = alu_out_sig == 16'b0000000000000000 ? 1'b1 : 1'b0;
  assign n_flag = alu_out_sig[15] == 1'b1 ? 1'b1 : 1'b0;
  assign lt_flag = slt_sig == 16'b0000000000000001 ? 1'b1 : 1'b0;
  assign alu_out = alu_out_sig;
  mux4x1 alu_mux(
      .in0(sum_sig),
    .in1(sub_sig),
    .in2(slt_sig),
    .in3(sneg_sig),
    .sel(operation),
    .out0(alu_out_sig));
  arithmetic_circuit alu_arithmetic_circuit(
      .a(operand0),
    .b(operand1),
    .sum(sum_sig),
    .sub(sub_sig),
    .slt(slt_sig),
    .sneg(sneg_sig));
endmodule

