module MI32_ASYNC_FSMS(
input wire RESET,
input wire CLK,
input wire REQ,
input wire DRDY,
input wire ARDY,
output wire ACK,
output wire EN
);
// ----------------------------------------------------------------------------
//                               Architecture
// ----------------------------------------------------------------------------
parameter [1:0]
  wait_for_req = 0,
  wait_for_drdy = 1,
  wait_for_nreq = 2;
reg [1:0] fsm;
reg [1:0] fsm_next;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      fsm <= wait_for_req;
    end else begin
      fsm <= fsm_next;
    end
  end
  always @(fsm, REQ, DRDY, ARDY) begin
    fsm_next <= fsm;
    case(fsm)
    wait_for_req : begin
      if(REQ == 1'b1 && ARDY == 1'b1) begin
        if(DRDY == 1'b1) begin
          fsm_next <= wait_for_nreq;
        end
        else begin
          fsm_next <= wait_for_drdy;
        end
      end
    end
    wait_for_drdy : begin
      if(DRDY == 1'b1) begin
        fsm_next <= wait_for_nreq;
      end
    end
    wait_for_nreq : begin
      if(REQ == 1'b0) begin
        fsm_next <= wait_for_req;
      end
    end
    endcase
  end
  assign ACK = fsm == wait_for_nreq ? 1'b1 : 1'b0;
  assign EN = fsm == wait_for_req && REQ == 1'b1 ? 1'b1 : 1'b0;
endmodule

