module audio_scancode_to_divisor(
input wire [7:0] scancode,
output reg [31:0] clock_divisor
);
  always @(scancode) begin
    case(scancode)
    8'b00100011 : begin
      clock_divisor <= 3367000;
      // 297 Hz (d')
    end
    8'b00100100 : begin
      clock_divisor <= 30303000;
      // 330 Hz (e')
    end
    8'b00101011 : begin
      clock_divisor <= 284091000;
      // 352 Hz (f')
    end
    8'b00110100 : begin
      clock_divisor <= 25252;
      // 396 Hz (g')
    end
    8'b00011100 : begin
      clock_divisor <= 22727;
      // 440 Hz (a')
    end
    8'b00110011 : begin
      clock_divisor <= 2020;
      // 495 Hz (h')
    end
    default : begin
      clock_divisor <= 378788;
      // 264 Hz (c');
    end
    endcase
  end
endmodule

module UART_RX(
input wire CLK,
input wire RESET,
input wire RX,
input wire S_TICK,
output reg RX_DONE_TICK,
output wire [7:0] DOUT
);
parameter [31:0] DBIT=8;
parameter [31:0] SB_TICK=16;
// # Stop BITS Tick (1 -> 16, 1.5 -> 24, 2 -> 32)
//-----------------------------------------------------------------------
parameter [1:0]
  idle = 0,
  start = 1,
  data = 2,
  stop = 3;
reg [1:0] state_reg; reg [1:0] state_next;
reg [3:0] s_reg; reg [3:0] s_next;
reg [2:0] n_reg; reg [2:0] n_next;
reg [7:0] b_reg; reg [7:0] b_next;
  // FSMD state & data registers
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      state_reg <= idle;
      s_reg <= {4{1'b0}};
      n_reg <= {3{1'b0}};
      b_reg <= {8{1'b0}};
    end else begin
      state_reg <= state_next;
      s_reg <= s_next;
      n_reg <= n_next;
      b_reg <= b_next;
    end
  end
  // Next-state logic & data path functional units/routing
  always @(state_reg, s_reg, n_reg, b_reg, S_TICK, RX) begin
    state_next <= state_reg;
    s_next <= s_reg;
    n_next <= n_reg;
    b_next <= b_reg;
    RX_DONE_TICK <= 1'b0;
    case(state_reg)
    idle : begin
      if(RX == 1'b0) begin
        state_next <= start;
        s_next <= {4{1'b0}};
      end
    end
    start : begin
      if((S_TICK == 1'b1)) begin
        if(s_reg == 7) begin
          state_next <= data;
          s_next <= {4{1'b0}};
          n_next <= {3{1'b0}};
        end
        else begin
          s_next <= s_reg + 1;
        end
      end
    end
    data : begin
      if((S_TICK == 1'b1)) begin
        if(s_reg == 15) begin
          s_next <= {4{1'b0}};
          b_next <= {RX,b_reg[7:1]};
          if(n_reg == (DBIT - 1)) begin
            state_next <= stop;
          end
          else begin
            n_next <= n_reg + 1;
          end
        end
        else begin
          s_next <= s_reg + 1;
        end
      end
    end
    stop : begin
      if((S_TICK == 1'b1)) begin
        RX_DONE_TICK <= 1'b1;
        if(s_reg == (SB_TICK - 1)) begin
          state_next <= idle;
        end
        else begin
          s_next <= s_reg + 1;
        end
      end
    end
    endcase
  end
  assign DOUT = b_reg;
endmodule

