module cronometro(
input wire clock_50,
input wire [1:0] dificuldade,
input wire reset,
output wire [7:0] restante,
output wire [7:0] atual
);
wire clk_1hz;
reg [7:0] contagem;
reg [7:0] maximo;
  clock_conv converter(
      clock_50,
    /* open */,
    clk_1hz,
    /* open */);
  always @(dificuldade, clock_50) begin
    // define o tempo maximo da contagem levando em conta a dificuldade escolhida
    case(dificuldade)
    2'b00 : begin
      maximo <= 8'b00011110;
    end
    2'b01 : begin
      maximo <= 8'b00010100;
    end
    2'b10 : begin
      maximo <= 8'b00001010;
    end
    2'b11 : begin
      maximo <= 8'b00000101;
    end
    endcase
  end
  always @(posedge clk_1hz, posedge reset) begin
    if((reset == 1'b1)) begin
      // reset assincrono
      contagem <= 8'b00000000;
    end else begin
      // se a o tempo atual for maior que o tempo maximo, reseta o tempo atual, senao, adiciona um ao tempo atual
      if((contagem >= maximo)) begin
        contagem <= 8'b00000000;
      end
      else begin
        contagem <= contagem + 1'b1;
      end
    end
  end
  // para obter o tempo restante, subtraimos o tempo atual do tempo maximo
  assign restante = maximo - contagem;
  assign atual = contagem;
endmodule

