module mcu80_irq(
input wire cpu_inta_i,
output wire cpu_intr_o,
input wire cpu_fetch_i,
input wire data_we_i,
input wire addr_i,
input wire [7:0] data_i,
output wire [7:0] data_o,
input wire [3:0] irq_i,
input wire clk,
input wire reset
);
//##############################################################################
//
//##############################################################################
// irq_pending: 1 when irq[i] is pending service
reg [3:0] irq_pending_reg;  // irq_enable: 1 when irq[i] is enabled 
reg [3:0] irq_enable_reg;  // irq_q: registered irq input used to catch rising edges
reg [3:0] irq_q;  // irq_trigger: asserted to 1 when a rising edge is detected
wire [3:0] irq_trigger;
wire [3:0] irq_clear;
reg [3:0] irq_clear_mask;
wire [7:0] data_rd;
reg [7:0] vector;
wire [2:0] irq_level;
  genvar i;
  generate for (i=0; i <= 3; i = i + 1) begin: edge_detection
      assign irq_trigger[i] = irq_q[i] == 1'b0 && irq_i[i] == 1'b1 && irq_enable_reg[i] == 1'b1 ? 1'b1 : 1'b0;
  end
  endgenerate
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      irq_pending_reg <= {4{1'b0}};
      irq_q <= {4{1'b0}};
    end
    else begin
      irq_pending_reg <= (irq_pending_reg & ( ~irq_clear)) | irq_trigger;
      irq_q <= irq_i;
    end
  end
  always @(*) begin
    case(irq_level)
      3'b111 : irq_clear_mask <= 4'b1000;
      3'b101 : irq_clear_mask <= 4'b0100;
      3'b011 : irq_clear_mask <= 4'b0010;
      default : irq_clear_mask <= 4'b0001;
    endcase
  end
  assign irq_clear = cpu_inta_i == 1'b1 && cpu_fetch_i == 1'b1 ? irq_clear_mask : 4'b0000;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      // All interrupts disabled at reset
      irq_enable_reg <= {4{1'b0}};
    end
    else begin
      if(data_we_i == 1'b1 && addr_i == 1'b0) begin
        irq_enable_reg <= data_i[3:0];
      end
    end
  end
  // Interrupt priority & vector decoding
  assign irq_level = irq_pending_reg[0] == 1'b1 ? 3'b001 : irq_pending_reg[1] == 1'b1 ? 3'b011 : irq_pending_reg[2] == 1'b1 ? 3'b110 : 3'b111;
  // Raise interrupt request when there's any irq pending
  assign cpu_intr_o = irq_pending_reg != 4'b0000 ? 1'b1 : 1'b0;
  // The IRQ vector is hardcoded to a RST instruction, whose opcode is 
  // RST <n> ---> 11nnn111
  always @(posedge clk) begin
    if(cpu_inta_i == 1'b1 && cpu_fetch_i == 1'b1) begin
      vector <= {2'b11,irq_level,3'b111};
    end
  end
  // There's only an internal register, the irq enable register, so we
  // don't need an output register mux.
  assign data_rd = {4'b0000,irq_enable_reg};
  // The mdule will output the register being read, if any, OR the irq vector.
  assign data_o = cpu_inta_i == 1'b1 ? vector : data_rd;
endmodule

