module controller(
input wire g,
input wire e,
input wire l,
input wire clk,
input wire reset,
output reg sel_1,
output reg [1:0] sel_2,
output reg counter_reset,
output reg counter_enable,
output reg load,
input wire counter_done,
input wire free,
output reg done,
output reg rwbar
);
parameter [2:0]
  RESET0 = 0,
  RESET1 = 1,
  WAITING = 2,
  S1 = 3,
  S2 = 4,
  S3 = 5,
  S4 = 6,
  S5 = 7;
reg [2:0] current_state;
reg [2:0] next_state;
  // next
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      current_state <= RESET0;
    end else begin
      current_state <= next_state;
    end
  end
  // next state + outputs :D
  always @(current_state, counter_done, g, e, l, reset, free) begin
    if(current_state == S1) begin
      sel_1 <= 1'b0;
      rwbar <= 1'b1;
      counter_reset <= 1'b1;
      next_state <= S2;
    end
    else if(current_state == S2) begin
      load <= 1'b1;
      counter_reset <= 1'b0;
      sel_1 <= 1'b1;
      next_state <= S3;
    end
    else if(current_state == S3) begin
      load <= 1'b0;
      next_state <= S4;
    end
    else if(current_state == S4) begin
      if(e == 1'b1 && g == 1'b0 && l == 1'b0) begin
        sel_2 <= 2'b10;
        rwbar <= 1'b0;
      end
      else if(e == 1'b0 && g == 1'b1 && l == 1'b0) begin
        rwbar <= 1'b1;
      end
      else if(e == 1'b0 && g == 1'b0 && l == 1'b1) begin
        sel_2 <= 2'b00;
        rwbar <= 1'b0;
      end
      next_state <= S5;
    end
    else if(current_state == S5) begin
      rwbar <= 1'b1;
      if(counter_done == 1'b1) begin
        done <= 1'b1;
        next_state <= WAITING;
      end
      else begin
        counter_enable <= 1'b1;
        next_state <= S3;
      end
    end
    else if(current_state == WAITING) begin
      if(free == 1'b1) begin
        done <= 1'b0;
        next_state <= S1;
      end
      else begin
        done <= 1'b0;
        next_state <= WAITING;
      end
    end
    else if(current_state == RESET0) begin
      counter_reset <= 1'b1;
      next_state <= RESET1;
      sel_1 <= 1'b1;
      sel_2 <= 2'b11;
    end
    else if(current_state == RESET1) begin
      counter_enable <= 1'b1;
      counter_reset <= 1'b0;
      if(counter_done == 1'b1) begin
        rwbar <= 1'b1;
        counter_enable <= 1'b0;
        next_state <= WAITING;
      end
      else begin
        rwbar <= 1'b0;
        next_state <= RESET1;
      end
    end
  end
endmodule

