module fmexg_core(
input wire clock,
input wire spi_clk,
input wire spi_cs,
output wire spi_miso,
output wire adc_clk,
output wire adc_pdwn,
input wire [11:0] adc_data,
output wire interrupt,
input wire fmexg_mic_sync
);
//
reg [2:0] counter_div12;
reg clkdiv12;  //signal fifo_readclk: std_logic;
reg [2:0] spi_bit_ctr;
reg [1:0] spi_byte_ctr;
reg fifo_readclk_en;
reg [11:0] first_sample;
reg [23:0] two_samples;  //signal fifo_bit: unsigned(3 downto 0);
//signal hacky_fix: unsigned(1 downto 0);
//signal spi_data: std_logic;
//signal interrupt_counter: unsigned(7 downto 0); 
wire [11:0] fifo_Data;
wire fifo_WrClock;
wire fifo_RdClock;
wire fifo_WrEn;
wire fifo_RdEn;
wire fifo_Reset;
wire fifo_RPReset;
wire [11:0] fifo_Q;
wire [11:0] fifo_Q_u;
wire fifo_Empty;
wire fifo_Full;
wire fifo_AlmostEmpty;
wire fifo_AlmostFull;
reg [11:0] rampcounter;
  assign adc_pdwn = 1'b0;
  always @(posedge clock) begin
    counter_div12 <= counter_div12 + 1;
    if(counter_div12 == 3'b101) begin
      counter_div12 <= 3'b000;
      clkdiv12 <=  ~clkdiv12;
    end
  end
  assign adc_clk =  ~clkdiv12;
  always @(negedge clkdiv12) begin
    rampcounter <= rampcounter + 1;
    //interrupt_counter <= interrupt_counter + 1;
  end
  assign interrupt = fifo_AlmostFull;
  //and (and interrupt_counter);
  fmexg_fifo_8k_1025 fifo(
      .Data(fifo_Data),
    .WrClock(fifo_WrClock),
    .RdClock(fifo_RdClock),
    .WrEn(fifo_WrEn),
    .RdEn(fifo_RdEn),
    .Reset(fifo_Reset),
    .RPReset(fifo_RPReset),
    .Q(fifo_Q),
    .Empty(fifo_Empty),
    .Full(fifo_Full),
    .AlmostEmpty(fifo_AlmostEmpty),
    .AlmostFull(fifo_AlmostFull));
  assign fifo_Q_u = fifo_Q;
  assign fifo_Data = fmexg_mic_sync == 1'b1 ? 12'b100000000000 : adc_data;
  //std_logic_vector(rampcounter); 
  assign fifo_WrClock = clkdiv12;
  assign fifo_RdClock = spi_clk;
  assign fifo_WrEn = 1'b1;
  assign fifo_RdEn = fifo_readclk_en;
  assign fifo_Reset = 1'b0;
  assign fifo_RPReset = 1'b0;
  always @(negedge spi_clk) begin
    if(spi_cs == 1'b0) begin
      two_samples <= {1'b0,two_samples[23:1]};
      // Read new data on second-to-last two rising edges
      if(spi_byte_ctr == 2'b10 && (spi_bit_ctr == 3'b110 || spi_bit_ctr == 3'b111)) begin
        fifo_readclk_en <= 1'b1;
      end
      else begin
        fifo_readclk_en <= 1'b0;
      end
      if(spi_byte_ctr == 2'b10 && spi_bit_ctr == 3'b111) begin
        //Falling edge of second-to-last clock pulse
        //Register first sample of pair
        first_sample <= fifo_Q;
      end
      else if(spi_byte_ctr == 2'b00 && spi_bit_ctr == 3'b000) begin
        //Falling edge of last clock pulse
        //Register two samples, swizzle bits
        //VHDL does NOT allow e.g. a(7 downto 0) <= b(0 to 7) to reverse a vector
        two_samples <= {fifo_Q_u[4],fifo_Q_u[5],fifo_Q_u[6],fifo_Q_u[7],fifo_Q_u[8],fifo_Q_u[9],fifo_Q_u[10],fifo_Q_u[11],first_sample[8],first_sample[9],first_sample[10],first_sample[11],fifo_Q_u[0],fifo_Q_u[1],fifo_Q_u[2],fifo_Q_u[3],first_sample[0],first_sample[1],first_sample[2],first_sample[3],first_sample[4],first_sample[5],first_sample[6],first_sample[7]};
      end
    end
  end
  assign spi_miso = two_samples[0];
  always @(posedge spi_clk, posedge spi_cs) begin
    if(spi_cs == 1'b1) begin
      spi_bit_ctr <= 3'b000;
      spi_byte_ctr <= 2'b00;
    end else begin
      //Increment bit (8) and byte (3) counters
      if(spi_bit_ctr == 3'b111) begin
        if(spi_byte_ctr == 2'b10) begin
          spi_byte_ctr <= 2'b00;
        end
        else begin
