module HexToBCD(
input wire CLK,
input wire [3:0] sw0,
input wire [3:0] sw1,
input wire [3:0] sw2,
input wire [3:0] sw3,
output reg [3:0] bcd0,
output reg [3:0] bcd1,
output reg [3:0] bcd2,
output reg [3:0] bcd3
);
  always @(posedge CLK) begin : P1
    reg [15:0] random = 16'b0000000000000000;
    reg [3:0] one = 4'b0000;
    reg [3:0] ten = 4'b0000;
    reg [3:0] hund = 4'b0000;
    reg [3:0] thou = 4'b0000;
    reg [3:0] tthou = 4'b0000;
    reg [3:0] hthou = 4'b0000;
    random = {sw3,sw2,sw1,sw0};
    for (i=0; i <= 15; i = i + 1) begin
      if((hthou >= 4'b0101)) begin
        hthou = (hthou) + 3;
      end
      if((tthou >= 4'b0101)) begin
        tthou = (tthou) + 3;
      end
      if((thou >= 4'b0101)) begin
        thou = (thou) + 3;
      end
      if((hund >= 4'b0101)) begin
        hund = (hund) + 3;
      end
      if((ten >= 4'b0101)) begin
        ten = (ten) + 3;
      end
      if((one >= 4'b0101)) begin
        one = (one) + 3;
      end
      hthou = {hthou[2:0],tthou[3]};
      tthou = {tthou[2:0],thou[3]};
      thou = {thou[2:0],hund[3]};
      hund = {hund[2:0],ten[3]};
      ten = {ten[2:0],one[3]};
      one = {one[2:0],random[15]};
      random = (random) << 1;
    end
    bcd0 <= one;
    bcd1 <= ten;
    bcd2 <= hund;
    bcd3 <= thou;
    one = 4'b0000;
    ten = 4'b0000;
    hund = 4'b0000;
    thou = 4'b0000;
    tthou = 4'b0000;
    hthou = 4'b0000;
  end
endmodule

module LAB7a(
input wire [3:0] KEY,
output wire [6:0] HEX0,
output wire [9:0] LEDR
);
wire [3:0] QQ; wire [3:0] q;
wire [3:0] F;
  // Inicio da FSM --
  assign QQ[3] = 1'b0;
  assign QQ[2] =  ~(q[3]) &  ~(q[2]) & q[1] & q[0];
  assign QQ[1] = ( ~(q[3]) &  ~(q[2])) & (q[1] ^ q[0]);
  assign QQ[0] = ( ~(q[3]) & q[2] &  ~(q[1])) | ( ~(q[3]) &  ~(q[2]) & q[1] &  ~(q[0]));
  D_4FF L0(
      KEY[1],
    KEY[0],
    QQ[3:0],
    q[3:0]);
  assign F = q;
  // Fim da FSM –
  assign LEDR = {6'b000000,F};
  decod7seg L1(
      F[3:0],
    HEX0);
endmodule

