module hold(
input wire clk,
input wire resetn,
input wire sraz,
input wire input,
output wire output,
output wire holding
);
parameter [31:0] HOLD_TIME=4;
parameter HOLD_LEVEL=1'b1;
reg [nbit[HOLD_TIME] - 1:0] Qp = 1'b0;
reg old_value;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      Qp <= {((nbit[HOLD_TIME] - 1)-(0)+1){1'b0}};
    end else begin
      if(sraz == 1'b1) begin
        Qp <= {((nbit[HOLD_TIME] - 1)-(0)+1){1'b0}};
      end
      else if(Qp == 0) begin
        if(old_value != input && input == HOLD_LEVEL) begin
          Qp <= HOLD_TIME - 1;
        end
        old_value <= input;
      end
      else begin
        Qp <= Qp - 1;
      end
    end
  end
  assign output = Qp == 0 ? input : old_value;
  assign holding = Qp == 0 ? 1'b0 : 1'b1;
endmodule

