output wire accept_o,
output wire [0:127] data_o,
output wire valid_o,
input wire accept_i
);
// low active async reset
// clock
// start cbc
// key input
// data input
// input key/data valid flag
// input accept
// data output
// output data valid flag
// output accept
// CBCMAC must have fix IV for security reasons
parameter C_IV = 1'b0;
