  assign accept_o = s_aes_accept;
  assign valid_o = s_aes_validout;
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_key <= {128{1'b0}};
    end else begin
      if((valid_i == 1'b1 && s_aes_accept == 1'b1 && start_i == 1'b1)) begin
        s_key <= key_i;
      end
    end
  end
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_aes_dataout_d <= {128{1'b0}};
