module wb_traffic_supervision(
input wire clk,
input wire rst_n,
input wire i_bg,
input wire i_ce,
output reg o_traffic_limit
);
parameter [31:0] g_priority;
parameter [31:0] g_tot_priority;
// bus grant
// clock enable
reg [g_tot_priority - 1:0] s_shreg = 1'b0;
reg [31:0] s_cntr;
  // rtl
  // purpose: holds information of usage of latest cycles
  // type   : sequential, no reset, rising clock edge
  always @(posedge clk) begin
      // process shreg
    if((i_ce == 1'b1)) begin
      s_shreg <= {s_shreg[g_tot_priority - 2:0],i_bg};
    end
  end
  // purpose: keeps track of used cycles
  // type   : sequential, rising edge, mixed type reset
  always @(posedge clk, posedge rst_n) begin
      // process counter
    if((rst_n == 1'b0)) begin
      s_cntr <= 0;
      o_traffic_limit <= 1'b0;
    end else begin
      if((i_ce == 1'b1)) begin
        if(((i_bg == 1'b1) && (s_shreg[g_tot_priority - 1] != 1'b1))) begin
          s_cntr <= s_cntr + 1;
          if((s_cntr == (g_priority - 1))) begin
            o_traffic_limit <= 1'b1;
          end
        end
        else if(((i_bg == 1'b0) && (s_shreg[g_tot_priority - 1] == 1'b1))) begin
          s_cntr <= s_cntr - 1;
          if((s_cntr == g_priority)) begin
            o_traffic_limit <= 1'b0;
          end
        end
      end
    end
  end
endmodule

