module nodeController(
input wire clk,
input wire grant,
input wire start,
input wire [1:0] count_in,
input wire [1:0] nodeid,
output reg req,
output reg count_en,
output wire [15:0] data_out
);
//-----------------------------------------------------------------------------
parameter [1:0]
  ready = 0,
  requested = 1,
  granted = 2,
  update = 3;
reg [1:0] state; reg [1:0] next_state;
reg output_enable;
  // architecture arch
  assign data_out = (output_enable == 1'b1) ? {nodeid,1'b1,count_in,6'b000000,nodeid,1'b0,count_in} : {16{1'bZ}};
  always @(posedge clk) begin
    state <= next_state;
  end
  always @(state, start, grant) begin
    case(state)
    ready : begin
      if(start == 1'b1) begin
        next_state <= requested;
      end
      else begin
        next_state <= ready;
      end
    end
    requested : begin
      if((grant == 1'b1)) begin
        next_state <= granted;
      end
      else begin
        next_state <= requested;
      end
    end
    granted : begin
      next_state <= update;
    end
    update : begin
      next_state <= ready;
    end
    endcase
  end
  always @(state) begin
    case(state)
    ready : begin
      req <= 1'b0;
      output_enable <= 1'b0;
      count_en <= 1'b0;
    end
    requested : begin
      req <= 1'b1;
      output_enable <= 1'b0;
      count_en <= 1'b0;
    end
    granted : begin
      req <= 1'b0;
      output_enable <= 1'b1;
      count_en <= 1'b0;
    end
    update : begin
      req <= 1'b0;
      output_enable <= 1'b0;
      count_en <= 1'b1;
    end
    endcase
  end
//-----------------------------------------------------------------------------
endmodule

module CrossClockDomain(
