output reg SyncOut_SO
);
reg clk_sync_0 = 1'b0;
reg clk_sync_1 = 1'b0;
reg clk_sync_2 = 1'b0;
reg clk_sync_3 = 1'b0;
  // architecture RTL
  always @(posedge Clk_CI) begin
      // process sync_clock_domain
    // rising clock edge
    clk_sync_0 <= AsyncIn_SI;
    clk_sync_1 <= clk_sync_0;
    clk_sync_2 <= clk_sync_1;
    clk_sync_3 <= clk_sync_2;
    SyncOut_SO <= clk_sync_3;
