module sram(
input wire clk,
input wire mem,
input wire rw,
output reg ready,
input wire [20:0] addr,
input wire [7:0] din,
output reg [7:0] dout,
output reg [20:0] SRAM_ADDR,
inout reg [7:0] SRAM_DATA,
output wire SRAM_CE,
output reg SRAM_WE,
output reg SRAM_OE
);
// interface
// read '1' / write '0'
// SRAM interface
parameter [2:0]
  idle = 0,
  read1 = 1,
  read2 = 2,
  write1 = 3,
  write2 = 4;
reg [2:0] state = idle;
  assign SRAM_CE = 1'b0;
  // sram always enabled
  //SRAM_OE <= '1';
  always @(posedge clk) begin
    case(state)
    idle : begin
      ready <= 1'b1;
      SRAM_DATA <= 8'bZZZZZZZZ;
      SRAM_WE <= 1'b1;
      SRAM_OE <= 1'b1;
      if(mem == 1'b1) begin
        SRAM_ADDR <= addr;
        if(rw == 1'b1) begin
          state <= read1;
        end
        else begin
          state <= write1;
          SRAM_DATA <= din;
        end
      end
    end
    read1 : begin
      ready <= 1'b0;
      SRAM_OE <= 1'b0;
      state <= read2;
    end
    read2 : begin
      SRAM_OE <= 1'b0;
      dout <= SRAM_DATA;
      state <= idle;
    end
    write1 : begin
      ready <= 1'b0;
      SRAM_WE <= 1'b0;
      state <= write2;
    end
    write2 : begin
      SRAM_DATA <= din;
      state <= idle;
    end
    endcase
  end
endmodule

module signext(
input wire [0:15] a,
output reg [0:31] y
);
  always @(a) begin : P1
    reg [0:31] temp;
    if((a[0] == 1'b0)) begin
      for (i=0; i <= 15; i = i + 1) begin
        temp[i] = 1'b0;
      end
    end
    else if((a[0] == 1'b1)) begin
      for (i=0; i <= 15; i = i + 1) begin
        temp[i] = 1'b1;
      end
    end
    for (i=16; i <= 31; i = i + 1) begin
      temp[i] = a[i - 16];
    end
    y <= temp;
  end
endmodule

module fsm_controller(
