reg [1:0] timer_state = stop2;
  always @(posedge masterReset, posedge buttonDown) begin
    if((masterReset == 1'b1)) begin
      timer_state <= stop2;
      en1 <= 1'b0;
      en2 <= 1'b0;
    end else begin
      case(timer_state)
      stop2 : begin
        en1 <= 1'b1;
        en2 <= 1'b1;
        timer_state <= start;
      end
      start : begin
        en1 <= 1'b0;
        timer_state <= stop1;
      end
      stop1 : begin
        en2 <= 1'b0;
        timer_state <= stop2;
      end
      endcase
    end
  end
endmodule

