module Multiplicador(
input wire [3:0] A,
input wire [3:0] B,
output wire [7:0] Z
);
wire [2:0] CoutVectorNivel1;
wire [2:0] CoutVectorNivel2;
wire [2:0] CoutVectorNivel3;
wire [3:0] auxSomaNivel1;
wire [3:0] auxSomaNivel2;
wire [14:0] auxANDS;
  assign auxANDS[0] = A[1] & B[0];
  assign auxANDS[1] = A[0] & B[1];
  assign auxANDS[2] = A[2] & B[0];
  assign auxANDS[3] = A[1] & B[1];
  assign auxANDS[4] = A[3] & B[0];
  assign auxANDS[5] = A[2] & B[1];
  assign auxANDS[6] = A[3] & B[1];
  assign auxANDS[7] = A[0] & B[2];
  assign auxANDS[8] = A[1] & B[2];
  assign auxANDS[9] = A[2] & B[2];
  assign auxANDS[10] = A[3] & B[2];
  assign auxANDS[11] = A[0] & B[3];
  assign auxANDS[12] = A[1] & B[3];
  assign auxANDS[13] = A[2] & B[3];
  assign auxANDS[14] = A[3] & B[3];
  assign Z[0] = A[0] & B[0];
  // R0
  Somador1bit S1(
      auxANDS[0],
    auxANDS[1],
    1'b0,
    CoutVectorNivel1[0],
    Z[1],
    .p(/* open */),
    .g(/* open */));
  // R1
  Somador1bit S2(
      auxANDS[2],
    auxANDS[3],
    CoutVectorNivel1[0],
    CoutVectorNivel1[1],
    auxSomaNivel1[0],
    .p(/* open */),
    .g(/* open */));
  // Soma parcial do R2 //primeiro nível da soma;
  Somador1bit S3(
      auxANDS[4],
    auxANDS[5],
    CoutVectorNivel1[1],
    CoutVectorNivel1[2],
    auxSomaNivel1[1],
    .p(/* open */),
    .g(/* open */));
  // Somap parcial do R3//primeiro nível de soma;
  Somador1bit S4(
      auxANDS[6],
    1'b0,
    CoutVectorNivel1[2],
    auxSomaNivel1[2],
    auxSomaNivel1[3],
    .p(/* open */),
    .g(/* open */));
  // Soma parcial do R4 e do R5//primeiro nível de soma;
  Somador1bit S5(
      auxANDS[7],
    auxSomaNivel1[0],
    1'b0,
    CoutVectorNivel2[0],
    Z[2],
    .p(/* open */),
    .g(/* open */));
  //R2// segundo nível de soma;
  Somador1Bit S6(
      auxANDS[8],
    auxSomaNivel1[1],
    CoutVectorNivel2[0],
    CoutVectorNivel2[1],
    auxSomaNivel2[0],
    .p(/* open */),
    .g(/* open */));
  //Soma parciel do R3//segundo nível de soma;
  Somador1Bit S7(
      auxANDS[9],
    auxSomaNivel1[2],
    CoutVectorNivel2[1],
    CoutVectorNivel2[2],
    auxSomaNivel2[1],
    .p(/* open */),
    .g(/* open */));
  //Soma parcial do R4//segundo nível de soma;
  Somador1Bit S8(
      auxANDS[10],
    auxSomaNivel1[3],
    CoutVectorNivel2[2],
    auxSomaNivel2[3],
    auxSomaNivel2[2],
    .p(/* open */),
    .g(/* open */));
  //Soma Parcial do R5// segundo nível de soma;
  Somador1Bit S9(
      auxANDS[11],
    auxSomaNivel2[0],
    1'b0,
    CoutVectorNivel3[0],
    Z[3],
    .p(/* open */),
    .g(/* open */));
  //R3//terceiro nível de soma;
  Somador1Bit S10(
      auxANDS[12],
    auxSomaNivel2[1],
    CoutVectorNivel3[0],
    CoutVectorNivel3[1],
    Z[4],
    .p(/* open */),
    .g(/* open */));
  //R4//terceiro nível de soma;
  Somador1Bit S11(
      auxANDS[13],
    auxSomaNivel2[2],
    CoutVectorNivel3[1],
    CoutVectorNivel3[2],
    Z[5],
    .p(/* open */),
    .g(/* open */));
  //R5//terceiro nível de soma;
  Somador1Bit S12(
      auxANDS[14],
    1'b0,
    CoutVectorNivel3[2],
    Z[7],
    Z[6],
    .p(/* open */),
    .g(/* open */));
    //R6 e R7//terceiro nível de soma;
endmodule

