module hw_image_generator(
input wire disp_ena,
input wire [0:9] row,
input wire [0:9] column,
input wire BUTTON_1,
output reg red,
output reg green,
output reg blue
);
parameter [31:0] pixels_x_start=280;
parameter [31:0] pixels_y_start=200;
parameter [31:0] pixels_x_end=360;
parameter [31:0] pixels_y_end=280;
parameter [31:0] pixels_x_start2=360;
parameter [31:0] pixels_y_start2=120;
parameter [31:0] pixels_x_end2=440;
parameter [31:0] pixels_y_end2=200;
parameter [31:0] pixels_x_start3=360;
parameter [31:0] pixels_y_start3=280;
parameter [31:0] pixels_x_end3=440;
parameter [31:0] pixels_y_end3=360;
parameter [31:0] pixels_x_start4=200;
parameter [31:0] pixels_y_start4=120;
parameter [31:0] pixels_x_end4=280;
parameter [31:0] pixels_y_end4=200;
parameter [31:0] pixels_x_start5=200;
parameter [31:0] pixels_y_start5=280;
parameter [31:0] pixels_x_end5=280;
parameter [31:0] pixels_y_end5=360;
// Ja disp_ena = 1, tad radit bildi. Ja 0, tad tukshuma ("blanking") periods.
// Rindas piksela koordinatas
// Kolonnas piksela koordinatas
// pirma poga
// Sarkana krasa
// Zala krasa
// Zila krasa
  always @(disp_ena, row, column, BUTTON_1) begin : P1
    reg [31:0] column_int = column;
  // Tiek salidzinats ar INTEGER
    reg [31:0] row_int = row;
  // vertibu, tapec japarveido uz UNSIGNED INTEGER
    reg [31:0] crossValX = 320;
  // Zilaa krusta rindas un kolonnas koordinatas.
    reg [31:0] crossValY = 240;
    if((disp_ena == 1'b1)) begin
      // Izvades laiks
      if((row_int == crossValX && column_int == crossValY)) begin
        // Izvadit sarkanu punktu pasha ekrana vidu
        red <= 1'b1;
        green <= 1'b0;
        blue <= 1'b0;
      end
      else if((row_int == crossValX)) begin
        // Izvadit zilu punktu katra x=320 piksela koordinata
        red <= 1'b0;
        green <= 1'b0;
        blue <= 1'b1;
      end
      else if((column_int == crossValY)) begin
        // Izvadit zilu punktu katra y = 240 piksela koordinata
        red <= 1'b0;
        green <= 1'b0;
        blue <= 1'b1;
      end
      else if((row_int > pixels_x_start && row_int < pixels_x_end && column_int > pixels_y_start && column_int < pixels_y_end)) begin
        red <= 1'b1;
        // Sarkans kvadrats
        green <= 1'b1;
        blue <= 1'b0;
      end
      else if((row_int > pixels_x_start2 && row_int < pixels_x_end2 && column_int > pixels_y_start2 && column_int < pixels_y_end2)) begin
        red <= 1'b1;
        // Violets kvadrats
        green <= 1'b0;
        blue <= 1'b1;
      end
      else if((row_int > pixels_x_start3 && row_int < pixels_x_end3 && column_int > pixels_y_start3 && column_int < pixels_y_end3)) begin
        red <= 1'b0;
        // Gaishi zils kvadrats
        green <= 1'b1;
        blue <= 1'b1;
      end
      else if((row_int > pixels_x_start4 && row_int < pixels_x_end4 && column_int > pixels_y_start4 && column_int < pixels_y_end4)) begin
        red <= 1'b0;
        // Zals kvadrats
        green <= 1'b1;
        blue <= 1'b0;
      end
      else if((row_int > pixels_x_start5 && row_int < pixels_x_end5 && column_int > pixels_y_start5 && column_int < pixels_y_end5)) begin
        red <= 1'b1;
        // Sarkans kvadrats
        green <= 1'b0;
        blue <= 1'b0;
      end
      else begin
        if((BUTTON_1 == 1'b1)) begin
          // Ja sledzis stavolki "1", tad aiz kvadratiem balts fons.
          red <= 1'b1;
          green <= 1'b1;
          blue <= 1'b1;
        end
        else begin
          red <= 1'b0;
          // Ja sledzis stavokli "0", tad aiz kvadratiem melns fons.
          green <= 1'b0;
          blue <= 1'b0;
        end
      end
    end
    else begin
      red <= 1'b0;
      // "Tukshuma periods"
      green <= 1'b0;
      blue <= 1'b0;
    end
  end
endmodule

