  assign I2C_CMD_EN = IO_INT == 'H190 ? 1'b1 : 1'b0;
  assign I2C_DATA_EN = IO_INT == 'H191 ? 1'b1 : 1'b0;
  assign I2C_RDY_EN = IO_INT == 'H192 ? 1'b1 : 1'b0;
  assign UART_D_EN = IO_INT == 'H198 ? 1'b1 : 1'b0;
  assign UART_S_EN = IO_INT == 'H199 ? 1'b1 : 1'b0;
  assign SONAR_EN = ((IO_INT >= 'H1A0) && (IO_INT < 'H1B7)) ? 1'b1 : 1'b0;
  assign XPOS_EN = IO_INT == 'H1C0 ? 1'b1 : 1'b0;
  assign YPOS_EN = IO_INT == 'H1C1 ? 1'b1 : 1'b0;
  assign TPOS_EN = IO_INT == 'H1C2 ? 1'b1 : 1'b0;
  assign POS_RSTN = IO_INT == 'H1C3 ? 1'b0 : 1'b1;
  assign RIN_EN = IO_INT == 'H1C8 ? 1'b1 : 1'b0;
  assign LIN_EN = IO_INT == 'H1C9 ? 1'b1 : 1'b0;
