wire [71:0] sr_inserted_data = 1'b0;
wire [71:0] scrambled_data = 1'b0;
wire [79:0] before_skew = 1'b0;
wire [79:0] final_data = 1'b0;
parameter delay_index = 8'b11100100;  // 3,2,1,0 for use as a lookup table in the generate loop
  idle_pattern_inserter i_idle_pattern_inserter(
      .clk(symbol_clk),
