module pixel_counter(
input wire clk,
input wire hs,
input wire vs,
input wire vde,
output wire [15:0] pixel_x,
output wire [15:0] pixel_y
);
reg [15:0] x;
reg [15:0] y;
reg hs_prev;
reg vs_prev;
wire hs_rising;
wire vs_rising;
reg visible_row;
  always @(posedge clk) begin
    hs_prev <= hs;
    vs_prev <= vs;
    if((vs_rising == 1'b1)) begin
      // Clear Y count on vsync
      y <= {16{1'b0}};
    end
    else if((hs_rising == 1'b1)) begin
      // Clear X count on hsync
      x <= {16{1'b0}};
      // Clear visible row flag on hsync
      visible_row <= 1'b0;
      if((visible_row == 1'b1)) begin
        // Increment Y count on hsync only if a row was shown
        y <= y + 1;
      end
    end
    else if((vde == 1'b1)) begin
      // Increment the X count on visible video
      x <= x + 1;
      // Raise visible row flag
      visible_row <= 1'b1;
    end
  end
  // Edge Detection
  assign hs_rising = (hs_prev == 1'b0 && HS == 1'b1) ? 1'b1 : 1'b0;
  assign vs_rising = (vs_prev == 1'b0 && VS == 1'b1) ? 1'b1 : 1'b0;
  // Pixel Output
  assign pixel_x = x;
  assign pixel_y = y;
endmodule

module iis_ser(
input wire CLK_100MHZ,
input wire SCLK,
input wire LRCLK,
output wire SDATA,
input wire EN,
input wire [23:0] LDATA,
input wire [23:0] RDATA
);
//gbuf clock
//logic (not used as clk)
//logic (not used as clk)
//bit cntr counts to 25 (not 24) so that it can set sdata to zero after
//the 24th bit has been sent to the receiver
parameter bit_cntr_max = 5'b11001;  //25
parameter [2:0]
  RESET = 0,
  WAIT_LEFT = 1,
  WRITE_LEFT = 2,
  WAIT_RIGHT = 3,
  WRITE_RIGHT = 4;
wire start_left;
wire start_right;
wire write_bit;
reg sclk_d1 = 1'b0;
reg lrclk_d1 = 1'b0;
reg [4:0] bit_cntr = 1'b0;
reg [23:0] ldata_reg = 1'b0;
reg [23:0] rdata_reg = 1'b0;
reg sdata_reg = 1'b0;
reg [2:0] iis_state = RESET;
  always @(posedge CLK_100MHZ) begin
    sclk_d1 <= SCLK;
    lrclk_d1 <= LRCLK;
  end
  //Detect falling edge on LRCLK
  assign start_left = lrclk_d1 &  ~(LRCLK);
  //Detect rising edge on LRCLK
  assign start_right =  ~(lrclk_d1) & LRCLK;
  //Detect falling edge on SCLK
  assign write_bit = sclk_d1 &  ~(SCLK);
  //Next state logic
  always @(posedge CLK_100MHZ) begin
    case(iis_state)
    RESET : begin
      if((EN == 1'b1)) begin
        iis_state <= WAIT_LEFT;
      end
    end
    WAIT_LEFT : begin
      if((EN == 1'b0)) begin
        iis_state <= RESET;
      end
      else if((start_left == 1'b1)) begin
        iis_state <= WRITE_LEFT;
      end
    end
    WRITE_LEFT : begin
      if((EN == 1'b0)) begin
        iis_state <= RESET;
      end
      else if((bit_cntr == bit_cntr_max)) begin
        iis_state <= WAIT_RIGHT;
      end
    end
    WAIT_RIGHT : begin
      if((EN == 1'b0)) begin
        iis_state <= RESET;
      end
      else if((start_right == 1'b1)) begin
        iis_state <= WRITE_RIGHT;
      end
    end
    WRITE_RIGHT : begin
      if((EN == 1'b0)) begin
        iis_state <= RESET;
      end
      else if((bit_cntr == bit_cntr_max)) begin
        iis_state <= WAIT_LEFT;
      end
    end
    default : begin
      //should never be reached
      iis_state <= RESET;
    end
    endcase
  end
  always @(posedge CLK_100MHZ) begin
    if((iis_state == WRITE_RIGHT || iis_state == WRITE_LEFT)) begin
      if((write_bit == 1'b1)) begin
        bit_cntr <= bit_cntr + 1;
      end
    end
    else begin
      bit_cntr <= {5{1'b0}};
    end
  end
  always @(posedge CLK_100MHZ) begin
    if((iis_state == RESET)) begin
      ldata_reg <= {24{1'b0}};
      rdata_reg <= {24{1'b0}};
    end
    else if(((iis_state == WAIT_LEFT) && (start_left == 1'b1))) begin
      ldata_reg <= LDATA;
      rdata_reg <= RDATA;
    end
    else begin
      if((iis_state == WRITE_LEFT && write_bit == 1'b1)) begin
        ldata_reg[23:1] <= ldata_reg[22:0];
        ldata_reg[0] <= 1'b0;
      end
      if((iis_state == WRITE_RIGHT && write_bit == 1'b1)) begin
        rdata_reg[23:1] <= rdata_reg[22:0];
        rdata_reg[0] <= 1'b0;
      end
    end
  end
  always @(posedge CLK_100MHZ) begin
    if((iis_state == RESET)) begin
      sdata_reg <= 1'b0;
    end
    else if((iis_state == WRITE_LEFT && write_bit == 1'b1)) begin
      sdata_reg <= ldata_reg[23];
    end
    else if((iis_state == WRITE_RIGHT && write_bit == 1'b1)) begin
      sdata_reg <= rdata_reg[23];
    end
  end
  assign SDATA = sdata_reg;
endmodule

module rgbctl_gen(
input wire CLK,
input wire RST,
output wire HS,
output wire VS,
output wire DE
);
parameter [31:0] HBP=48;
parameter [31:0] HDP=640;
parameter [31:0] HFP=16;
parameter [31:0] VBP=33;
parameter [31:0] VDP=480;
parameter [31:0] VFP=10;
parameter [31:0] HPULSE=96;
parameter [31:0] VPULSE=2;
parameter HPIXELS = HPULSE + HBP + HDP + HFP;
parameter VLINES = VPULSE + VBP + VDP + VFP;
reg [log2[HPIXELS] - 1:0] cnt_horiz;
wire cnt_horiz_ce;
wire cnt_horiz_o;
reg [log2[VLINES] - 1:0] cnt_vert;
wire cnt_vert_ce;
wire cnt_vert_clr;
wire hdp_active;
wire vdp_active;
wire hpulse_active;
wire vpulse_active;
  assign hdp_active = cnt_horiz >= (HPULSE + HBP) && cnt_horiz < (HPULSE + HBP + HDP) ? 1'b1 : 1'b0;
  assign vdp_active = cnt_vert >= (VPULSE + VBP) && cnt_vert < (VPULSE + VBP + VDP) ? 1'b1 : 1'b0;
  assign hpulse_active = cnt_horiz < HPULSE ? 1'b1 : 1'b0;
  assign vpulse_active = cnt_vert < VPULSE ? 1'b1 : 1'b0;
  assign DE = hdp_active & vdp_active;
  // negative logic:
  assign HS =  ~hpulse_active;
  assign VS =  ~vpulse_active;
  //------------------
  assign cnt_horiz_ce = 1'b1;
  assign cnt_vert_ce = cnt_horiz_o;
  //------------------
  always @(posedge CLK, posedge RST, posedge cnt_horiz_ce) begin
    if(RST == 1'b1) begin
      cnt_horiz <= {((log2[HPIXELS] - 1)-(0)+1){1'b0}};
    end
    else if(cnt_horiz_ce == 1'b1) begin
      if(cnt_horiz == (HPIXELS - 1)) begin
        cnt_horiz <= {((log2[HPIXELS] - 1)-(0)+1){1'b0}};
      end
      else begin
        cnt_horiz <= cnt_horiz + 1;
      end
    end
  end
  assign cnt_horiz_o = cnt_horiz == (HPIXELS - 1) ? 1'b1 : 1'b0;
  //------------------
  always @(posedge CLK, posedge RST, posedge cnt_vert_ce) begin
    if(RST == 1'b1) begin
      cnt_vert <= {((log2[VLINES] - 1)-(0)+1){1'b0}};
    end
    else if(cnt_vert_ce == 1'b1) begin
      if(cnt_vert == (VLINES - 1)) begin
        cnt_vert <= {((log2[VLINES] - 1)-(0)+1){1'b0}};
      end
      else begin
        cnt_vert <= cnt_vert + 1;
      end
    end
  end
endmodule

module freezer(
input wire clock,
input wire reset,
input wire RST_in,
input wire button_freeze,
input wire cpu_cycle_done,
input wire cpu_write,
input wire activate,
output reg [1:0] freezer_state,
input wire unfreeze,
output wire freeze_trig,
output reg freeze_act
);
parameter g_ext_activate=false;
// debug
// could be software driven, or automatic, depending on cartridge
reg reset_in;
reg [31:0] wr_cnt;
reg do_freeze;
reg do_freeze_d;
reg activate_c;
reg activate_d;
parameter [1:0]
  idle = 0,
  triggered = 1,
  enter_freeze = 2,
  button = 3;
reg [1:0] state;
  assign freeze_trig = (state == triggered) ? 1'b1 : 1'b0;
  always @(posedge clock) begin
    activate_c <= activate;
    activate_d <= activate_c;
    do_freeze <= button_freeze;
    do_freeze_d <= do_freeze;
    reset_in <= reset | RST_in;
    if(cpu_cycle_done == 1'b1) begin
      if(cpu_write == 1'b1) begin
        if(wr_cnt != 3) begin
          wr_cnt <= wr_cnt + 1;
        end
      end
      else begin
        wr_cnt <= 0;
      end
    end
    case(state)
    idle : begin
      freeze_act <= 1'b0;
      if(do_freeze_d == 1'b0 && do_freeze == 1'b1) begin
        // push
        state <= triggered;
      end
    end
    triggered : begin
      if(((g_ext_activate & activate_d) == 1'b1) || (( ~g_ext_activate & wr_cnt) == 3)) begin
        state <= enter_freeze;
        freeze_act <= 1'b1;
      end
    end
    enter_freeze : begin
      if(unfreeze == 1'b1) begin
        freeze_act <= 1'b0;
        state <= button;
      end
    end
    button : begin
      if(do_freeze == 1'b0) begin
        // wait until button is not pressed anymore
        state <= idle;
      end
    end
    default : begin
      state <= idle;
    end
    endcase
    if(reset_in == 1'b1) begin
      state <= idle;
      wr_cnt <= 0;
      activate_d <= 1'b0;
    end
  end
  always @(*) begin
    case(state)
      idle : freezer_state <= 2'b00;
      triggered : freezer_state <= 2'b01;
      enter_freeze : freezer_state <= 2'b10;
      button : freezer_state <= 2'b11;
      default : freezer_state <= 2'b00;
    endcase
  end
endmodule

module TM16bits(
input wire wb_clk_i,
input wire wb_rst_i,
input wire [0:0] wb_adr_i,
output wire [7:0] wb_dat_o,
input wire [7:0] wb_dat_i,
input wire wb_we_i,
input wire wb_stb_i,
output wire wb_ack_o,
output reg irq_req_o,
input wire irq_ack_i
);
parameter [31:0] CNT_PRESC=24;
parameter ENA_TMR=1'b1;
// WISHBONE signals
// Clock
// Reset input
// Adress bus
// DataOut Bus
// DataIn Bus
// Write Enable
// Strobe
// Acknowledge
// Interface
// Timer counter
reg [15:0] cnt_r = 1'b0;  // Divider value
reg [15:0] div_r = 1'b0;
wire tc;  // Terminal count
// Microseconds source
wire ena_cnt;
reg [31:0] pre_cnt_r;
  // Microseconds time source
  always @(posedge wb_clk_i) begin
    if(wb_rst_i == 1'b1) begin
      pre_cnt_r <= 0;
    end
    else begin
      pre_cnt_r <= pre_cnt_r + 1;
      if(pre_cnt_r == (CNT_PRESC - 1)) begin
        pre_cnt_r <= 0;
      end
    end
  end
  assign ena_cnt = pre_cnt_r == (CNT_PRESC - 1) ? 1'b1 : 1'b0;
  // 16 bits counter
  always @(posedge wb_clk_i) begin
    if((wb_rst_i | tc | (wb_stb_i & wb_we_i)) == 1'b1) begin
      cnt_r <= {16{1'b0}};
    end
    else if(ena_cnt == 1'b1) begin
      cnt_r <= cnt_r + 1;
    end
  end
  assign tc = cnt_r == (div_r - 1) && ena_cnt == 1'b1 ? 1'b1 : 1'b0;
  // Interrupt logic
  always @(posedge wb_clk_i) begin
    if(wb_rst_i == 1'b1) begin
      irq_req_o <= 1'b0;
    end
    else if(tc == 1'b1 && ENA_TMR == 1'b1) begin
      irq_req_o <= 1'b1;
    end
    else if(irq_ack_i == 1'b1) begin
      irq_req_o <= 1'b0;
    end
  end
  //--------------------------------------------------------------------------
  // WISHBONE read
  //--------------------------------------------------------------------------
  assign wb_dat_o = {8{1'b0}};
  assign wb_ack_o = wb_stb_i;
  //--------------------------------------------------------------------------
  // WISHBONE write
  //--------------------------------------------------------------------------
  always @(posedge wb_clk_i) begin
    if(wb_rst_i == 1'b1) begin
      div_r <= {16{1'b0}};
    end
    else if((wb_stb_i & wb_we_i) == 1'b1) begin
      if(wb_adr_i == 1'b0) begin
        div_r[7:0] <= wb_dat_i;
      end
      else begin
        div_r[15:8] <= wb_dat_i;
      end
    end
  end
// Entity: TM16bits
endmodule

