module WDT_MOD(
input wire WB_CLK,
input wire WB_RST,
input wire [15:2] WB_ADDR,
output reg [31:0] WB_DATA_OUT,
input wire [31:0] WB_DATA_IN,
input wire WB_STB_RD,
input wire WB_STB_WR,
output wire RUN,
output wire OUT_EN
);
// IO-REQ: 1 DWORD
parameter [15:2] WB_CONF_OFFSET=14'b00000000000000;
parameter [15:0] WB_CONF_DATA=16'b0000000000000001;
parameter [15:2] WB_ADDR_OFFSET=14'b00000000000000;
parameter RAND_SEED = 16'b1111111111111000;
reg [31:0] wb_data_mux;
reg [15:0] rand = RAND_SEED;
reg rand_ok;
reg out_en_reg;
reg [19:0] timer;
wire timeout;
reg [3:0] cycle_cnt = 1'b1;
wire cycle_ok;
  //--------------------------------------------------------
  //- bus logic
  //--------------------------------------------------------
  always @(WB_ADDR) begin
    case(WB_ADDR)
    WB_CONF_OFFSET : begin
      wb_data_mux[15:0] <= WB_CONF_DATA;
      wb_data_mux[31:16] <= {WB_ADDR_OFFSET,2'b00};
    end
    WB_ADDR_OFFSET : begin
      wb_data_mux <= {32{1'b0}};
      wb_data_mux[15:0] <= rand;
      wb_data_mux[16] <= out_en_reg;
    end
    default : begin
      wb_data_mux <= {32{1'b0}};
    end
    endcase
  end
  always @(posedge WB_RST, posedge WB_CLK) begin
    if(WB_RST == 1'b1) begin
      WB_DATA_OUT <= {32{1'b0}};
    end else begin
      if(WB_STB_RD == 1'b1) begin
        WB_DATA_OUT <= wb_data_mux;
      end
    end
  end
  always @(posedge WB_RST, posedge WB_CLK) begin
    if(WB_RST == 1'b1) begin
      out_en_reg <= 1'b0;
      rand <= RAND_SEED;
      rand_ok <= 1'b0;
    end else begin
      rand_ok <= 1'b0;
      if(WB_STB_WR == 1'b1) begin
        case(WB_ADDR)
        WB_ADDR_OFFSET : begin
          out_en_reg <= WB_DATA_IN[16];
          if((WB_DATA_IN[15:0] == rand)) begin
            rand_ok <= 1'b1;
          end
          rand <= {rand[14:0],rand[15] ^ rand[10]};
        end
        default : begin
        end
        endcase
      end
    end
  end
  //--------------------------------------------------------
  //- watchdog
  //--------------------------------------------------------
  // Timeout
  always @(posedge WB_RST, posedge WB_CLK) begin
    if(WB_RST == 1'b1) begin
      timer <= {20{1'b0}};
    end else begin
      if(rand_ok == 1'b1) begin
        timer <= {20{1'b1}};
      end
      else if(timeout == 1'b0) begin
        timer <= timer - 1;
      end
    end
  end
  assign timeout = timer == 0 ? 1'b1 : 1'b0;
  // initial cycle counter
  always @(posedge WB_RST, posedge WB_CLK) begin
    if(WB_RST == 1'b1) begin
      cycle_cnt <= {4{1'b1}};
    end else begin
      if(timeout == 1'b1) begin
        cycle_cnt <= {4{1'b1}};
      end
      else if(rand_ok == 1'b1 && cycle_ok == 1'b0) begin
        cycle_cnt <= cycle_cnt - 1;
      end
    end
  end
  assign cycle_ok = cycle_cnt == 0 ? 1'b1 : 1'b0;
  // set outputs
  assign RUN = cycle_ok;
  assign OUT_EN = out_en_reg & cycle_ok;
endmodule

