module FL(
input wire [0:63] fl_in,
input wire [0:63] fli_in,
input wire [0:63] fl_k,
input wire [0:63] fli_k,
output wire [0:63] fl_out,
output wire [0:63] fli_out
);
wire [0:31] fl_a1;
wire [0:31] fl_a2;
wire [0:31] fl_b1;
wire [0:31] fl_b2;
wire [0:31] fli_a1;
wire [0:31] fli_a2;
wire [0:31] fli_b1;
wire [0:31] fli_b2;
  //FL function
  assign fl_a1 = fl_in[0:31] & fl_k[0:31];
  assign fl_a2 = ({fl_a1[1:31],fl_a1[0]}) ^ fl_in[32:63];
  assign fl_b1 = fl_a2 | fl_k[32:63];
  assign fl_b2 = fl_in[0:31] ^ fl_b1;
  assign fl_out = {fl_b2,fl_a2};
  //FL^-1 function
  assign fli_a1 = fli_in[32:63] | fli_k[32:63];
  assign fli_a2 = fli_in[0:31] ^ fli_a1;
  assign fli_b1 = fli_a2 & fli_k[0:31];
  assign fli_b2 = ({fli_b1[1:31],fli_b1[0]}) ^ fli_in[32:63];
  assign fli_out = {fli_a2,fli_b2};
endmodule

