  always @(*) begin
    case(reset_n)
      1'b1 : r_addr_inst <= pc;
      default : r_addr_inst <= start_address;
    endcase
  end
  always @(posedge clk, posedge reset_n, posedge start_address) begin
    if((reset_n == 1'b0)) begin
      pc <= start_address;
      next_pc <= (start_address) + (3);
    end else begin
      if((stall == 1'b0)) begin
        if((cbranch == 1'b1)) begin
          pc <= cbranch_addr;
          next_pc <= (cbranch_addr) + (3);
        end
        else if((ubranch == 1'b1)) begin
          pc <= ubranch_addr;
          next_pc <= (ubranch_addr) + (3);
        end
        else begin
          pc <= (pc) + (3);
          next_pc <= (pc) + (6);
        end
      end
      else begin
        //hold previous value on stall (automatic)
      end
    end
  end
endmodule

