input wire down,
output wire [3:0] count
);
// Contador de um algarismo decimal com entrada de clock, reset, up e down
reg [3:0] s_count;
  always @(posedge clk) begin
    if((!(s_count[0] == 1'b0) && !(s_count[0] == 1'b1))) begin
      s_count <= {4{1'b0}};
    end
    else if((reset == 1'b1)) begin
      s_count <= {4{1'b0}};
    end
    else if((up == 1'b1)) begin
      if((s_count == 4'b1001)) begin
        s_count <= {4{1'b0}};
      end
      else begin
        s_count <= s_count + 1;
      end
    end
    else if((down == 1'b1)) begin
      if((s_count == 4'b0000)) begin
        s_count <= 4'b1001;
      end
      else begin
        s_count <= s_count - 1;
      end
    end
    else begin
      s_count <= s_count;
    end
  end
  assign count = s_count;
endmodule

