module memtable(
input wire clk,
input wire rst,
input wire [31:0] instaddr,
output reg [31:0] instout,
input wire wen,
input wire [31:0] addr,
input wire [31:0] din,
output reg [31:0] dout,
input wire extwen,
input wire [31:0] extaddr,
input wire [31:0] extdin,
output reg [31:0] extdout
);
parameter msize = 16383;  //word size
reg [31:0] MT[0:msize];
  always @(posedge clk, posedge rst) begin : P4
    reg [31:0] addri, extaddri;
    if(rst == 1'b1) begin
      for (i=0; i <= msize; i = i + 1) begin
        MT[i] <= {1{1'b0}};
      end
    end else begin
      if(wen == 1'b1) begin
        addri = addr[31:2];
        if(addri >= 0 && addri <= msize) begin
          MT[addri] <= din;
        end
      end
      if(extwen == 1'b1) begin
        extaddri = extaddr[31:2];
        if(extaddri >= 0 && extaddri <= msize) begin
          MT[extaddri] <= extdin;
        end
      end
    end
  end
  always @(addr, MT) begin : P3
    reg [31:0] addri;
    dout <= {32{1'b0}};
    addri = addr[31:2];
    if(addri >= 0 && addri <= msize) begin
      dout <= MT[addri];
    end
  end
  always @(instaddr, MT) begin : P2
    reg [31:0] addri;
    instout <= {32{1'b0}};
    addri = instaddr[31:2];
    if(addri >= 0 && addri <= msize) begin
      instout <= MT[addri];
    end
  end
  always @(extaddr, MT) begin : P1
    reg [31:0] extaddri;
    extdout <= {32{1'b0}};
    extaddri = extaddr[31:2];
    if(extaddri >= 0 && extaddri <= msize) begin
      extdout <= MT[extaddri];
    end
  end
endmodule

module SEE_det(
input wire clk,
input wire rst,
input wire data0,
input wire data1,
output wire EGDE,
output wire F_EGDE,
output wire EOP
);
// data0 = data+, data1 = data-
// general egde for everything
// falling egde for starting condition
// end of packet dtection
reg cur_EOP; wire nxt_EOP;
reg cur_EGDE; wire nxt_EGDE;
reg cur_FEGDE; wire nxt_FEGDE;  // flip flop all output signals
reg d1; reg d2;  // input edge detection flip-flop
  assign EGDE = cur_EGDE;
  assign F_EGDE = cur_FEGDE;
  assign EOP = cur_EOP;
  always @(posedge clk, posedge rst) begin : P1
  // overall process for clock
    if(rst == 1'b0) begin
      cur_EOP <= 1'b0;
      cur_EGDE <= 1'b0;
      cur_FEGDE <= 1'b0;
      d1 <= 1'b1;
      d2 <= 1'b1;
    end else begin
      d1 <= data0;
      d2 <= d1;
      cur_EOP <= nxt_EOP;
      cur_EGDE <= nxt_EGDE;
      cur_FEGDE <= nxt_FEGDE;
    end
  end
  assign nxt_EGDE = rst == 1'b1 ? d1 ^ d2 : 1'b0;
  // edge detection, for re-synchronizing signals
  assign nxt_FEGDE = rst == 1'b1 ? d2 & ( ~d1) : 1'b0;
  // falling edge only
  assign nxt_EOP = rst == 1'b1 ?  ~(data0 | data1) : 1'b0;
    // since USB will not keep sending EOP, so a combinational will be sufficient.
endmodule

module vga_sync(
input wire clk,
input wire reset,
output wire hsync,
output wire vsync,
output wire video_on,
output wire p_tick,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y
);
// VGA 640-by-480 sync parameters
parameter HD = 639;  //horizontal display area
parameter HF = 16;  //h. front porch
parameter HB = 48;  //h. back porch
parameter HR = 96;  //h. retrace
parameter VD = 479;  //vertical display area
parameter VF = 10;  //v. front porch
parameter VB = 33;  //v. back porch
parameter VR = 2;  //v. retrace
parameter THREE = 2'b11;  // sync counters
reg [9:0] v_count_reg; reg [9:0] v_count_next;
reg [9:0] h_count_reg; reg [9:0] h_count_next;  // output buffer
reg v_sync_reg; reg h_sync_reg;
wire v_sync_next; wire h_sync_next;  // status signal
wire h_end; wire v_end; wire pixel_tick;
reg [1:0] count_3;
  // registers
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      v_count_reg <= {10{1'b0}};
      h_count_reg <= {10{1'b0}};
      v_sync_reg <= 1'b1;
      h_sync_reg <= 1'b1;
    end else begin
      v_count_reg <= v_count_next;
      h_count_reg <= h_count_next;
      v_sync_reg <= v_sync_next;
      h_sync_reg <= h_sync_next;
    end
  end
  // circuit to generate 25 MHz enable tick
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      count_3 <= {2{1'b0}};
    end else begin
      count_3 <= count_3 + 1;
    end
  end
  // 25 MHz pixel tick
  assign pixel_tick = count_3 == THREE ? 1'b1 : 1'b0;
  // status
  assign h_end = h_count_reg == (HD + HF + HB + HR - 1) ? 1'b1 : 1'b0;
  assign v_end = v_count_reg == (VD + VF + VB + VR - 1) ? 1'b1 : 1'b0;
