module ps2(
input wire clk,
input wire rst,
input wire PS2_CLK,
input wire PS2_DATA,
output wire [7:0] char,
output reg rx_done
);
parameter [2:0]
  Start = 0,
  Data = 1,
  Parity = 2,
  Stop = 3,
  Ack = 4;
reg [2:0] p = Start; reg [2:0] pin = Start;
reg [7:0] s; reg [7:0] sin;
reg [31:0] n; reg [31:0] nin;
reg [7:0] f; wire [7:0] fin;
reg t; wire tin;
wire fall_edge;
  //---------------------------------------------------------------------------
  // Input Signal Debounce                                                   --
  //---------------------------------------------------------------------------
  // the frequency of the PS2 clock signal is about 20 to 30 KHz. To avoid   --
  // undesired glitches, wait 8 cycles for a stable signal.                  --
  //---------------------------------------------------------------------------
  assign fin = {PS2_CLK,f[7:1]};
  assign tin = f == 8'hFF ? 1'b1 : f == 8'h00 ? 1'b0 : t;
  always @(posedge clk) begin
    f <= fin;
    t <= tin;
  end
  assign fall_edge = t & ( ~tin);
  //---------------------------------------------------------------------------
  // PS2 Read                                                               --
  //---------------------------------------------------------------------------
  always @(p, s, n, fall_edge, PS2_DATA) begin
    rx_done <= 1'b0;
    pin <= p;
    sin <= s;
    nin <= n;
    case(p)
        // Wait for first falling edge. The first bit is a start bit with
    // value '0'. We do not check that.
    Start : begin
      if(fall_edge == 1'b1) begin
        nin <= 0;
        pin <= Data;
      end
      // On the next 8 falling edges we shuffle data into the shift register.
      // The keyboard sends the LSB first.
    end
    Data : begin
      if(fall_edge == 1'b1) begin
        sin <= {PS2_DATA,s[7:1]};
        if(n == 7) begin
          pin <= Parity;
        end
        else begin
          nin <= n + 1;
        end
      end
      // Fetch odd parity bit. No parity check here.
    end
    Parity : begin
      if(fall_edge == 1'b1) begin
        sin <= {PS2_DATA,s[7:1]};
        // A mystery.
        pin <= Stop;
      end
      // Fetch stop bit. Always '1'.
    end
    Stop : begin
      if(fall_edge == 1'b1) begin
        pin <= Ack;
      end
      // One cycle tick to indicate a complete reception.
    end
    Ack : begin
      rx_done <= 1'b1;
      pin <= Start;
    end
    endcase
  end
  always @(posedge clk) begin
    p <= pin;
    s <= sin;
    n <= nin;
    f <= fin;
    if(rst == 1'b1) begin
      p <= Start;
    end
  end
  assign char = s;
endmodule

