      s_counter <= s_counter + 1;
    end
    else if((s_counter == (K - 1))) begin
      clkOut <= 1'b0;
      s_counter <= 0;
    end
    else begin
      s_counter <= s_counter + 1;
    end
  end
endmodule

module ASCII_BUFFER(
input wire [7:0] ASCII_DATA,
input wire ASCII_RD,
input wire ASCII_WE,
input wire CLK,
input wire RST,
output reg [15:0] ASCII_BUFF
);
parameter [2:0]
  init = 0,
  idle = 1,
  VALID_KEY = 2,
  SPECIAL_KEY = 3,
  BACKSPACE = 4,
  FLUSH = 5;
reg [2:0] STATE = init;
reg [31:0] ram_addr;
reg [3:0] ram[0:4];
reg [3:0] KEY;
reg [15:0] INST = 1'b0;
  always @(*) begin
    case(ASCII_DATA)
      8'h66 : KEY <= 4'hf;
      8'h65 : KEY <= 4'he;
      8'h64 : KEY <= 4'hd;
      8'h63 : KEY <= 4'hc;
      8'h62 : KEY <= 4'hb;
      8'h61 : KEY <= 4'ha;
      8'h46 : KEY <= 4'hF;
      8'h45 : KEY <= 4'hE;
      8'h44 : KEY <= 4'hD;
      8'h43 : KEY <= 4'hC;
      8'h42 : KEY <= 4'hB;
      8'h41 : KEY <= 4'hA;
      8'h39 : KEY <= 4'h9;
      8'h38 : KEY <= 4'h8;
      8'h37 : KEY <= 4'h7;
      8'h36 : KEY <= 4'h6;
      8'h35 : KEY <= 4'h5;
      8'h34 : KEY <= 4'h4;
      8'h33 : KEY <= 4'h3;
      8'h32 : KEY <= 4'h2;
      8'h31 : KEY <= 4'h1;
      8'h30 : KEY <= 4'h0;
      default : KEY <= 4'h0;
    endcase
  end
  // Null
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      STATE <= init;
    end else begin
      case(STATE)
      init : begin
        ASCII_BUFF <= {16{1'b0}};
        ram[0] <= 4'h0;
        ram[1] <= 4'h0;
        ram[2] <= 4'h0;
        ram[3] <= 4'h0;
        ram_addr <= 0;
        state <= idle;
      end
      idle : begin
        ASCII_BUFF <= INST;
        if(ASCII_RD == 1'b1 && ASCII_WE == 1'b1) begin
          state <= VALID_KEY;
          // A Valid key was pressed
        end
        else if(ASCII_RD == 1'b1 && ASCII_WE == 1'b0) begin
          state <= SPECIAL_KEY;
          //Special key was pressed
        end
        else begin
          state <= idle;
        end
      end
      VALID_KEY : begin
        if(ram_addr < 4) begin
          ram[ram_addr] <= key;
          ram_addr <= ram_addr + 1;
        end
        else begin
          ram_addr <= 4;
        end
        state <= idle;
      end
      SPECIAL_KEY : begin
        if(ASCII_DATA == 8'h0D) begin
          //0D = enterkey
          state <= FLUSH;
        end
        else if(ASCII_DATA == 8'h08) begin
          // 08 = backspace
          state <= BACKSPACE;
        end
        else begin
          state <= idle;
        end
      end
      BACKSPACE : begin
        if(ram_addr > 0) begin
          ram_addr <= ram_addr - 1;
        end
        ram[ram_addr] <= 4'h0;
        state <= idle;
      end
      FLUSH : begin
        INST <= {ram[0],ram[1],ram[2],ram[3]};
        state <= init;
      end
      default : begin
        state <= idle;
      end
      endcase
    end
  end
endmodule

