module top_module(
input wire clk_i,
input wire locked_i,
output wire [7:0] blink_o
);
// Constant declaration
parameter c_blink_num_pins = 8;
parameter c_counter_width = 4;  // Global clock and reset signals
//signal s_locked 				: std_logic;
wire clk_sys_rstn;  // Only one clock domain
wire [0:0] reset_clks;
wire [0:0] reset_rstn;  // Global Clock Single ended
wire clk_sys;  // Counter signal
reg [c_counter_width - 1:0] s_counter;
parameter s_counter_full = 4;
reg [c_blink_num_pins - 1:0] s_blink;
  // Reset synchronization
  gc_reset #(
      .g_logdelay(1),
    .g_syncdepth(2))
  cmp_reset(
      .free_clk_i(clk_sys),
    .locked_i(locked_i),
    .clks_i(reset_clks),
    .rstn_o(reset_rstn));
  // Simulation only
  assign clk_sys = clk_i;
  // End of simulation only!
  assign reset_clks[0] = clk_sys;
  assign clk_sys_rstn = reset_rstn[0];
  always @(posedge clk_sys) begin
    if(clk_sys_rstn == 1'b0) begin
      s_counter <= {((c_counter_width - 1)-(0)+1){1'b0}};
      s_blink <= 8'h01;
    end
    else begin
      if((s_counter == (s_counter_full - 1))) begin
        s_counter <= {((c_counter_width - 1)-(0)+1){1'b0}};
        s_blink <= {s_blink[c_blink_num_pins - 2:0],s_blink[c_blink_num_pins - 1]};
      end
      else begin
        s_counter <= s_counter + 1;
      end
    end
  end
  assign blink_o = s_blink;
endmodule

