module uart_tx(
input wire clock_i,
input wire reset_i,
input wire [15:0] baud_i,
input wire [1:0] char_len_i,
input wire stop_bits_i,
input wire [1:0] parity_i,
input wire hwflux_i,
input wire break_i,
input wire [7:0] data_i,
input wire tx_empty_i,
output reg fifo_rd_o,
input wire cts_n_i,
output wire txd_o
);
parameter [2:0]
  stIdle = 0,
  stLoad = 1,
  stLoad2 = 2,
  stStart = 3,
  stData = 4,
  stParity = 5,
  stStop2 = 6,
  stStop1 = 7;
reg [2:0] state_s;
reg [1:0] parity_cfg_s = 1'b0;
reg stop_bits_s = 1'b0;
reg [31:0] baudr_cnt_q = 0;
reg [31:0] max_cnt_s = 0;
reg [31:0] bit_cnt_q = 0;
reg [3:0] bitmax_s = 1'b0;
wire [2:0] bitmask_s;
reg [7:0] shift_q;
reg tx_s = 1'b1;
reg [7:0] datapar_s;
wire parity_s;
  assign bitmask_s = char_len_i == 2'b00 ? 3'b000 : char_len_i == 2'b01 ? 3'b001 : char_len_i == 2'b10 ? 3'b011 : 3'b111;
  // 8 bits
  assign parity_s = parity_cfg_s[1] ^ datapar_s[7] ^ datapar_s[6] ^ datapar_s[5] ^ datapar_s[4] ^ datapar_s[3] ^ datapar_s[2] ^ datapar_s[1] ^ datapar_s[0];
  // Main process
  always @(posedge clock_i) begin
    if(reset_i == 1'b1) begin
      baudr_cnt_q <= 0;
      shift_q <= {8{1'b1}};
      tx_s <= 1'b1;
      bit_cnt_q <= 0;
      state_s <= stIdle;
    end
    else begin
      fifo_rd_o <= 1'b0;
      case(state_s)
      stIdle : begin
        if(tx_empty_i == 1'b0) begin
          if(hwflux_i == 1'b0 || cts_n_i == 1'b0) begin
            fifo_rd_o <= 1'b1;
            state_s <= stLoad;
          end
        end
      end
      stLoad : begin
        baudr_cnt_q <= 0;
        bit_cnt_q <= 0;
        bitmax_s <= (4) + (char_len_i);
        max_cnt_s <= baud_i;
        parity_cfg_s <= parity_i;
        stop_bits_s <= stop_bits_i;
        state_s <= stLoad2;
      end
      stLoad2 : begin
        tx_s <= 1'b0;
        // Start bit
        shift_q <= data_i;
        datapar_s[7:5] <= data_i[7:5] & bitmask_s;
        datapar_s[4:0] <= data_i[4:0];
        state_s <= stStart;
      end
      stStart : begin
        if(baudr_cnt_q >= max_cnt_s) begin
          baudr_cnt_q <= 0;
          tx_s <= shift_q[0];
          shift_q <= {1'b1,shift_q[7:1]};
          state_s <= stData;
        end
        else begin
          baudr_cnt_q <= baudr_cnt_q + 1;
        end
      end
      stData : begin
        if(baudr_cnt_q >= max_cnt_s) begin
          baudr_cnt_q <= 0;
          tx_s <= shift_q[0];
          shift_q <= {1'b1,shift_q[7:1]};
          if(bit_cnt_q >= bitmax_s) begin
            if(parity_cfg_s != 2'b00) begin
              tx_s <= parity_s;
              state_s <= stParity;
            end
            else begin
              tx_s <= 1'b1;
              if(stop_bits_s == 1'b0) begin
                state_s <= stStop1;
              end
              else begin
                state_s <= stStop2;
              end
            end
          end
          else begin
            bit_cnt_q <= bit_cnt_q + 1;
          end
        end
        else begin
          baudr_cnt_q <= baudr_cnt_q + 1;
        end
      end
      stParity : begin
        if(baudr_cnt_q >= max_cnt_s) begin
          baudr_cnt_q <= 0;
          tx_s <= 1'b1;
          if(stop_bits_s == 1'b0) begin
            state_s <= stStop1;
          end
          else begin
            state_s <= stStop2;
          end
        end
        else begin
          baudr_cnt_q <= baudr_cnt_q + 1;
        end
      end
      stStop2 : begin
        if(baudr_cnt_q >= max_cnt_s) begin
          baudr_cnt_q <= 0;
          state_s <= stStop1;
        end
        else begin
          baudr_cnt_q <= baudr_cnt_q + 1;
        end
      end
      stStop1 : begin
        if(baudr_cnt_q >= (max_cnt_s - 3)) begin
          baudr_cnt_q <= 0;
          state_s <= stIdle;
        end
        else begin
          baudr_cnt_q <= baudr_cnt_q + 1;
        end
      end
      endcase
    end
  end
  assign txd_o = tx_s &  ~break_i;
endmodule

