module memctrl(
input wire CLK,
input wire RESET,
input wire [19:0] MEM_A,
input wire [7:0] MEM_DI,
output reg [7:0] MEM_DO,
input wire MEM_RW,
input wire MEM_REQ,
output reg MEM_ACK,
output reg [17:0] SRAM_A,
inout wire [15:0] SRAM_D,
output reg SRAM_CE0,
output reg SRAM_CE1,
output reg SRAM_OE,
output reg SRAM_WE,
output reg SRAM_UB,
output reg SRAM_LB
);
reg [15:0] SRAM_DI;
wire [15:0] SRAM_DO;  // STATEMACHINE   
parameter [2:0]
  IDLE = 0,
  READ1 = 1,
  WRITE1 = 2,
  WRITE2 = 3,
  DONE = 4;
reg [2:0] STATE = IDLE;
  assign SRAM_D = SRAM_DI;
  assign SRAM_DO = SRAM_D;
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      SRAM_A <= {18{1'b0}};
      SRAM_DI <= {16{1'bZ}};
      SRAM_CE0 <= 1'b1;
      SRAM_CE1 <= 1'b1;
      SRAM_OE <= 1'b1;
      SRAM_WE <= 1'b1;
      SRAM_UB <= 1'b1;
      SRAM_LB <= 1'b1;
      MEM_DO <= 8'b11111111;
      MEM_ACK <= 1'b0;
    end
    else begin
      MEM_ACK <= 1'b0;
      case(STATE)
      IDLE : begin
        if(MEM_REQ == 1'b1) begin
          SRAM_A <= MEM_A[18:1];
          if(MEM_A[19] == 1'b0) begin
            SRAM_CE0 <= 1'b0;
          end
          else begin
            SRAM_CE1 <= 1'b0;
          end
          if(MEM_A[0] == 1'b0) begin
            SRAM_LB <= 1'b0;
          end
          else begin
            SRAM_UB <= 1'b0;
          end
          if(MEM_RW == 1'b0) begin
            SRAM_OE <= 1'b0;
            STATE <= READ1;
          end
          else begin
            SRAM_DI <= {MEM_DI,MEM_DI};
            SRAM_WE <= 1'b0;
            STATE <= WRITE1;
          end
        end
      end
      READ1 : begin
        if(MEM_A[0] == 1'b0) begin
          MEM_DO <= SRAM_DO[7:0];
        end
        else begin
          MEM_DO <= SRAM_DO[15:8];
        end
        SRAM_LB <= 1'b1;
        SRAM_UB <= 1'b1;
        SRAM_CE0 <= 1'b1;
        SRAM_CE1 <= 1'b1;
        SRAM_OE <= 1'b1;
        MEM_ACK <= 1'b1;
        STATE <= DONE;
      end
      WRITE1 : begin
        SRAM_CE0 <= 1'b1;
        SRAM_CE1 <= 1'b1;
        SRAM_WE <= 1'b1;
        STATE <= WRITE2;
      end
      WRITE2 : begin
        SRAM_DI <= {16{1'bZ}};
        MEM_ACK <= 1'b1;
        STATE <= DONE;
      end
      DONE : begin
        STATE <= IDLE;
      end
      default : begin
        STATE <= IDLE;
      end
      endcase
    end
  end
endmodule

