module CARRY_SELECT_ADDER(
input wire [31:0] A,
input wire [31:0] B,
output wire [31:0] S,
input wire Ci,
output wire Co
);
wire [8:0] CARRY;
  genvar i;
  generate for (i=0; i <= 7; i = i + 1) begin: RCA_GENERATE
      CARRY_SELECT_BLOCK #(
          .N(4))
    CSB(
          .A(A[(i * 4) + 3:i * 4]),
      .B(B[(i * 4) + 3:i * 4]),
      .S(S[(i * 4) + 3:i * 4]),
      .Ci(CARRY[i]),
      .Co(CARRY[i + 1]));
  end
  endgenerate
  assign CARRY[0] = Ci;
  assign Co = CARRY[8];
endmodule

