module clk_gen(
input wire clk_50M,
input wire reset,
input wire enable,
input wire [15:0] count_max,
output wire [15:0] count_bd,
input wire rst_count_bd
);
reg [15:0] count_bd_s;
reg rst_count_bd_dl;
  always @(posedge clk_50M, posedge reset) begin
    if(reset == 1'b0) begin
      count_bd_s <= 16'h0000;
    end else begin
      if(enable == 1'b1) begin
        rst_count_bd_dl <= rst_count_bd;
        if((rst_count_bd == 1'b1 && rst_count_bd_dl == 1'b0) || count_bd_s == count_max) begin
          //--- Reset the counter only when it reaches the max count defined by baud rate
          count_bd_s <= 16'h0000;
          //--- or when a reset is asked by UART blocks
        end
        else begin
          count_bd_s <= count_bd_s + 1;
        end
      end
    end
  end
  assign count_bd = count_bd_s;
endmodule

module reset_ctrl(
input wire I_clk,
input wire I_reset,
input wire I_reset_inv,
output reg O_reset
);
// input for "active high" reset signal
// input for "active low" reset signal
// reset output, "active high"
reg [31:0] clockcounter = 15;
  always @(posedge I_clk) begin
    O_reset <= 1'b0;
    if(clockcounter != 0) begin
      O_reset <= 1'b1;
      clockcounter <= clockcounter - 1;
    end
    if(I_reset == 1'b1 || I_reset_inv == 1'b0) begin
      clockcounter <= 15;
    end
  end
endmodule

module reset_controller(
input wire clk125mhz,
output reg phy_ready,
output reg eth_rst_b
);
reg [24:0] reset_counter = 1'b0;
  always @(posedge clk125MHz) begin
    if(reset_counter[(24)] == 1'b0) begin
      reset_counter <= reset_counter + 1;
    end
    eth_rst_b <= reset_counter[(24)] | reset_counter[(24) - 1];
    phy_ready <= reset_counter[(24)];
  end
endmodule

