module add_210(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module Bin7SegDecoderH(
input wire enable,
input wire [3:0] binInput,
output wire [6:0] decOut_n
);
reg [6:0] s_decOut_n;
  always @(*) begin
    case(binInput)
      4'b0001 : s_decOut_n <= 7'b1111001;
  //1
      4'b0010 : s_decOut_n <= 7'b0100100;
  //2
      4'b0011 : s_decOut_n <= 7'b0110000;
  //3
      4'b0100 : s_decOut_n <= 7'b0011001;
  //4
      4'b0101 : s_decOut_n <= 7'b0010010;
  //5
      4'b0110 : s_decOut_n <= 7'b0000010;
  //6
      4'b0111 : s_decOut_n <= 7'b1111000;
  //7
      4'b1000 : s_decOut_n <= 7'b0000000;
  //8
      4'b1001 : s_decOut_n <= 7'b0010000;
  //9
      4'b1010 : s_decOut_n <= 7'b0001000;
  //A
      4'b1011 : s_decOut_n <= 7'b0000011;
  //b
      4'b1100 : s_decOut_n <= 7'b1000110;
  //C
      4'b1101 : s_decOut_n <= 7'b0100001;
  //d
      4'b1110 : s_decOut_n <= 7'b0000110;
  //E
      4'b1111 : s_decOut_n <= 7'b0001110;
  //F
      default : s_decOut_n <= 7'b1111111;
    endcase
  end
  //0
  assign decOut_n = (enable == 1'b1) ? s_decOut_n : 7'b1111111;
endmodule

